def _load_manifest(root: Path, findings: list[Finding]) -> dict[str, Any] | None:
    path = root / MANIFEST_NAME
    if not path.exists():
        findings.append(
            _finding(
                "P1",
                "workflow",
                "managed-manifest",
                "Managed workflow manifest is missing, so workflow conformance cannot be verified.",
                MANIFEST_NAME,
            )
        )
        return None
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError) as exc:
        findings.append(
            _finding("P1", "workflow", "managed-manifest", "Manifest is invalid.", str(exc))
        )
        return None
    if not isinstance(value, dict) or not isinstance(value.get("managed_components"), dict):
        findings.append(
            _finding(
                "P1",
                "workflow",
                "managed-manifest",
                "Manifest does not contain a managed-components mapping.",
                MANIFEST_NAME,
            )
        )
        return None
    catalog_path = root / ".astack/components.json"
    try:
        catalog = json.loads(catalog_path.read_text(encoding="utf-8"))
        entries = catalog["components"]
        expected = {str(entry["id"]): str(entry["target"]) for entry in entries}
        expected["runtime.version"] = ".astack/version"
    except (OSError, json.JSONDecodeError, KeyError, TypeError) as exc:
        findings.append(
            _finding(
                "P1",
                "workflow",
                "managed-manifest",
                "The installed component catalog is invalid.",
                str(exc),
            )
        )
        return None
    components = value["managed_components"]
    managed_files: dict[str, str] = {}
    try:
        for component_id, component in components.items():
            if not isinstance(component, dict):
                raise ValueError(f"invalid component record: {component_id}")
            relative = str(component.get("path", ""))
            checksum = str(component.get("sha256", ""))
            _safe_managed_path(root, relative)
            expected_path = expected.get(str(component_id))
            if expected_path != relative:
                raise ValueError(f"component path mismatch: {component_id}={relative}")
            managed_files[relative] = checksum
    except ValueError as exc:
        findings.append(
            _finding(
                "P0",
                "workflow",
                "managed-manifest",
                "Manifest contains an unsafe managed path.",
                str(exc),
                sensitive=True,
            )
        )
        return None
    component_ids = {str(component_id) for component_id in components}
    required_ids = set(expected)
    missing = sorted(required_ids - component_ids)
    extra = sorted(component_ids - required_ids)
    if missing or extra:
        details = []
        if missing:
            details.append(f"missing={','.join(missing)}")
        if extra:
            details.append(f"extra={','.join(extra)}")
        findings.append(
            _finding(
                "P1",
                "workflow",
                "managed-manifest",
                "Manifest does not match the installed canonical component catalog.",
                "; ".join(details),
            )
        )
        return None
    value["managed_files"] = managed_files
    return value


def _check_managed_files(root: Path, findings: list[Finding]) -> None:
    manifest = _load_manifest(root, findings)
    if manifest is None:
        return
    installed_version = str(manifest.get("workflow_version", ""))
    version_path = root / ".astack/version"
    declared_version = (
        version_path.read_text(encoding="utf-8").strip().lstrip("v")
        if version_path.exists()
        else ""
    )
    if not declared_version or declared_version != installed_version:
        findings.append(
            _finding(
                "P1",
                "workflow",
                "workflow-version",
                "Declared and installed workflow versions do not match.",
                (
                    f"declared={declared_version or 'missing'}, "
                    f"installed={installed_version or 'missing'}"
                ),
            )
        )
    managed = manifest["managed_files"]
    for relative, expected in sorted(managed.items()):
        path = _safe_managed_path(root, str(relative))
        if not path.exists():
            findings.append(
                _finding(
                    "P1",
                    "workflow",
                    "managed-file",
                    "Managed workflow file is missing.",
                    str(relative),
                )
            )
        elif _sha256(path) != str(expected):
            findings.append(
                _finding(
                    "P1",
                    "workflow",
                    "managed-file",
                    "Managed workflow file differs from its installed checksum.",
                    str(relative),
                )
            )


def _git_paths(root: Path, *args: str) -> list[str]:
    result = _run(["git", *args], cwd=root)
    if result.returncode != 0:
        raise RuntimeError(result.stderr.strip() or f"git {' '.join(args)} failed")
    return [line for line in result.stdout.splitlines() if line]


def _raw_comparison_base(root: Path) -> str:
    candidates: list[str] = []
    github_base = os.environ.get("GITHUB_BASE_REF", "").strip()
    if github_base:
        candidates.extend([f"refs/remotes/origin/{github_base}", f"refs/heads/{github_base}"])
    remote_head = _run(
        ["git", "symbolic-ref", "--quiet", "--short", "refs/remotes/origin/HEAD"], cwd=root
    )
    if remote_head.returncode == 0 and remote_head.stdout.strip():
        candidates.append(remote_head.stdout.strip())
    candidates.extend(
        [
            "refs/remotes/origin/main",
            "refs/heads/main",
            "refs/remotes/origin/master",
            "refs/heads/master",
        ]
    )
    for candidate in dict.fromkeys(candidates):
        result = _run(["git", "rev-parse", "--verify", f"{candidate}^{{commit}}"], cwd=root)
        if result.returncode == 0:
            return candidate
    raise RuntimeError("could not resolve the default or CI base branch")


def _raw_comparison_start(root: Path) -> str:
    pushed_from = os.environ.get(RAW_BASE_SHA_ENV, "").strip()
    if pushed_from:
        if not re.fullmatch(r"[0-9a-f]{40}", pushed_from):
            raise RuntimeError(f"{RAW_BASE_SHA_ENV} must be a full lowercase Git SHA")
        if pushed_from == "0" * 40:
            raise RuntimeError(
                f"{RAW_BASE_SHA_ENV} is the all-zero initial-push SHA, so no prior tree exists"
            )
        verified = _run(["git", "rev-parse", "--verify", f"{pushed_from}^{{commit}}"], cwd=root)
        if verified.returncode != 0 or verified.stdout.strip() != pushed_from:
            detail = verified.stderr.strip() or "git rev-parse did not return the requested SHA"
            raise RuntimeError(
                f"{RAW_BASE_SHA_ENV} commit is unavailable in the local clone: {detail}"
            )
        return pushed_from
    base = _raw_comparison_base(root)
    merge_base = _run(["git", "merge-base", "HEAD", base], cwd=root)
    if merge_base.returncode != 0 or not merge_base.stdout.strip():
        raise RuntimeError(
            merge_base.stderr.strip() or f"could not resolve merge-base between HEAD and {base}"
        )
    return merge_base.stdout.strip()


def _committed_raw_changes(root: Path) -> list[str]:
    comparison_start = _raw_comparison_start(root)
    return _git_paths(
        root,
        "diff",
        "--name-only",
        "--diff-filter=DMRT",
        comparison_start,
        "HEAD",
        "--",
        "data/raw",
    )


def _check_git_and_raw(root: Path, findings: list[Finding]) -> None:
    if _run(["git", "rev-parse", "--is-inside-work-tree"], cwd=root).returncode != 0:
        findings.append(
            _finding("P1", "reproducibility", "git", "Project is not in a Git worktree.", ".")
        )
        return
    audit_ignore = _run(
        ["git", "check-ignore", "--quiet", "reports/audits/sensitive-audit.md"], cwd=root
    )
    if audit_ignore.returncode == 1:
        findings.append(
            _finding(
                "P1",
                "security",
                "audit-report-ignore",
                "Local audit reports are not ignored and could be committed accidentally.",
                "add /reports/audits/ to .gitignore",
            )
        )
    elif audit_ignore.returncode != 0:
        findings.append(
            _finding(
                "P1",
                "security",
                "audit-report-ignore",
                "Could not verify that sensitive local audit reports are ignored.",
                audit_ignore.stderr.strip() or "git check-ignore failed",
            )
        )
    worktree = _run(["git", "status", "--porcelain"], cwd=root)
    if worktree.returncode != 0:
        findings.append(
            _finding(
                "P1",
                "workflow",
                "worktree-status",
                "Could not verify whether the worktree is clean.",
                worktree.stderr.strip() or "git status failed",
            )
        )
    elif worktree.stdout.strip():
        findings.append(
            _finding(
                "P1",
                "workflow",
                "worktree-cleanliness",
                "Worktree has tracked or untracked changes and is not ready to ship or publish.",
                "commit or remove intended changes before shipping",
            )
        )
    try:
        raw_changes = set(
            _git_paths(root, "diff", "--name-only", "--diff-filter=DMRT", "--", "data/raw")
        )
        raw_changes.update(
            _git_paths(
                root, "diff", "--cached", "--name-only", "--diff-filter=DMRT", "--", "data/raw"
            )
        )
        raw_changes.update(_committed_raw_changes(root))
    except RuntimeError as exc:
        findings.append(
            _finding(
                "P1",
                "data-safety",
                "raw-immutability",
                "Git raw-data checks were unavailable.",
                str(exc),
            )
        )
        return
    if raw_changes:
        findings.append(
            _finding(
                "P0",
                "data-safety",
                "raw-immutability",
                "Tracked source snapshots under data/raw have changed.",
                ", ".join(sorted(raw_changes)),
                sensitive=True,
            )
        )


def _candidate_files(root: Path, findings: list[Finding]) -> list[Path]:
    try:
        paths = _git_paths(root, "ls-files", "--cached", "--others", "--exclude-standard")
    except RuntimeError as exc:
        findings.append(
            _finding(
                "P1",
                "security",
                "commit-candidate-scan",
                "Commit-candidate secret and size checks were unavailable.",
                str(exc),
            )
        )
        return []
    return [root / path for path in paths if (root / path).is_file()]


def _check_secrets_and_size(root: Path, findings: list[Finding]) -> None:
    dvc_enabled = (root / ".dvc").exists()
    for path in _candidate_files(root, findings):
        relative = path.relative_to(root)
        if _is_sensitive_filename(path.name):
            findings.append(
                _finding(
                    "P0",
                    "security",
                    "sensitive-file",
                    "A likely sensitive configuration file is a commit candidate.",
                    str(relative),
                    sensitive=True,
                )
            )
        size = path.stat().st_size
        if size > 10 * 1024 * 1024 and not path.name.endswith(".dvc"):
            findings.append(
                _finding(
                    "P1",
                    "data-safety",
                    "large-file",
                    "A file larger than 10 MiB is not represented by a DVC pointer.",
                    f"{relative} ({size} bytes, dvc_configured={dvc_enabled})",
                    sensitive=True,
                )
            )
        if path.suffix.lower() in BINARY_SUFFIXES:
            continue
        try:
            contains_secret = _stream_contains_secret(path)
        except (UnicodeDecodeError, OSError):
            if size > 2 * 1024 * 1024:
                findings.append(
                    _finding(
                        "P1",
                        "security",
                        "secret-scan-unavailable",
                        "A large commit-candidate file could not be scanned as UTF-8 text.",
                        str(relative),
                        sensitive=True,
                    )
                )
            continue
        if contains_secret:
            findings.append(
                _finding(
                    "P0",
                    "security",
                    "secret-pattern",
                    "A likely credential pattern was found. The value is intentionally omitted.",
                    str(relative),
                    sensitive=True,
                )
            )


def _safe_data_relative(value: object, *, destination: bool = False) -> Path | None:
    text = str(value or "")
    path = Path(text)
    windows_path = PureWindowsPath(text)
    if (
        not text
        or path.is_absolute()
        or windows_path.is_absolute()
        or windows_path.drive
        or any(part in {"", ".", ".."} for part in path.parts)
        or (destination and path.as_posix().rstrip("/") == "data")
    ):
        return None
    return path


def _safe_private_history_path(value: object) -> str | None:
    if not isinstance(value, str) or not value or value != value.strip():
        return None
    if (
        "\\" in value
        or "//" in value
        or value.endswith("/")
        or any(char in WINDOWS_UNSAFE_PATH_CHARS or ord(char) < 32 for char in value)
    ):
        return None
    parts = value.split("/")
    if any(
        part in {"", ".", ".."}
        or part.endswith((".", " "))
        or part.rstrip(". ").split(".", 1)[0].upper() in WINDOWS_RESERVED_NAMES
        for part in parts
    ):
        return None
    path = Path(value)
    windows_path = PureWindowsPath(value)
    if (
        path.is_absolute()
        or windows_path.is_absolute()
        or windows_path.drive
        or path.as_posix() != value
    ):
        return None
    return value


def _private_history_policy(config: dict[str, Any]) -> tuple[list[str], list[str], list[str]]:
    privacy = config.get("privacy")
    if privacy is None:
        return [], [], []
    if not isinstance(privacy, dict):
        return [], [], ["privacy must be a table"]
    supported = {"private_history_paths", "private_history_safe_paths"}
    errors = [f"unsupported privacy setting {key!r}" for key in privacy if key not in supported]
    values: dict[str, list[str]] = {}
    for key in sorted(supported):
        raw = privacy.get(key, [])
        if not isinstance(raw, list):
            errors.append(f"privacy.{key} must be a list of project-relative paths")
            continue
        normalized: list[str] = []
        for index, value in enumerate(raw):
            path = _safe_private_history_path(value)
            if path is None:
                errors.append(f"privacy.{key}[{index}] is not a safe project-relative path")
            elif path in normalized:
                errors.append(f"privacy.{key} contains a duplicate path: {path}")
            else:
                normalized.append(path)
        values[key] = normalized
    private = values.get("private_history_paths", [])
    safe = values.get("private_history_safe_paths", [])
    for path in safe:
        if not any(path == root or path.startswith(root + "/") for root in private):
            errors.append(
                f"privacy.private_history_safe_paths contains a path outside private roots: {path}"
            )
    return private, safe, errors


def _committed_history_paths(root: Path) -> set[str]:
    commits = _run(["git", "rev-list", "--all"], cwd=root)
    if commits.returncode != 0:
        raise RuntimeError(commits.stderr.strip() or "could not enumerate Git history")
    commit_ids = [commit for commit in commits.stdout.splitlines() if commit]
    if not commit_ids:
        raise RuntimeError("could not enumerate any Git history")
    paths: set[str] = set()
    for commit in commit_ids:
        tree = _run(["git", "ls-tree", "-r", "-z", "--name-only", commit], cwd=root)
        if tree.returncode != 0:
            raise RuntimeError(tree.stderr.strip() or f"could not inspect Git commit {commit}")
        paths.update(path for path in tree.stdout.split("\0") if path)
    return paths


def _check_private_history_paths(root: Path, findings: list[Finding]) -> None:
    try:
        config = _project_config(root)
        private, safe, errors = _private_history_policy(config)
    except (OSError, tomllib.TOMLDecodeError) as exc:
        findings.append(
            _finding(
                "P1",
                "security",
                "private-history-config",
                "Committed-history privacy configuration is invalid.",
                str(exc),
                sensitive=True,
            )
        )
        return
    if errors:
        findings.append(
            _finding(
                "P1",
                "security",
                "private-history-config",
                "Committed-history privacy configuration is invalid.",
                "; ".join(errors),
                sensitive=True,
            )
        )
        return
    if not private:
        return
    try:
        history_paths = _committed_history_paths(root)
    except RuntimeError as exc:
        findings.append(
            _finding(
                "P1",
                "security",
                "private-history",
                "Committed-history privacy checks were unavailable.",
                str(exc),
                sensitive=True,
            )
        )
        return
    violations = sorted(
        path
        for path in history_paths
        if any(path == root_path or path.startswith(root_path + "/") for root_path in private)
        and path not in safe
    )
    if violations:
        findings.append(
            _finding(
                "P0",
                "security",
                "private-history-path",
                "Committed history contains a path declared private by project policy.",
                ", ".join(violations),
                sensitive=True,
            )
        )


def _check_data_layout(root: Path, data: object, findings: list[Finding]) -> None:
    if not isinstance(data, dict):
        findings.append(
            _finding(
                "P1",
                "data-safety",
                "data-layout",
                "Data configuration must be a table.",
                ".astack/project.toml",
            )
        )
        return
    layout = data.get("layout")
    if layout not in {"standard", "legacy"}:
        findings.append(
            _finding(
                "P1",
                "data-safety",
                "data-layout",
                "Data layout must be standard or an explicit legacy migration exception.",
                str(layout),
            )
        )
        return
    try:
        root_path = data_root(root)
    except (OSError, ValueError, tomllib.TOMLDecodeError) as exc:
        findings.append(
            _finding(
                "P1",
                "data-safety",
                "data-layout",
                "Local data-root configuration is invalid.",
                str(exc),
                sensitive=True,
            )
        )
        return
    if layout == "standard":
        share_raw = data.get("share_raw", True)
        if not isinstance(share_raw, bool):
            findings.append(
                _finding(
                    "P1",
                    "data-safety",
                    "data-layout",
                    "Standard shared-raw configuration must be true or false.",
                    str(share_raw),
                    sensitive=True,
                )
            )
        return
    mappings = data.get("legacy_shared_inputs", [])
    if not isinstance(mappings, list):
        mappings = [None]
    invalid: list[str] = []
    for index, mapping in enumerate(mappings):
        if isinstance(mapping, str):
            destination = _safe_data_relative(mapping, destination=True)
            source = _safe_data_relative(mapping)
        elif isinstance(mapping, dict):
            destination = _safe_data_relative(mapping.get("path"), destination=True)
            source = _safe_data_relative(mapping.get("source", mapping.get("path")))
        else:
            destination = source = None
        if destination is None or source is None or not (root_path / source).exists():
            invalid.append(str(index))
    if invalid:
        findings.append(
            _finding(
                "P1",
                "data-safety",
                "legacy-data-layout",
                "Legacy shared-input mappings are unsafe or unavailable.",
                f"mapping_indexes={','.join(invalid)}",
            )
        )


def _check_dependency_checks(root: Path, findings: list[Finding]) -> None:
    """Report what the last checked run of each stage read or wrote without declaring it."""
    checks = dependency_checks(root)
    unchecked = sorted(set(_lock_fingerprints(root)) - set(checks))
    if unchecked:
        findings.append(
            _finding(
                "P2",
                "reproducibility",
                "unchecked-stage",
                "These DVC stages last ran outside `just reproduce`, so what they read and wrote "
                "was not checked. Run `just reproduce` to check them.",
                ", ".join(unchecked[:10]),
            )
        )
    for name, check in sorted(checks.items()):
        writes = check.get("undeclared_writes") or []
        reads = check.get("undeclared_reads") or []
        if writes:
            findings.append(
                _finding(
                    "P1",
                    "reproducibility",
                    "undeclared-write",
                    "A DVC stage wrote files its dvc.yaml outs do not declare, so later stages "
                    "that read them cannot be traced. Declare them as outs.",
                    f"{name}: {', '.join(writes[:5])}",
                )
            )
        if reads:
            findings.append(
                _finding(
                    "P1",
                    "reproducibility",
                    "undeclared-read",
                    "A DVC stage read project files its dvc.yaml deps do not declare, so a change "
                    "to them would not make its outputs outdated. Declare them as deps.",
                    f"{name}: {', '.join(reads[:5])}",
                )
            )
        if check.get("inputs_locked") is False:
            findings.append(
                _finding(
                    "P2",
                    "reproducibility",
                    "inputs-not-locked",
                    "Some files could not be locked or checked safely while this stage ran, so "
                    "reads of them by compiled libraries or other programs, or writes to them, "
                    "may not have been caught.",
                    f"{name}: {', '.join((check.get('lock_gaps') or [])[:5])}",
                )
            )
        if check.get("untraced"):
            findings.append(
                _finding(
                    "P2",
                    "reproducibility",
                    "untraced-stage",
                    "Part of a DVC stage's reads could not be checked. Its writes still were.",
                    f"{name}: {check['untraced']}",
                )
            )


def _has_markdown_report(root: Path) -> bool:
    """Whether reports/ holds a report, not counting figures, tables, audits or READMEs."""
    reports = root / "reports"
    if not reports.is_dir():
        return False
    return any(
        path.is_file()
        and path.name != "README.md"
        and not {"figures", "tables", "audits"} & set(path.relative_to(reports).parts)
        for pattern in ("*.md", "*.qmd")
        for path in reports.rglob(pattern)
    )


def _check_project_state(
    root: Path,
    findings: list[Finding],
    *,
    require_durable_evidence: bool = False,
    output_scope: str | None = None,
) -> None:
    try:
        config = _project_config(root)
    except (OSError, tomllib.TOMLDecodeError) as exc:
        findings.append(
            _finding("P1", "workflow", "project-state", "Project state is invalid.", str(exc))
        )
        return
    if config.get("schema_version") != 1:
        findings.append(
            _finding(
                "P1",
                "workflow",
                "project-state",
                "Project state schema version is missing or unsupported.",
                ".astack/project.toml",
            )
        )
        return
    if not _science_applies(root):
        _check_validation_config(config, findings)
        return
    analysis = config.get("analysis", {})
    stage = analysis.get("stage") if isinstance(analysis, dict) else None
    if stage not in {"exploratory", "material"}:
        findings.append(
            _finding(
                "P1",
                "workflow",
                "analysis-stage",
                "Analysis stage must be exploratory or material.",
                str(stage),
            )
        )
        return
    _check_validation_config(config, findings)
    _check_data_layout(root, config.get("data", {}), findings)
    outputs = config.get("outputs")
    component_layout, declared_components = _output_policy(config)
    if outputs is not None and (
        not isinstance(outputs, dict)
        or outputs.get("layout") != "component"
        or not isinstance(outputs.get("components"), list)
        or any(
            not isinstance(component, str) or not COMPONENT_PATTERN.fullmatch(component)
            for component in outputs.get("components", [])
        )
        or len(declared_components) != len(outputs.get("components", []))
    ):
        findings.append(
            _finding(
                "P1",
                "workflow",
                "output-layout",
                (
                    "Output configuration requires component layout and unique lowercase "
                    "component slugs."
                ),
                ".astack/project.toml",
            )
        )
    _check_output_layout(root, config, findings)
    # One finding per registry blocker, including unknown evidence and stale confirmation.
    _check_output_contract(root, findings, output_scope)
    if stage != "material":
        return
    if not _has_markdown_report(root):
        findings.append(
            _finding(
                "P1",
                "scientific-output",
                "report-missing",
                "Material analysis needs a Markdown report under reports/ that cites its "
                "evidence. Write one with the ds-report-generation skill, then run "
                "`just report-check`.",
                "reports/",
            )
        )
    reproduction = _reproduction_config(config)
    engine = _reproduction_engine(root, config)
    reproduction_component = reproduction.get("component")
    if engine not in REPRODUCTION_ENGINES:
        findings.append(
            _finding(
                "P1",
                "reproducibility",
                "reproduction-engine",
                "Reproduction engine must be `command` or `dvc`.",
                str(engine),
            )
        )
    elif engine == "command" and _reproduction_command(root, config) is None:
        findings.append(
            _finding(
                "P1",
                "reproducibility",
                "reproduction-command",
                "Command-based reproduction requires a configured command array.",
                ".astack/project.toml",
            )
        )
    elif engine == "dvc":
        if "dvc" not in config.get("tools", []):
            findings.append(
                _finding(
                    "P1",
                    "reproducibility",
                    "dvc-capability",
                    "DVC reproduction requires the dvc capability to be declared.",
                    ".astack/project.toml",
                )
            )
        pipeline_outputs, pipeline_errors = _dvc_pipeline_outputs(root)
        for error in pipeline_errors:
            findings.append(
                _finding(
                    "P1",
                    "reproducibility",
                    "dvc-pipeline",
                    "DVC reproduction requires a valid non-empty dvc.yaml pipeline.",
                    error,
                )
            )
        for output in pipeline_outputs:
            if not _reproduction_output_allowed(root, output, config):
                findings.append(
                    _finding(
                        "P1",
                        "data-safety",
                        "dvc-output-path",
                        (
                            "DVC pipeline outputs must use an allowed component output path and "
                            "must not overwrite retained raw inputs."
                        ),
                        output,
                    )
                )
        _check_dependency_checks(root, findings)
        try:
            check_ignore_patterns(config)
        except RuntimeError as exc:
            findings.append(
                _finding("P1", "reproducibility", "check-ignore", str(exc), ".astack/project.toml")
            )
        if _dvc_reproduction_targets(config) is None:
            findings.append(
                _finding(
                    "P1",
                    "reproducibility",
                    "dvc-targets",
                    (
                        "DVC reproduction targets must be a list of non-empty strings that do not "
                        "begin with `-`."
                    ),
                    ".astack/project.toml",
                )
            )
    elif "dvc" in config.get("tools", []) and "engine" not in reproduction:
        findings.append(
            _finding(
                "P2",
                "reproducibility",
                "legacy-dvc-command",
                (
                    "DVC capability is using legacy command reproduction. Declare "
                    "reproduction.engine = 'command' or migrate to dvc.yaml."
                ),
                ".astack/project.toml",
            )
        )
    if reproduction_component is not None and (
        not isinstance(reproduction_component, str)
        or not COMPONENT_PATTERN.fullmatch(reproduction_component)
    ):
        findings.append(
            _finding(
                "P1",
                "reproducibility",
                "reproduction-component",
                "Material analysis requires a safe lowercase reproduction component slug.",
                str(reproduction_component),
            )
        )
    elif component_layout and reproduction_component not in declared_components:
        findings.append(
            _finding(
                "P1",
                "reproducibility",
                "reproduction-component",
                "Material analysis requires a declared reproduction.component.",
                str(reproduction_component),
            )
        )
    try:
        _random_seed(config)
    except RuntimeError as exc:
        findings.append(
            _finding("P1", "reproducibility", "random-seed", str(exc), ".astack/project.toml")
        )
    justfile = root / "justfile"
    just_text = justfile.read_text(encoding="utf-8") if justfile.exists() else ""
    if not re.search(r"(?m)^reproduce\b[^:\n=]*:(?!=)", just_text):
        findings.append(
            _finding(
                "P1",
                "reproducibility",
                "reproduction-interface",
                "Material analysis requires the canonical `just reproduce` interface.",
                "justfile",
            )
        )
    routine_records = list((root / ".cache/runs").glob("**/*.json"))
    run_records = list((root / "reports/qa/runs").glob("*.json"))
    if isinstance(reproduction_component, str) and COMPONENT_PATTERN.fullmatch(
        reproduction_component
    ):
        try:
            evidence_runs = _safe_managed_path(root, f"evidence/{reproduction_component}/runs")
        except ValueError as exc:
            findings.append(
                _finding(
                    "P1",
                    "data-safety",
                    "reproduction-record-path",
                    "Durable reproduction evidence must remain inside the project.",
                    str(exc),
                )
            )
        else:
            run_records.extend(evidence_runs.glob("*.json"))
    _, output_errors = _reproduction_outputs(root, config)
    for error in output_errors:
        findings.append(
            _finding(
                "P1",
                "reproducibility",
                "reproduction-outputs",
                (
                    "Material analysis must declare the outputs a reproduction produces, so a "
                    "rerun can be compared with the promoted reference."
                ),
                error,
            )
        )
    record_paths = run_records if require_durable_evidence else routine_records + run_records
    if any(_valid_run_record(root, path, config) for path in record_paths) and not any(
        _verified_run_record(root, path, config) for path in record_paths
    ):
        findings.append(
            _finding(
                "P1" if require_durable_evidence else "P2",
                "reproducibility",
                "reproduction-unverified",
                (
                    "The pipeline ran, but no promoted rerun has matched a promoted reference "
                    "record, so reproduction is not verified."
                ),
                "run `just reproduce --promote` again after committing the reference record",
            )
        )
    if not any(_valid_run_record(root, path, config) for path in record_paths):
        findings.append(
            _finding(
                "P1",
                "reproducibility",
                "run-provenance",
                (
                    "Material analysis has no valid durable run record for the current committed "
                    "state."
                    if require_durable_evidence
                    else (
                        "Material analysis has no valid run record for the current committed state."
                    )
                ),
                "evidence/<component>/runs/"
                if require_durable_evidence
                else ".cache/runs/ or evidence/",
            )
        )
    acquisition = config.get("acquisition")
    if acquisition is not None and _acquisition_command(config) is None:
        findings.append(
            _finding(
                "P1",
                "reproducibility",
                "acquisition-command",
                "Configured acquisition requires a non-empty command array.",
                ".astack/project.toml",
            )
        )
    if acquisition is not None and _acquisition_staged(config) is None:
        findings.append(
            _finding(
                "P1",
                "reproducibility",
                "acquisition-staged",
                "In-place acquisition was removed. Remove [acquisition].staged and write "
                "new inputs to $ASTACK_ACQUISITION_DIR "
                "(docs/migrations/staged-acquisition.md).",
                ".astack/project.toml",
            )
        )
    project_tests = [
        path
        for path in (root / "tests").glob("test_*.py")
        if path.name not in {"test_smoke.py", "test_sources_schema.py"}
    ]
    if not project_tests:
        findings.append(
            _finding(
                "P1",
                "reproducibility",
                "analytical-tests",
                "Material analysis requires project-specific analytical tests.",
                "tests/",
            )
        )


def _optimization_observations(root: Path) -> dict[str, Any]:
    try:
        state_root = state_path(canonical_checkout(root), "diagnostics.json").parent
        return dict(load_diagnostic_summary(state_root))
    except (ImportError, OSError, RuntimeError, ValueError):
        return {"evidence_state": "unavailable", "reason": "local_state_unavailable"}


def _apply_ci_limits(root: Path, findings: list[Finding]) -> list[str]:
    """Restrict CI's claim, never manufacture source or reproduction verification."""
    config = _project_config(root)
    if config.get("ci") != {"mode": "local-only-sources"}:
        findings.append(
            _finding(
                "P1",
                "workflow",
                "ci-mode",
                "CI limits require explicit ci.mode = local-only-sources.",
                ".astack/project.toml",
            )
        )
        return []
    sources_path = root / "data/sources.yml"
    if yaml is None:
        return []
    try:
        data = yaml.safe_load(sources_path.read_text())
    except (OSError, ValueError, yaml.YAMLError):
        return []  # Existing source validation retains the actual parse failure.
    sources = data.get("sources", {}) if isinstance(data, dict) else {}
    if not isinstance(sources, dict):
        return []
    local = {
        str(key)
        for key, value in sources.items()
        if isinstance(value, dict) and value.get("availability") == "local_only"
    }
    if not local:
        findings.append(
            _finding(
                "P1",
                "provenance",
                "ci-source-declaration",
                "Limited CI requires at least one explicitly local_only source.",
                "data/sources.yml",
            )
        )
        return []
    excluded = []
    for index, finding in enumerate(findings):
        if (finding.check == "source-missing" and finding.evidence in local) or finding.check in {
            "run-provenance",
            "reproduction-unverified",
        }:
            excluded.append(finding.check + ":" + finding.evidence)
            findings[index] = _finding(
                "P2",
                finding.area,
                finding.check + "-not-verified-in-ci",
                "Not verified in limited CI. "
                "Strict local source/reproduction verification is still required.",
                finding.evidence,
                sensitive=finding.sensitive,
            )
    return excluded


def _analysis_stage(root: Path) -> str | None:
    try:
        analysis = _project_config(root).get("analysis", {})
    except (OSError, tomllib.TOMLDecodeError):
        return None
    stage = analysis.get("stage") if isinstance(analysis, dict) else None
    return stage if isinstance(stage, str) else None


def audit(
    root: Path,
    *,
    run_tools: bool = False,
    strict: bool = False,
    ci: bool = False,
    output_scope: str | None = None,
    read_only: bool = False,
) -> dict[str, Any]:
    """Audit the project. With read_only, nothing in the project is written, not even markers."""
    if not read_only:
        _ensure_cache_ignored(root)
        _ensure_audit_reports_ignored(root)
    _load_digest_cache(root)
    _DIGEST_POLICY["bypass"] = strict
    previous = _READ_ONLY["on"]
    _READ_ONLY["on"] = previous or read_only
    try:
        return _audit(root, run_tools=run_tools, strict=strict, ci=ci, output_scope=output_scope)
    finally:
        _READ_ONLY["on"] = previous
        _DIGEST_POLICY["bypass"] = False
        _save_digest_cache(root)


def _audit(
    root: Path,
    *,
    run_tools: bool,
    strict: bool,
    ci: bool,
    output_scope: str | None,
) -> dict[str, Any]:
    findings: list[Finding] = []
    verify_count = len(_scientific_verify_commands(root, []) or [])
    planned = ["check", "integration", *verify_stage_names(verify_count), "strict-audit"]
    if not _scaffold_layout_applies(root):
        # A General project runs its own declared commands, not `just check` and `integration`.
        count = len(_general_check_commands(root, [])) or 1
        planned = [*general_stage_names(count), "strict-audit"]
    session = (
        ValidationSession(
            root,
            name="limited-ci" if ci else "ship-ready",
            planned_stages=planned,
            runner=_run,
        )
        if run_tools
        else None
    )
    if session is not None:
        _check_optional_tools(
            root,
            findings,
            run_tools,
            ensure_dvc_cache=_ensure_dvc_cache,
            session=session,
            **({"ci": True} if ci else {}),
        )
        strict_started = time.monotonic()
    else:
        strict_started = time.monotonic()
    _check_structure(root, findings)
    _check_project_state(root, findings, require_durable_evidence=strict, output_scope=output_scope)
    _check_managed_files(root, findings)
    _check_git_and_raw(root, findings)
    _check_private_history_paths(root, findings)
    _check_secrets_and_size(root, findings)
    science = _science_applies(root)
    if science:
        _check_sources(root, findings)
    _check_spatial(root, findings)
    _check_publication(root, findings)
    if science:
        _check_evidence(root, findings)
    if session is None:
        _check_optional_tools(
            root,
            findings,
            run_tools,
            ensure_dvc_cache=_ensure_dvc_cache,
            **({"ci": True} if ci else {}),
        )
    # CI limits exist for sources CI cannot read. Without science checks there are none.
    excluded = _apply_ci_limits(root, findings) if ci and science else []
    findings.sort(key=lambda item: (PRIORITY_ORDER[item.priority], item.area, item.check))
    blocking = any(item.priority in {"P0", "P1"} for item in findings)
    by_area = {
        area: [item for item in findings if item.area == area]
        for area in {item.area for item in findings}
    }
    workflow_blocking = any(item.priority in {"P0", "P1"} for item in by_area.get("workflow", []))
    reproducibility_blocking = any(
        item.priority in {"P0", "P1"}
        for area in {"reproducibility", "provenance", "data-safety", "security"}
        for item in by_area.get(area, [])
    )
    reproducibility_not_assessed = any(
        item.check.endswith("-not-run") or item.check in {"ci", "reproduction-unverified"}
        for item in findings
    )
    software_findings = [item for item in findings if item.check.startswith("software-")]
    software_verdict = "pass"
    if any(item.priority in {"P0", "P1"} for item in software_findings):
        software_verdict = "fail"
    elif not run_tools or any(item.check == "software-not-run" for item in software_findings):
        software_verdict = "not-assessed"
    analysis_stage = _analysis_stage(root)
    not_assessed = [
        "scientific design and domain validity require interpretive review",
        "full data reproduction is not implied by repository checks",
    ]
    # Passing software checks is not reproduction evidence. Only a material analysis with a
    # valid run record (findings above report its absence) can support a pass.
    reproducibility_verdict = "pass"
    if reproducibility_blocking:
        reproducibility_verdict = "fail"
    elif reproducibility_not_assessed:
        reproducibility_verdict = "not-assessed"
    elif not science:
        reproducibility_verdict = "not-assessed"
        not_assessed.append(
            "science checks: this General project declares no scientific capability, "
            "outputs, analysis stage, or data/sources.yml"
        )
    elif analysis_stage != "material":
        reproducibility_verdict = "not-assessed"
        not_assessed.append(
            "computational reproducibility: no reproduction evidence exists while "
            "analysis.stage is not material"
        )
    release_verdict = "needs-interpretive-review"
    if blocking:
        release_verdict = "fail"
    elif reproducibility_verdict != "pass":
        release_verdict = "not-assessed"
    result: dict[str, Any] = {
        "schema_version": 1,
        "root": str(root),
        "analysis_stage": analysis_stage,
        "verdicts": {
            "workflow_conformance": "fail" if workflow_blocking else "pass",
            "software_checks": software_verdict,
            "computational_reproducibility": reproducibility_verdict,
            "scientific_credibility": "needs-interpretive-review",
            "release_readiness": release_verdict,
        },
        "counts": {
            priority: sum(item.priority == priority for item in findings)
            for priority in PRIORITY_ORDER
        },
        "findings": [asdict(item) for item in findings],
        "output_contract": _audit_output_contract_summary(root, output_scope),
        "optimization_observations": _optimization_observations(root),
        "not_assessed": [
            *not_assessed,
            *(
                []
                if _publication_declaration(root) is not None
                else ["journal and archive handoff: [publication] is not declared"]
            ),
        ],
    }
    if ci:
        result["verdicts"]["computational_reproducibility"] = (
            "fail" if reproducibility_blocking else "not-assessed"
        )
        result["verdicts"]["release_readiness"] = "fail" if blocking else "not-assessed"
        result["ci_validation"] = {
            "scope": "engineering-and-metadata-only",
            "status": "pass"
            if run_tools and not blocking
            else "fail"
            if blocking
            else "not-assessed",
            "excluded_checks": excluded,
            "source_identity": "not-verified-in-ci",
            "reproduction": "not-verified-in-ci",
            "requires_strict_local_ship_ready": True,
        }
    if session is not None:
        session.record_stage(
            "strict-audit",
            started=strict_started,
            status="passed" if not blocking else "failed",
        )
        result["validation_session"] = session.finish(status="passed" if not blocking else "failed")
    return result


# --- sources responsibility ---


def _expected_checksum(value: object) -> tuple[str, str] | None:
    """Parse a checksum as (kind, hex): kind is "file", "tree" (legacy v1) or "tree-v2"."""
    text = str(value or "").lower()
    kind = "file"
    if text.startswith("sha256-tree-v1:"):
        kind = "tree"
        text = text.removeprefix("sha256-tree-v1:")
    elif text.startswith("sha256-tree-v2:"):
        kind = "tree-v2"
        text = text.removeprefix("sha256-tree-v2:")
    elif text.startswith("sha256:"):
        text = text.removeprefix("sha256:")
    return (kind, text) if re.fullmatch(r"[0-9a-f]{64}", text) else None


def _is_os_metadata(path: Path) -> bool:
    """Finder and Explorer write these on browse. They are never source data.

    Only raw coverage skips them. Checksums hash every file, so keep them out of source trees.
    """
    return path.name in OS_METADATA_FILENAMES or path.name.startswith("._")


def _data_files(directory: Path) -> list[Path]:
    return sorted(
        item for item in directory.rglob("*") if item.is_file() and not _is_os_metadata(item)
    )


def _tree_sha256(directory: Path) -> str:
    """Legacy sha256-tree-v1. Its framing is ambiguous when file bytes contain NUL (#260)."""
    digest = hashlib.sha256()
    for path in sorted(item for item in directory.rglob("*") if item.is_file()):
        digest.update(path.relative_to(directory).as_posix().encode())
        digest.update(b"\0")
        with path.open("rb") as handle:
            for block in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(block)
        digest.update(b"\0")
    return digest.hexdigest()


def _tree_sha256_v2(directory: Path) -> str:
    """sha256-tree-v2: each file is framed by its path, NUL, and its fixed-length SHA-256."""
    digest = hashlib.sha256(b"astack-sha256-tree-v2\0")
    for relative, path in sorted(_tree_v2_files(directory, "")):
        digest.update(relative.encode() + b"\0" + _cached_sha256(path).encode() + b"\n")
    return digest.hexdigest()


def _tree_v2_files(directory: Path, prefix: str) -> list[tuple[str, Path]]:
    """List every file under a tree, raising instead of skipping anything it cannot read."""
    files: list[tuple[str, Path]] = []
    with os.scandir(directory) as entries:  # an unreadable directory raises, never hides files
        for entry in entries:
            relative = f"{prefix}{entry.name}"
            path = Path(entry.path)
            if entry.is_symlink():
                if not path.is_file():
                    raise RuntimeError(
                        f"{relative} is a symlink to a directory or a missing target; copy the "
                        "files into the source directory instead"
                    )
                files.append((relative, path))
            elif entry.is_dir(follow_symlinks=False):
                files.extend(_tree_v2_files(path, f"{relative}/"))
            elif entry.is_file(follow_symlinks=False):
                files.append((relative, path))
            else:
                raise RuntimeError(f"{relative} is not a regular file or directory")
    return files


def _tree_manifest(directory: Path) -> list[list[object]] | None:
    """Every file's path and stamp, or None when any file is not cacheable."""
    entries: list[list[object]] = []
    for path in sorted(item for item in directory.rglob("*") if item.is_file()):
        stamp = _file_stamp(path)
        if not _stable_stamp(stamp):
            return None
        entries.append([path.relative_to(directory).as_posix(), *stamp])
    return entries


def _cached_tree_sha256(directory: Path) -> str:
    """Return the tree digest, reusing it only while the whole file set and stamps are unchanged."""
    entries = _tree_manifest(directory)
    if entries is None:
        return _tree_sha256(directory)
    key = hashlib.sha256(json.dumps(entries).encode()).hexdigest()
    cache_key = f"tree:{directory.resolve()}"
    digest = _cached_digest(cache_key, key, lambda: _tree_sha256(directory))
    # Re-enumerate after hashing: a file added, removed, or changed meanwhile invalidates it.
    if _tree_manifest(directory) != entries:
        _DIGEST_MEMO.pop(cache_key, None)
        return _tree_sha256(directory)
    return digest


def _local_source_path(root: Path, value: object) -> Path | None:
    text = str(value or "")
    if not text or "://" in text:
        return None
    path = Path(text)
    if path.is_absolute() or ".." in path.parts:
        return None
    candidate = (root / path).resolve(strict=False)
    resolved_root = root.resolve()
    allowed_roots = {resolved_root}
    raw_path = root / "data/raw"
    if raw_path.exists():
        allowed_roots.add(raw_path.resolve())
    try:
        configured_data = data_root(root)
    except (OSError, ValueError, tomllib.TOMLDecodeError):
        configured_data = root / "data"
    allowed_roots.update({configured_data.resolve(), (configured_data / "raw").resolve()})
    if not any(candidate == allowed or allowed in candidate.parents for allowed in allowed_roots):
        return None
    return candidate


def _normalized_evidence(value: object) -> str:
    return " ".join(str(value).split()).casefold()


def _has_source_evidence(value: object) -> bool:
    if isinstance(value, dict):
        status = value.get("status")
        if status == "known":
            return _has_source_evidence(value.get("value"))
        if status == "not_applicable":
            return _has_source_evidence(value.get("reason"))
        return status in EPISTEMIC_STATES
    if isinstance(value, str):
        normalized = _normalized_evidence(value)
        return bool(normalized) and normalized not in PLACEHOLDER_EVIDENCE_VALUES
    return value is not None and bool(value)


def _has_text_source_evidence(value: object) -> bool:
    return isinstance(value, str) and _has_source_evidence(value)


def _has_allowed_outputs(value: object) -> bool:
    return (
        isinstance(value, list)
        and bool(value)
        and all(isinstance(output, str) and _has_source_evidence(output) for output in value)
    )


def _epistemic_state(value: object) -> tuple[bool, bool]:
    """Return structural validity and whether evidence remains unresolved."""
    if not isinstance(value, dict) or value.get("status") not in EPISTEMIC_STATES:
        return False, False
    status = str(value["status"])
    if status == "known":
        known_value = value.get("value")
        return (
            bool(known_value)
            if isinstance(known_value, dict)
            else _has_source_evidence(known_value),
            False,
        )
    if status == "not_applicable":
        return _has_source_evidence(value.get("reason")), False
    return True, True


def _source_identity(value: object) -> tuple[bool, bool]:
    valid, unresolved = _epistemic_state(value)
    if not valid or unresolved:
        return valid, unresolved
    assert isinstance(value, dict)
    if value.get("status") == "not_applicable":
        return True, False
    identity = value.get("value")
    if not isinstance(identity, dict):
        return False, False
    method = identity.get("method")
    identifier = identity.get("identifier")
    return (
        method in SOURCE_IDENTITY_METHODS and _has_text_source_evidence(identifier),
        False,
    )


def _declared_identity(value: dict[str, Any]) -> tuple[str | None, str | None]:
    identity = value.get("identity")
    if isinstance(identity, dict) and identity.get("status") == "known":
        declared = identity.get("value")
        if isinstance(declared, dict):
            method, identifier = declared.get("method"), declared.get("identifier")
            return (
                method if isinstance(method, str) else None,
                identifier if isinstance(identifier, str) else None,
            )
    return None, None


def _verification_record_problem(
    root: Path, source_id: str, value: dict[str, Any], path_value: str
) -> str | None:
    """Return why an external source's verification record does not support it, or None."""
    relative = value.get("verification")
    if not isinstance(relative, str) or not relative.strip():
        return "verification must be a project-relative path to a verification record"
    try:
        path = _safe_managed_path(root, relative.strip())
    except ValueError as exc:
        return str(exc)
    if not path.is_file():
        return f"verification record does not exist: {relative}"
    try:
        record = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        return f"verification record is not valid JSON: {exc}"
    if not isinstance(record, dict) or record.get("schema_version") != 1:
        return "verification record schema_version must be 1"
    digest = _expected_checksum(record.get("digest"))
    if digest is None:
        return (
            "verification record digest must be sha256:<hex>, sha256-tree-v2:<hex>, or the "
            "legacy sha256-tree-v1:<hex>"
        )
    if not _has_text_source_evidence(record.get("verified_at")):
        return "verification record requires verified_at"
    expected: dict[str, str | None] = {"source_id": source_id, "retrieved_from": path_value}
    method, identifier = _declared_identity(value)
    if identifier is not None:
        expected |= {"method": method, "identifier": identifier}
    for field, wanted in expected.items():
        if record.get(field) != wanted:
            return f"verification record {field} does not match data/sources.yml"
    return _digest_consistency_problem(value, method, identifier, digest)


def _digest_consistency_problem(
    value: dict[str, Any],
    method: str | None,
    identifier: str | None,
    digest: tuple[str, str],
) -> str | None:
    """Compare a verified digest, including its file/tree kind, with every declared digest."""
    if value.get("raw_checksum") is not None:
        declared = _expected_checksum(value.get("raw_checksum"))
        if declared is None:
            return "raw_checksum is malformed"
        if declared != digest:
            return "verification digest does not match raw_checksum"
    if method in {"sha256", "sha256_tree"}:
        parsed = _expected_checksum(identifier)
        hex_digest = parsed[1] if parsed is not None else None
        kind = "file"
        if method == "sha256" and parsed is not None and parsed[0] != "file":
            return "sha256 identity must be a file digest, not a tree checksum"
        if method == "sha256_tree":
            if str(identifier or "").lower().startswith("sha256:"):
                return "sha256_tree identity must be a tree checksum, not a file digest"
            # A bare hex tree identifier predates versioned prefixes, so it means v1.
            kind = "tree" if parsed is None or parsed[0] == "file" else parsed[0]
        if hex_digest is None or (kind, hex_digest) != digest:
            return "sha256 identity does not match the verified digest"
    return None


def _check_external_verification(
    root: Path,
    source_id: str,
    value: dict[str, Any],
    path_value: str,
    findings: list[Finding],
) -> None:
    """A declared external identity is a claim; only a digest of retrieved bytes verifies it."""
    if value.get("verification") is None:
        findings.append(
            _finding(
                "P1",
                "provenance",
                "source-identity-unverified",
                (
                    "External source identity is declared but not verified against a digest of "
                    "retrieved bytes, so it cannot support release. Run `python "
                    ".astack/workflow.py verify-source <id> <retrieved-path>`."
                ),
                source_id,
            )
        )
        return
    problem = _verification_record_problem(root, source_id, value, path_value)
    if problem is not None:
        findings.append(
            _finding(
                "P1",
                "provenance",
                "source-identity-verification",
                "External source verification record does not support its declared identity.",
                f"{source_id}: {problem}",
            )
        )
        return
    # A valid record's digest equals every declared digest, so its kind speaks for all of them.
    if _verification_digest_kind(root, value) == "tree":
        findings.append(_legacy_tree_finding(source_id))


def _verification_digest_kind(root: Path, value: dict[str, Any]) -> str | None:
    try:
        path = _safe_managed_path(root, str(value.get("verification")).strip())
        record = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, ValueError):
        return None
    parsed = _expected_checksum(record.get("digest")) if isinstance(record, dict) else None
    return parsed[0] if parsed is not None else None


def _legacy_tree_finding(source_id: str) -> Finding:
    return _finding(
        "P1",
        "provenance",
        "legacy-tree-checksum",
        (
            "Source directory uses the legacy sha256-tree-v1 checksum, whose framing can let two "
            "different directories share a digest, so it cannot support release. Record the "
            "value from `python .astack/workflow.py checksum <path>` (sha256-tree-v2) instead, "
            "and re-run verify-source for an external source."
        ),
        source_id,
    )


def _retrieved_digest(path: Path) -> str:
    """Hash fresh bytes: a verification record or recorded checksum never trusts the cache."""
    previous = _DIGEST_POLICY["bypass"]
    _DIGEST_POLICY["bypass"] = True
    try:
        return _uncached_retrieved_digest(path)
    finally:
        _DIGEST_POLICY["bypass"] = previous


def _uncached_retrieved_digest(path: Path) -> str:
    if path.is_symlink():
        raise RuntimeError("Retrieved source path must not be a symlink")
    if path.is_file():
        return f"sha256:{_sha256(path)}"
    if path.is_dir():
        return f"sha256-tree-v2:{_tree_sha256_v2(path)}"
    raise RuntimeError(f"Retrieved source path does not exist: {path}")


def verify_source(root: Path, source_id: str, retrieved: Path) -> dict[str, Any]:
    """Hash bytes retrieved for an external source and write its verification record."""
    if yaml is None:
        raise RuntimeError("PyYAML is unavailable, so data/sources.yml cannot be read")
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]*", source_id):
        raise RuntimeError("Source id must use letters, digits, '.', '_' or '-'")
    data = yaml.safe_load((root / "data/sources.yml").read_text(encoding="utf-8")) or {}
    sources = data.get("sources") if isinstance(data, dict) else None
    value = sources.get(source_id) if isinstance(sources, dict) else None
    if not isinstance(value, dict):
        raise RuntimeError(f"Source {source_id!r} is not declared in data/sources.yml")
    path_value = str(value.get("path") or "").strip()
    if "://" not in path_value:
        raise RuntimeError("verify-source applies only to external sources (path with a scheme)")
    digest = _retrieved_digest(retrieved)
    method, identifier = _declared_identity(value)
    parsed_digest = _expected_checksum(digest)
    assert parsed_digest is not None
    problem = _digest_consistency_problem(value, method, identifier, parsed_digest)
    if problem is not None:
        raise RuntimeError(f"Retrieved bytes do not match the declaration: {problem}")
    record: dict[str, Any] = {
        "schema_version": 1,
        "source_id": source_id,
        "retrieved_from": path_value,
        "digest": digest,
        "verified_at": datetime.now(UTC).isoformat(timespec="seconds").replace("+00:00", "Z"),
    }
    if identifier is not None:
        record |= {"method": method, "identifier": identifier}
    relative = f"data/source-verification/{source_id}.json"
    output = _safe_managed_path(root, relative)
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(json.dumps(record, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    return {
        "status": "verified",
        "record": relative,
        "digest": digest,
        "next_step": f"Set sources.{source_id}.verification: {relative} in data/sources.yml",
        "limits": (
            "Proves which bytes were retrieved and hashed at verified_at. It does not prove the "
            "upstream location will serve the same bytes again."
        ),
    }


def _external_root_for(root: Path, name: str) -> Path | None:
    """Look up an external root in the canonical checkout's local config, or this root's."""
    try:
        canonical = Path(canonical_checkout(root))
    except (OSError, RuntimeError):
        canonical = root
    try:
        found: Path | None = external_root(canonical, name)
    except (OSError, RuntimeError, ValueError, tomllib.TOMLDecodeError):
        return None
    return found


def _in_place_source_path(root: Path, value: object) -> tuple[Path | None, str]:
    """Resolve "root:<name>/<relative path>" against this machine's external roots."""
    text = str(value or "").strip()
    usage = "in-place source path must be root:<name>/<relative path>"
    if not text.startswith(IN_PLACE_PREFIX):
        return None, usage
    name, _, relative = text[len(IN_PLACE_PREFIX) :].partition("/")
    if not re.fullmatch(r"[a-z0-9_]+", name) or not relative:
        # Lowercase letters, digits and underscores map one-to-one to ASTACK_EXTERNAL_ROOT_<NAME>.
        return None, usage + ", where <name> uses lowercase letters, digits and underscores"
    relative_path = Path(relative)
    if relative_path.is_absolute() or ".." in relative_path.parts:
        return None, "in-place source path must not be absolute or traverse upward"
    base = _external_root_for(root, name)
    if base is None:
        return None, (
            f"external root {name!r} is not configured on this machine. Set it in "
            ".astack/local.toml under [data.external_roots]"
        )
    candidate = (base / relative_path).resolve(strict=False)
    if candidate != base and base not in candidate.parents:
        return None, "in-place source path escapes its external root"
    if candidate.is_relative_to(root.resolve()):
        return None, "an in-place source must live outside the project. Snapshot it instead"
    return candidate, ""


def _snapshot_limit_bytes(root: Path) -> tuple[int, str | None]:
    """The per-source size above which a source may stay in place, and any config error."""
    default = DEFAULT_SNAPSHOT_LIMIT_GB * (1 << 30)
    try:
        data = project_config(root).get("data", {})
    except (OSError, ValueError, tomllib.TOMLDecodeError):
        return default, None
    value = (
        data.get("snapshot_limit_gb", DEFAULT_SNAPSHOT_LIMIT_GB) if isinstance(data, dict) else None
    )
    if isinstance(value, bool) or not isinstance(value, (int, float)) or value <= 0:
        return default, f"[data].snapshot_limit_gb must be a positive number, not {value!r}"
    return int(value * (1 << 30)), None


def _total_bytes(path: Path) -> int:
    """Total size of a file or tree from metadata only, never following links."""
    if not path.is_dir():
        return path.stat().st_size
    total = 0
    for current, _directories, files in os.walk(path, followlinks=False):
        for name in files:
            try:
                total += os.lstat(os.path.join(current, name)).st_size
            except OSError:
                continue
    return total


def _check_source_bytes(
    source_path: Path, source_id: str, checksum: tuple[str, str], findings: list[Finding]
) -> set[Path]:
    """Compare a source's bytes with its checksum. Returns the files it covers."""
    checksum_kind, expected_digest = checksum
    if source_path.is_file():
        if checksum_kind != "file" or _cached_sha256(source_path) != expected_digest:
            findings.append(
                _finding(
                    "P0",
                    "data-safety",
                    "raw-checksum",
                    "A local source snapshot does not match its recorded checksum.",
                    source_id,
                    sensitive=True,
                )
            )
        return {source_path}
    if source_path.is_dir():
        _check_tree_checksum(source_path, source_id, checksum_kind, expected_digest, findings)
        return {path for path in source_path.rglob("*") if path.is_file()}
    if source_path.exists():
        # A FIFO, socket or device has no stable bytes to compare, so it never verifies.
        findings.append(
            _finding(
                "P0",
                "data-safety",
                "raw-checksum",
                "A source is neither a regular file nor a directory, so its bytes cannot be "
                "verified.",
                source_id,
                sensitive=True,
            )
        )
    return set()


def _in_place_checksum_error(source_path: Path, checksum: tuple[str, str] | None) -> str:
    """An in-place directory needs sha256-tree-v2, which refuses links and special files."""
    if checksum is not None and source_path.is_dir() and checksum[0] != "tree-v2":
        return "An in-place directory requires a sha256-tree-v2 checksum."
    return ""


def _check_in_place_source(
    root: Path, source_id: str, value: dict[str, Any], limit: int, findings: list[Finding]
) -> None:
    """A source verified where it lives instead of snapshotted. It needs a recorded reason."""
    if value.get("storage") != "in_place":
        findings.append(
            _finding(
                "P1",
                "provenance",
                "source-storage",
                "A root: path is valid only with storage: in_place.",
                source_id,
            )
        )
        return
    reason = value.get("in_place_reason")
    if reason not in IN_PLACE_REASONS:
        findings.append(
            _finding(
                "P1",
                "provenance",
                "source-in-place-reason",
                "An in-place source needs in_place_reason: size or license. "
                "Otherwise snapshot it into data/raw through acquisition.",
                source_id,
            )
        )
    source_path, error = _in_place_source_path(root, value.get("path"))
    if source_path is None:
        findings.append(_finding("P1", "provenance", "source-path", error, source_id))
        return
    if not source_path.exists():
        findings.append(
            _finding(
                "P1",
                "reproducibility",
                "source-missing",
                "In-place source is not available on this machine. Mount its drive or fix its "
                "external root.",
                source_id,
            )
        )
        return
    checksum = _expected_checksum(value.get("raw_checksum"))
    checksum_error = _in_place_checksum_error(source_path, checksum)
    if checksum is None or checksum_error:
        findings.append(
            _finding(
                "P1",
                "reproducibility",
                "source-checksum",
                checksum_error or "An in-place source requires a valid SHA-256 checksum.",
                source_id,
            )
        )
    else:
        _check_source_bytes(source_path, source_id, checksum, findings)
    if reason == "size":
        total = _total_bytes(source_path)
        if total <= limit:
            findings.append(
                _finding(
                    "P1",
                    "provenance",
                    "source-should-snapshot",
                    "An in-place source within the snapshot limit must be snapshotted into "
                    "data/raw through acquisition.",
                    f"{source_id}: {total / (1 << 30):.2f} GiB, limit {limit / (1 << 30):g} GiB",
                )
            )


def in_place_root_environment(root: Path) -> dict[str, str]:
    """The external-root variables a run needs to find its in-place sources."""
    path = root / "data" / "sources.yml"
    if yaml is None or not path.exists():
        return {}
    try:
        data = yaml.safe_load(path.read_text(encoding="utf-8")) or {}
    except (yaml.YAMLError, OSError):
        return {}
    sources = data.get("sources") if isinstance(data, dict) else None
    environment: dict[str, str] = {}
    for value in sources.values() if isinstance(sources, dict) else ():
        text = str(value.get("path") or "").strip() if isinstance(value, dict) else ""
        if not text.startswith(IN_PLACE_PREFIX):
            continue
        name = text[len(IN_PLACE_PREFIX) :].partition("/")[0]
        base = _external_root_for(root, name)
        if base is not None:
            environment[EXTERNAL_ROOT_ENV_PREFIX + name.upper()] = str(base)
    return environment


def in_place_inputs_identity(root: Path) -> dict[str, str]:
    """Verify every in-place source a run reads and return its checksum by source id.

    A run must refuse an in-place source it cannot verify, because nothing in the project
    holds a copy of those bytes.
    """
    path = root / "data" / "sources.yml"
    if yaml is None or not path.exists():
        return {}
    try:
        data = yaml.safe_load(path.read_text(encoding="utf-8")) or {}
    except (yaml.YAMLError, OSError) as exc:
        raise RuntimeError(f"Provenance YAML is invalid: {exc}") from exc
    sources = data.get("sources") if isinstance(data, dict) else None
    if not isinstance(sources, dict):
        return {}
    identity: dict[str, str] = {}
    for source_id, value in sorted(
        (str(key), record) for key, record in sources.items() if isinstance(record, dict)
    ):
        in_place = value.get("storage") == "in_place" or str(
            value.get("path") or ""
        ).strip().startswith(IN_PLACE_PREFIX)
        if not in_place:
            continue
        source_path, error = _in_place_source_path(root, value.get("path"))
        if source_path is None:
            raise RuntimeError(f"In-place source {source_id}: {error}")
        if not source_path.exists():
            raise RuntimeError(f"In-place source {source_id} is not available on this machine")
        checksum = _expected_checksum(value.get("raw_checksum"))
        if checksum is None:
            raise RuntimeError(f"In-place source {source_id} has no valid SHA-256 checksum")
        checksum_error = _in_place_checksum_error(source_path, checksum)
        if checksum_error:
            raise RuntimeError(f"In-place source {source_id}: {checksum_error}")
        mismatches: list[Finding] = []
        _check_source_bytes(source_path, source_id, checksum, mismatches)
        if any(finding.check == "raw-checksum" for finding in mismatches):
            raise RuntimeError(f"In-place source {source_id} does not match its checksum")
        identity[source_id] = f"{checksum[0]}:{checksum[1]}"
    return identity


def _uncommitted_outside_raw(root: Path, path_value: str) -> bool:
    """Whether a local source outside data/raw has bytes this repository's Git does not record.

    Reproduction fingerprints data/raw and refuses uncommitted changes, so any other location is
    covered only when Git does not ignore it.
    """
    parts = Path(path_value).parts
    if parts[:2] == ("data", "raw"):
        return False
    ignored = _run(
        ["git", "ls-files", "--others", "--exclude-standard", "--ignored", "--", path_value],
        cwd=root,
    )
    # Outside Git, reproduction refuses to run. Untracked files make it refuse too.
    if ignored.returncode == 0 and ignored.stdout.strip():
        return True
    return _outside_project_git(root, Path(path_value))


def _outside_project_git(root: Path, relative: Path) -> bool:
    """Whether a project path's bytes escape this repository's Git record.

    Git keeps a symlink, not its target's bytes, and a nested repository or submodule keeps its
    own ignore rules and dirty state, which this checkout's status does not see.
    """
    current = root
    for part in relative.parts:
        current = current / part
        if current.is_symlink() or (current / ".git").exists():
            return True
    if not current.is_dir():
        return False
    for directory, subdirectories, files in os.walk(current, followlinks=False):
        names = (*subdirectories, *files)
        if ".git" in names or any(Path(directory, name).is_symlink() for name in names):
            return True
    return False


def _check_sources(root: Path, findings: list[Finding]) -> None:
    path = root / "data" / "sources.yml"
    if not path.exists():
        findings.append(
            _finding(
                "P1", "provenance", "sources", "Canonical provenance file is missing.", str(path)
            )
        )
        return
    if yaml is None:
        findings.append(
            _finding(
                "P1",
                "provenance",
                "sources-parser",
                "PyYAML is unavailable, so provenance was not validated.",
                "uv sync --group dev",
            )
        )
        return
    try:
        data = yaml.safe_load(path.read_text(encoding="utf-8")) or {}
    except (yaml.YAMLError, OSError) as exc:
        findings.append(
            _finding("P1", "provenance", "sources", "Provenance YAML is invalid.", str(exc))
        )
        return
    schema_version = data.get("schema_version", 1) if isinstance(data, dict) else None
    # YAML can yield lists, maps or booleans here; only the integers 1 and 2 are versions.
    if type(schema_version) is not int or schema_version not in {1, 2}:
        findings.append(
            _finding(
                "P1",
                "provenance",
                "sources-schema-version",
                "Provenance schema version is unsupported.",
                str(schema_version),
            )
        )
        return
    sources = data.get("sources") if isinstance(data, dict) else None
    if not isinstance(sources, dict):
        findings.append(
            _finding(
                "P1", "provenance", "sources", "`sources` must be a mapping.", "data/sources.yml"
            )
        )
        return
    raw_files = _data_files(root / "data" / "raw") if (root / "data" / "raw").exists() else []
    source_code = [
        path
        for folder in (root / "src", root / "scripts")
        if folder.exists()
        for path in folder.rglob("*.py")
        if path.name != "__init__.py"
    ]
    notebooks = (
        [
            path
            for path in (root / "notebooks").rglob("*.py")
            if path.is_file() and not _viewer_notebook(root, path)
        ]
        if (root / "notebooks").exists()
        else []
    )
    reports_dir = root / "reports"
    reports = list(reports_dir.rglob("*.qmd")) if reports_dir.exists() else []
    if (raw_files or source_code or notebooks or reports) and not sources:
        findings.append(
            _finding(
                "P1",
                "provenance",
                "source-coverage",
                "Data or analytical artifacts exist but no provenance records are defined.",
                (
                    f"raw_files={len(raw_files)}, analytical_code={len(source_code)}, "
                    f"notebooks={len(notebooks)}, reports={len(reports)}"
                ),
                sensitive=True,
            )
        )
    invalid_ids = sorted(
        repr(key) for key in sources if not isinstance(key, str) or not key.strip()
    )
    if invalid_ids:
        findings.append(
            _finding(
                "P1",
                "provenance",
                "source-id",
                "Source IDs must be non-empty strings. Quote numeric or empty keys.",
                ", ".join(invalid_ids),
            )
        )
    limit, limit_error = _snapshot_limit_bytes(root)
    if limit_error:
        findings.append(
            _finding("P1", "provenance", "data-snapshot-limit", limit_error, ".astack/project.toml")
        )
    covered_raw: set[Path] = set()
    for source_id, value in sorted(
        (key, record) for key, record in sources.items() if isinstance(key, str) and key.strip()
    ):
        if not isinstance(value, dict):
            findings.append(
                _finding(
                    "P1",
                    "provenance",
                    "source-record",
                    "Source record must be a mapping.",
                    str(source_id),
                )
            )
            continue
        missing = sorted(
            field
            for field in SOURCE_REQUIRED_FIELDS
            if not (
                _has_allowed_outputs(value.get(field))
                if field == "allowed_outputs"
                else _epistemic_state(value.get(field))[0]
                if schema_version == 2 and field in EPISTEMIC_FIELDS
                else _has_text_source_evidence(value.get(field))
            )
        )
        if missing:
            findings.append(
                _finding(
                    "P1",
                    "provenance",
                    "source-fields",
                    "Source record is missing required evidence.",
                    f"{source_id}: {', '.join(missing)}",
                )
            )
        if schema_version == 2:
            unresolved: list[str] = []
            invalid_states: list[str] = []
            for field in sorted(EPISTEMIC_FIELDS):
                valid, field_unresolved = _epistemic_state(value.get(field))
                if not valid:
                    invalid_states.append(field)
                elif field_unresolved:
                    unresolved.append(field)
            checksum_identity = _expected_checksum(value.get("raw_checksum")) is not None
            identity_valid, identity_unresolved = (
                (True, False)
                if value.get("identity") is None and checksum_identity
                else _source_identity(value.get("identity"))
            )
            if not identity_valid:
                invalid_states.append("identity")
            elif identity_unresolved:
                unresolved.append("identity")
            if invalid_states:
                findings.append(
                    _finding(
                        "P1",
                        "provenance",
                        "source-evidence-state",
                        "Source evidence state is invalid or lacks its required value or reason.",
                        f"{source_id}: {', '.join(invalid_states)}",
                    )
                )
            if unresolved:
                findings.append(
                    _finding(
                        "P1",
                        "provenance",
                        "source-evidence-unresolved",
                        "Source evidence is explicitly unresolved and cannot support release.",
                        f"{source_id}: {', '.join(unresolved)}",
                    )
                )
        storage = value.get("storage", "snapshot")
        if storage not in ("snapshot", "in_place"):
            findings.append(
                _finding(
                    "P1",
                    "provenance",
                    "source-storage",
                    "Source storage must be snapshot or in_place.",
                    str(source_id),
                )
            )
            continue
        if storage == "in_place" or str(value.get("path") or "").strip().startswith(
            IN_PLACE_PREFIX
        ):
            _check_in_place_source(root, str(source_id), value, limit, findings)
            continue
        checksum = _expected_checksum(value.get("raw_checksum"))
        path_value = str(value.get("path") or "").strip()
        external_source = "://" in path_value
        identity_valid, identity_unresolved = (
            (True, False)
            if value.get("identity") is None and checksum is not None
            else _source_identity(value.get("identity"))
        )
        if value.get("availability") not in (None, "local_only", "ci_available"):
            findings.append(
                _finding(
                    "P1",
                    "provenance",
                    "source-availability",
                    "Availability must be local_only or ci_available when declared.",
                    str(source_id),
                )
            )
        identity_value = value.get("identity")
        identity_known = (
            isinstance(identity_value, dict)
            and identity_value.get("status") == "known"
            and identity_valid
            and not identity_unresolved
        )
        if checksum is None and (not external_source or not identity_known):
            findings.append(
                _finding(
                    "P1",
                    "reproducibility",
                    "source-checksum",
                    "Source requires a valid SHA-256 checksum or verifiable external identity.",
                    str(source_id),
                )
            )
        source_path = _local_source_path(root, path_value)
        procedures = [value[field] for field in ("acquisition", "retrieval") if field in value]
        if not external_source and source_path is None:
            findings.append(
                _finding(
                    "P1",
                    "provenance",
                    "source-path",
                    "Local source path is absolute, traversing, or otherwise unsafe.",
                    str(source_id),
                )
            )
        elif source_path is not None and not source_path.exists():
            findings.append(
                _finding(
                    "P1",
                    "reproducibility",
                    "source-missing",
                    "Recorded local source path does not exist.",
                    str(source_id),
                )
            )
        if external_source and not any(
            _has_text_source_evidence(procedure) for procedure in procedures
        ):
            findings.append(
                _finding(
                    "P1",
                    "reproducibility",
                    "source-acquisition",
                    "External source requires a versioned acquisition or retrieval procedure.",
                    str(source_id),
                )
            )
        if external_source:
            _check_external_verification(root, str(source_id), value, path_value, findings)
        if source_path and source_path.exists() and _uncommitted_outside_raw(root, path_value):
            findings.append(
                _finding(
                    "P1",
                    "provenance",
                    "source-storage",
                    "A snapshot source must be in data/raw or committed to Git. Snapshot it "
                    "through acquisition, or declare storage: in_place with a reason.",
                    str(source_id),
                )
            )
        if source_path and source_path.exists() and checksum:
            covered_raw.update(_check_source_bytes(source_path, str(source_id), checksum, findings))
    uncovered = [path for path in raw_files if path.resolve() not in covered_raw]
    if uncovered and sources:
        findings.append(
            _finding(
                "P1",
                "provenance",
                "raw-source-coverage",
                "Some local raw snapshots are not covered by a source path and checksum.",
                f"uncovered_count={len(uncovered)}",
                sensitive=True,
            )
        )


def _check_tree_checksum(
    source_path: Path,
    source_id: str,
    kind: str,
    expected_digest: str,
    findings: list[Finding],
) -> None:
    """Compare a source directory with its tree checksum, and flag the ambiguous v1 format."""
    try:
        if kind == "tree":
            actual_digest: str | None = _cached_tree_sha256(source_path)
        elif kind == "tree-v2":
            actual_digest = _tree_sha256_v2(source_path)
        else:
            actual_digest = None
    except (OSError, RuntimeError):
        actual_digest = None
    if actual_digest != expected_digest:
        findings.append(
            _finding(
                "P0",
                "data-safety",
                "raw-checksum",
                "A local source directory does not match its tree checksum.",
                source_id,
                sensitive=True,
            )
        )
    elif kind == "tree":
        findings.append(_legacy_tree_finding(source_id))


def source_checksum(path: Path) -> dict[str, Any]:
    """Return the raw_checksum value for a local file or directory."""
    return {"path": str(path), "checksum": _retrieved_digest(path)}


def _spatial_document(root: Path) -> tuple[dict[str, Any] | None, str | None]:
    """Return the optional spatial extension, or why it cannot be read."""
    path = root / "data/spatial.yml"
    if not path.exists():
        return None, None
    if yaml is None:
        return None, "PyYAML is unavailable"
    try:
        document = yaml.safe_load(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, ValueError, yaml.YAMLError) as exc:
        return None, f"data/spatial.yml is invalid: {exc}"
    if not isinstance(document, dict) or document.get("schema_version") != 1:
        return None, "data/spatial.yml must be a mapping with schema_version: 1"
    return document, None


def _spatial_validator_entries(document: dict[str, Any]) -> tuple[list[list[str]], list[str]]:
    """Return runnable validator commands and a description of every malformed entry."""
    validators = document.get("validators", [])
    if not isinstance(validators, list):
        return [], ["validators must be a list of command arrays"]
    commands: list[list[str]] = []
    problems: list[str] = []
    for index, command in enumerate(validators):
        if (
            isinstance(command, list)
            and command
            and all(isinstance(part, str) and part and "\0" not in part for part in command)
        ):
            commands.append(command)
        else:
            problems.append(f"validators[{index}] must be a non-empty array of strings without NUL")
    return commands, problems


def _spatial_validators(root: Path) -> list[list[str]]:
    """Validators run only when every declared entry is well formed."""
    document, _ = _spatial_document(root)
    if document is None:
        return []
    commands, problems = _spatial_validator_entries(document)
    return [] if problems else commands


def _positive_number(value: object) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool) and value > 0


def _spatial_text(value: object) -> bool:
    """A real, non-placeholder value in its original type (YAML dates allowed for dates)."""
    if isinstance(value, (date, datetime)):
        return True
    return isinstance(value, str) and _has_text_source_evidence(value)


def _known_spatial_value(field: str, value: object) -> bool:
    if field == "nodata":
        # Numeric zero is a real nodata value; empty or placeholder text is missing evidence.
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            return True
        return _spatial_text(value)
    if field == "vertical_datum":
        return _spatial_text(value) or (isinstance(value, dict) and _spatial_text(value.get("id")))
    required = {
        "crs": ("id", "axis_order", "units"),
        "temporal_extent": ("start", "end"),
        "resolution": ("units",),
        "geometry_validity": ("method", "result"),
    }[field]
    if not isinstance(value, dict):
        return False
    if not all(_spatial_text(value.get(key)) for key in required):
        return False
    if field == "resolution":
        return _positive_number(value.get("x")) and _positive_number(value.get("y"))
    return True


def _spatial_record_problems(record: object) -> tuple[list[str], list[str]]:
    """Return (invalid fields, unresolved fields) for one spatial record."""
    if not isinstance(record, dict):
        return ["record"], []
    invalid: list[str] = []
    unresolved: list[str] = []
    for field in SPATIAL_FIELDS:
        state = record.get(field)
        status = state.get("status") if isinstance(state, dict) else None
        if not isinstance(state, dict) or not isinstance(status, str):
            invalid.append(field)
        elif status == "known":
            # Checked here, not by _epistemic_state, so a valid falsy value such as nodata 0 passes.
            if "value" not in state or not _known_spatial_value(field, state["value"]):
                invalid.append(field)
        else:
            valid, field_unresolved = _epistemic_state(state)
            if not valid:
                invalid.append(field)
            elif field_unresolved:
                unresolved.append(field)
    steps = record.get("reprojection", [])
    if not isinstance(steps, list) or not all(
        isinstance(step, dict)
        and all(_spatial_text(step.get(key)) for key in ("from", "to", "method"))
        for step in steps
    ):
        invalid.append("reprojection")
    return invalid, unresolved


def _check_spatial(root: Path, findings: list[Finding]) -> None:
    """Check the optional spatial extension. Absent means not declared, never a pass."""
    document, error = _spatial_document(root)
    if error is not None:
        findings.append(
            _finding("P1", "spatial", "spatial-metadata", "Spatial metadata is invalid.", error)
        )
        return
    if document is None:
        return
    sources_path = root / "data/sources.yml"
    try:
        provenance = yaml.safe_load(sources_path.read_text(encoding="utf-8")) or {}
    except (OSError, yaml.YAMLError):
        provenance = {}
    declared_sources = provenance.get("sources") if isinstance(provenance, dict) else None
    known_sources = set(declared_sources) if isinstance(declared_sources, dict) else set()
    entries: list[tuple[str, object]] = []
    for section in ("sources", "outputs"):
        records = document.get(section, {})
        if not isinstance(records, dict):
            findings.append(
                _finding(
                    "P1",
                    "spatial",
                    "spatial-metadata",
                    "Spatial metadata sections must be mappings.",
                    section,
                )
            )
            continue
        for key, record in sorted(records.items(), key=lambda item: str(item[0])):
            name = f"{section}.{key}"
            if section == "sources" and key not in known_sources:
                findings.append(
                    _finding(
                        "P1",
                        "spatial",
                        "spatial-source",
                        "Spatial metadata names a source not declared in data/sources.yml.",
                        name,
                    )
                )
            if section == "outputs":
                try:
                    _safe_managed_path(root, str(key))
                except ValueError:
                    findings.append(
                        _finding(
                            "P1",
                            "spatial",
                            "spatial-output",
                            "Spatial output path is unsafe.",
                            name,
                        )
                    )
                    continue
            entries.append((name, record))
    for name, record in entries:
        invalid, unresolved = _spatial_record_problems(record)
        if invalid:
            findings.append(
                _finding(
                    "P1",
                    "spatial",
                    "spatial-metadata",
                    "Spatial evidence is missing, malformed, or lacks its value or reason.",
                    f"{name}: {', '.join(invalid)}",
                )
            )
        if unresolved:
            findings.append(
                _finding(
                    "P1",
                    "spatial",
                    "spatial-evidence-unresolved",
                    "Spatial evidence is explicitly unresolved and cannot support release.",
                    f"{name}: {', '.join(unresolved)}",
                )
            )
    _, validator_problems = _spatial_validator_entries(document)
    for problem in validator_problems:
        findings.append(
            _finding(
                "P1",
                "spatial",
                "spatial-metadata",
                "Spatial validators are malformed, so none were run.",
                problem,
            )
        )
    if entries and not validator_problems and not _spatial_validators(root):
        findings.append(
            _finding(
                "P1",
                "spatial",
                "spatial-unvalidated",
                (
                    "Spatial metadata is declared but no project-defined validator checks it "
                    "against the data. Declare `validators` in data/spatial.yml."
                ),
                "data/spatial.yml",
            )
        )


# --- validation responsibility ---


def _ship_ready_runs_strict_audit(text: str, *, ci: bool = False) -> bool:
    lines = text.splitlines()
    targets = [
        index
        for index, line in enumerate(lines)
        # ship-ready may take one optional analysis key (see the project justfile).
        if re.match(r"^" + ("ci-check" if ci else r'ship-ready(\s+analysis="")?') + r"\s*:", line)
    ]
    if len(targets) != 1:
        return False
    takes_analysis = not ci and "analysis" in lines[targets[0]].partition(":")[0]
    previous = targets[0] - 1
    while previous >= 0 and not lines[previous].strip():
        previous -= 1
    if previous >= 0 and lines[previous].lstrip().startswith("["):
        return False  # Script/interpreter attributes are not a plain audit recipe.
    index = targets[0] + 1
    recipe_lines: list[str] = []
    while index < len(lines):
        line = lines[index]
        if line and not line[0].isspace():
            break
        if line.lstrip().startswith("#!"):
            return False
        if line.strip() and not line.lstrip().startswith("#"):
            recipe_lines.append(line.strip())
        index += 1
    if len(recipe_lines) != 1:
        return False  # Additional script commands can mask audit failures.
    expected = [
        "uv",
        "run",
        "--locked",
        "python",
        ".astack/workflow.py",
        "audit",
        "--format",
        "text",
        "--run-tools",
        "--strict",
    ]
    if ci:
        expected.append("--ci")
    # A recipe that takes an analysis must pass it, through just's quote() and nothing else:
    # extra shell quotes around the interpolation would undo quote() and let the key run code.
    interpolation = "{{quote(analysis)}}"
    for line in recipe_lines:
        if re.search(r"\|\||&&|[|;&`<>]|\$\(", line) or "#" in line:
            continue
        if takes_analysis:
            raw = line.split()
            if raw[-2:] != ["--analysis", interpolation] or line.count("{{") != 1:
                continue
            line = " ".join(raw[:-2])
        elif "{{" in line:
            continue
        try:
            tokens = shlex.split(line, comments=False)
        except ValueError:
            continue
        if tokens == expected:
            return True
    return False


def _workflow_steps(text: str) -> tuple[set[str], list[tuple[str, bool]]] | None:
    if yaml is None:
        return None
    try:
        value = yaml.safe_load(text)
    except yaml.YAMLError:
        return None
    if not isinstance(value, dict):
        return None
    on_value = value.get("on", value.get(True))
    if isinstance(on_value, str):
        triggers = {on_value}
    elif isinstance(on_value, list):
        triggers = {str(trigger) for trigger in on_value}
    elif isinstance(on_value, dict):
        triggers = {str(trigger) for trigger in on_value}
    else:
        triggers = set()
    relevant = triggers & {"pull_request", "pull_request_target", "push"}
    jobs = value.get("jobs")
    if not isinstance(jobs, dict):
        return relevant, []
    run_values = []
    for job in jobs.values():
        if not isinstance(job, dict) or not isinstance(job.get("steps"), list):
            continue
        job_continue_on_error = job.get("continue-on-error")
        job_active = "if" not in job and (
            job_continue_on_error is None
            or job_continue_on_error is False
            or (
                isinstance(job_continue_on_error, str)
                and job_continue_on_error.strip().casefold() == "false"
            )
        )
        for step in job["steps"]:
            if isinstance(step, dict) and isinstance(step.get("run"), str):
                continue_on_error = step.get("continue-on-error")
                active = (
                    job_active
                    and "if" not in step
                    and (
                        continue_on_error is None
                        or continue_on_error is False
                        or (
                            isinstance(continue_on_error, str)
                            and continue_on_error.strip().casefold() == "false"
                        )
                    )
                )
                run_values.append((step["run"].strip(), active))
    return relevant, run_values


def _check_structure(root: Path, findings: list[Finding]) -> None:
    scaffold = _scaffold_layout_applies(root)
    required = ["AGENTS.md"]
    if scaffold:
        required += ["README.md", "pyproject.toml", "justfile"]
    if _science_applies(root):
        required.append("data/sources.yml")
    for relative in required:
        if not (root / relative).exists():
            findings.append(
                _finding(
                    "P1",
                    "workflow",
                    "required-file",
                    "Required baseline file is missing.",
                    relative,
                )
            )
    if not scaffold:
        # A General project keeps its own build, lockfile, and CI. Only the layout that
        # `astack new` creates promises `uv.lock`, a `ship-ready` recipe, and CI that runs it.
        return
    if not (root / "uv.lock").exists():
        findings.append(
            _finding(
                "P1",
                "reproducibility",
                "dependency-lock",
                "Dependency lockfile is missing. Run `uv lock` and commit it.",
                "uv.lock",
            )
        )
    pyproject = root / "pyproject.toml"
    if pyproject.exists() and "[build-system]" not in pyproject.read_text(encoding="utf-8"):
        findings.append(
            _finding(
                "P1",
                "reproducibility",
                "package-install",
                "Python package build configuration is missing.",
                "pyproject.toml",
            )
        )
    justfile = root / "justfile"
    if justfile.exists():
        text = justfile.read_text(encoding="utf-8")
        if not _ship_ready_runs_strict_audit(text) or "|| true" in text:
            findings.append(
                _finding(
                    "P1",
                    "workflow",
                    "ship-ready",
                    (
                        "Shipping must directly run the managed audit with --run-tools and "
                        "--strict without suppressing failures."
                    ),
                    "justfile",
                )
            )
    workflow_dir = root / ".github" / "workflows"
    workflows = list(workflow_dir.glob("*.yml")) + list(workflow_dir.glob("*.yaml"))
    if not workflows:
        findings.append(
            _finding(
                "P2",
                "reproducibility",
                "ci",
                "No GitHub Actions validation workflow was found.",
                ".github/workflows",
            )
        )
    else:
        validation_workflows = []
        invalid_validation_workflows = []
        unparseable_workflows = []
        for path in workflows:
            text = path.read_text(encoding="utf-8")
            parsed = _workflow_steps(text)
            if parsed is None:
                unparseable_workflows.append(path.relative_to(root).as_posix())
                continue
            triggers, run_values = parsed
            if not triggers:
                continue
            relative = path.relative_to(root).as_posix()
            validation_workflows.append(relative)
            ci_recipe = False
            try:
                ci_declaration = _project_config(root).get("ci")
            except (OSError, ValueError):
                pass  # Project configuration validation reports the actual failure.
            else:
                ci_recipe = (
                    ci_declaration == {"mode": "local-only-sources"}
                    and justfile.exists()
                    and _ship_ready_runs_strict_audit(justfile.read_text(), ci=True)
                )
            if not any(
                active and (value == "just ship-ready" or (ci_recipe and value == "just ci-check"))
                for value, active in run_values
            ):
                invalid_validation_workflows.append(str(path.relative_to(root)))
        if unparseable_workflows:
            findings.append(
                _finding(
                    "P1",
                    "workflow",
                    "ci-workflow-parse",
                    "CI workflow YAML could not be parsed safely.",
                    ", ".join(sorted(unparseable_workflows)),
                )
            )
        if not validation_workflows:
            findings.append(
                _finding(
                    "P1",
                    "workflow",
                    "ci-ship-ready",
                    (
                        "CI has no applicable pull_request or push validation workflow. "
                        "At least one must run exact `run: just ship-ready`."
                    ),
                    ".github/workflows",
                )
            )
        elif invalid_validation_workflows:
            findings.append(
                _finding(
                    "P1",
                    "workflow",
                    "ci-ship-ready",
                    (
                        "CI validation workflows must contain an active exact "
                        "`run: just ship-ready` step."
                    ),
                    ", ".join(sorted(invalid_validation_workflows)),
                )
            )


def _check_stage_purposes(root: Path, findings: list[Finding]) -> None:
    """A stage script with no docstring leaves its review page without a purpose."""
    import ast

    try:
        pipeline = (root / "dvc.yaml").read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return
    for path in sorted((root / "scripts").glob("*.py")) if (root / "scripts").is_dir() else []:
        relative = path.relative_to(root).as_posix()
        if relative not in pipeline:
            continue
        try:
            documented = ast.get_docstring(ast.parse(path.read_bytes()))
        except (OSError, SyntaxError, ValueError):
            continue
        if not documented:
            findings.append(
                _finding(
                    "P2",
                    "workflow",
                    "stage-script-purpose",
                    "This stage script has no docstring, so its review page has no purpose line.",
                    relative,
                )
            )


def _check_evidence(root: Path, findings: list[Finding]) -> None:
    _check_stage_purposes(root, findings)
    reports = list((root / "reports").rglob("*.qmd")) if (root / "reports").exists() else []
    notebooks = [
        path
        for path in ((root / "notebooks").rglob("*.py") if (root / "notebooks").exists() else [])
        if not _viewer_notebook(root, path)
    ]
    analysis_code = [
        path
        for folder in (root / "src", root / "scripts")
        if folder.exists()
        for path in folder.rglob("*.py")
        if path.name != "__init__.py"
    ]
    legacy_qa_files = (
        [path for path in (root / "reports" / "qa").rglob("*") if path.is_file()]
        if (root / "reports" / "qa").exists()
        else []
    )
    evidence_files = (
        [path for path in (root / "evidence").rglob("*") if path.is_file()]
        if (root / "evidence").exists()
        else []
    )
    durable_evidence = evidence_files or legacy_qa_files
    if reports and not durable_evidence:
        findings.append(
            _finding(
                "P1",
                "scientific-evidence",
                "report-qa",
                "A narrative report exists without durable QA artifacts.",
                f"reports={len(reports)}, evidence_files=0",
            )
        )
    if notebooks and not analysis_code and not durable_evidence:
        findings.append(
            _finding(
                "P1",
                "scientific-evidence",
                "notebook-only-analysis",
                "Notebooks appear to be the only analytical implementation and evidence location.",
                f"notebooks={len(notebooks)}, reusable_or_script_files=0, evidence_files=0",
            )
        )


def _classify_output_path(relative: str) -> dict[str, str | None]:
    windows_path = PureWindowsPath(relative)
    normalized = relative.replace("\\", "/").strip("/")
    parts = Path(normalized).parts
    if (
        not normalized
        or windows_path.is_absolute()
        or windows_path.drive
        or Path(relative).is_absolute()
        or any(part in {"", ".", ".."} for part in parts)
    ):
        return {"lifecycle": "invalid", "component": None, "problem": "unsafe-path"}
    if normalized == "data/raw" or normalized.startswith("data/raw/"):
        return {"lifecycle": "raw", "component": None, "problem": None}
    if normalized == "data/manual" or normalized.startswith("data/manual/"):
        return {"lifecycle": "manual", "component": None, "problem": None}
    if normalized == "scratch" or normalized.startswith("scratch/"):
        return {"lifecycle": "scratch", "component": None, "problem": None}
    if normalized == ".cache" or normalized.startswith(".cache/"):
        return {"lifecycle": "routine", "component": None, "problem": None}
    if normalized == "reports/qa" or normalized.startswith("reports/qa/"):
        return {"lifecycle": "legacy-evidence", "component": None, "problem": "legacy-path"}
    for prefix, lifecycle in COMPONENT_LIFECYCLES.items():
        if normalized == prefix:
            return {"lifecycle": lifecycle, "component": None, "problem": None}
        if normalized.startswith(f"{prefix}/"):
            component = normalized.removeprefix(f"{prefix}/").split("/", 1)[0]
            problem = None if COMPONENT_PATTERN.fullmatch(component) else "invalid-component"
            return {"lifecycle": lifecycle, "component": component, "problem": problem}
    if normalized == "reports" or normalized.startswith("reports/"):
        return {"lifecycle": "report", "component": None, "problem": None}
    return {"lifecycle": "other", "component": None, "problem": None}


def _output_policy(config: dict[str, Any]) -> tuple[bool, set[str]]:
    outputs = config.get("outputs", {})
    if not isinstance(outputs, dict) or outputs.get("layout") != "component":
        return False, set()
    components = outputs.get("components", [])
    if not isinstance(components, list):
        return True, set()
    return True, {component for component in components if isinstance(component, str)}


def _check_output_layout(root: Path, config: dict[str, Any], findings: list[Finding]) -> None:
    component_layout, declared = _output_policy(config)
    priority = "P1" if component_layout else "P2"
    roots = [Path(prefix) for prefix in COMPONENT_LIFECYCLES]
    roots.extend([Path("reports/qa"), Path("reports")])
    # The scientific output registry's evidence file is project metadata, not a generated
    # output, and its documented home is evidence/<name>.yml.
    registry = config.get("scientific_outputs")
    evidence_path = registry.get("evidence_path") if isinstance(registry, dict) else None
    seen: set[str] = set()
    if isinstance(evidence_path, str):
        evidence_file = Path(evidence_path)
        # The registry loader's own rule: relative, no `..`, confined to evidence/.
        if (
            not evidence_file.is_absolute()
            and ".." not in evidence_file.parts
            and evidence_file.parts[:1] == ("evidence",)
        ):
            seen.add(evidence_file.as_posix())  # Same spelling as the walk below (`./`, `//`).
    for output_root in roots:
        absolute_root = root / output_root
        if not absolute_root.exists():
            continue
        for path in absolute_root.rglob("*"):
            if not path.is_file():
                continue
            relative = path.relative_to(root).as_posix()
            if relative in seen:
                continue
            seen.add(relative)
            classification = _classify_output_path(relative)
            lifecycle = classification["lifecycle"]
            component = classification["component"]
            problem = classification["problem"]
            if lifecycle == "legacy-evidence":
                findings.append(
                    _finding(
                        priority,
                        "workflow",
                        "legacy-output-path",
                        "Machine-readable QA belongs under evidence/<component>/, not reports/qa/.",
                        relative,
                    )
                )
                continue
            if (
                lifecycle in {"figure", "table", "report"}
                and path.suffix.casefold() in MACHINE_OUTPUT_SUFFIXES
            ):
                findings.append(
                    _finding(
                        priority,
                        "workflow",
                        "machine-output-in-reports",
                        "Machine-readable outputs belong under artifacts/ or evidence/.",
                        relative,
                    )
                )
                continue
            if lifecycle in COMPONENT_LIFECYCLES.values():
                if problem or component is None:
                    findings.append(
                        _finding(
                            priority,
                            "workflow",
                            "component-output-path",
                            "Generated outputs must use a valid lifecycle/<component>/file path.",
                            relative,
                        )
                    )
                elif component_layout and component not in declared:
                    findings.append(
                        _finding(
                            "P1",
                            "workflow",
                            "undeclared-component",
                            "Output path uses a component not declared in .astack/project.toml.",
                            f"component={component}, path={relative}",
                        )
                    )
                continue


def _run_required_tool(
    root: Path,
    findings: list[Finding],
    *,
    check: str,
    configured_path: str,
    args: list[str],
    session: Any = None,
    stage_name: str | None = None,
) -> None:
    try:
        result = (
            session.run_command(stage_name or check, args)
            if session is not None
            else _run(args, cwd=root)
        )
    except FileNotFoundError:
        findings.append(
            _finding(
                "P1",
                "reproducibility",
                f"{check}-availability",
                "A configured validation tool is unavailable.",
                configured_path,
            )
        )
        return
    if result.returncode != 0:
        findings.append(
            _finding(
                "P1",
                "reproducibility",
                f"{check}-runtime",
                "A configured validation command failed.",
                " ".join(args),
            )
        )


def _configured_capabilities(root: Path, findings: list[Finding]) -> set[str]:
    path = root / ".astack/project.toml"
    if not path.exists():
        return set()
    try:
        value = tomllib.loads(path.read_text(encoding="utf-8"))
        capabilities = value.get("tools", [])
    except (tomllib.TOMLDecodeError, OSError, AttributeError):
        return set()
    supported = {"dvc", "marimo", "quarto"}
    if not isinstance(capabilities, list) or any(
        not isinstance(capability, str) or capability not in supported
        for capability in capabilities
    ):
        findings.append(
            _finding(
                "P1",
                "workflow",
                "capabilities",
                "Project tools declaration is invalid.",
                ".astack/project.toml",
            )
        )
        return set()
    return set(capabilities)


def _check_optional_tools(
    root: Path,
    findings: list[Finding],
    run_tools: bool,
    *,
    ensure_dvc_cache: Callable[[Path], Path],
    session: Any = None,
    ci: bool = False,
) -> None:
    """`ensure_dvc_cache` comes from the reproduction module, which itself imports this one."""
    software_path = "justfile"
    configured: dict[str, list[list[str]]] = {
        "software": [["just", "check"], ["just", "integration"]]
    }
    if not _scaffold_layout_applies(root):
        # A General project has no astack justfile. Run its own declared CHECK instead.
        software_path = ".astack/project.toml"
        software = _general_check_commands(root, findings)
        if software:
            configured["software"] = software
        else:
            del configured["software"]
    else:
        configured["software"] += _scientific_verify_commands(root, findings) or []
    capabilities = _configured_capabilities(root, findings)
    dvc_present = (root / ".dvc/config").exists() or (root / "dvc.yaml").exists()
    reports = sorted((root / "reports").rglob("*.qmd")) if (root / "reports").exists() else []
    notebooks = sorted((root / "notebooks").rglob("*.py")) if (root / "notebooks").exists() else []
    discovered = {
        capability
        for capability, present in {
            "dvc": dvc_present,
            "quarto": bool(reports),
            "marimo": bool(notebooks),
        }.items()
        if present
    }
    for capability in sorted(discovered - capabilities):
        findings.append(
            _finding(
                "P1",
                "workflow",
                "unregistered-capability",
                "Capability files exist but the capability is not declared in project state.",
                capability,
            )
        )
    if "dvc" in capabilities:
        if not (root / ".dvc/config").exists():
            findings.append(
                _finding(
                    "P1",
                    "workflow",
                    "dvc-configuration",
                    "DVC capability is declared but its project configuration is incomplete.",
                    ".dvc/config is required",
                )
            )
        configured["dvc"] = [["uv", "run", "--locked", "dvc", "status"]]
        if (root / "dvc.yaml").exists():
            configured["dvc"].append(
                ["uv", "run", "--locked", "dvc", "repro", "--dry", "--allow-missing"]
            )
    if "quarto" in capabilities:
        if not reports:
            findings.append(
                _finding(
                    "P1",
                    "workflow",
                    "quarto-configuration",
                    "Quarto capability is declared but no report source exists.",
                    "reports/**/*.qmd",
                )
            )
        configured["quarto"] = [
            ["quarto", "render", str(path.relative_to(root))] for path in reports
        ]
    if "marimo" in capabilities:
        if not notebooks:
            findings.append(
                _finding(
                    "P1",
                    "workflow",
                    "marimo-configuration",
                    "Marimo capability is declared but no notebook source exists.",
                    "notebooks/**/*.py",
                )
            )
        configured["marimo"] = [
            ["uv", "run", "--locked", "marimo", "check", str(path.relative_to(root))]
            for path in notebooks
        ]
    spatial_validators = _spatial_validators(root)
    if spatial_validators:
        configured["spatial"] = spatial_validators
    if not run_tools:
        for capability in configured:
            findings.append(
                _finding(
                    "P2",
                    "reproducibility",
                    f"{capability}-not-run",
                    "Configured runtime validation was not performed.",
                    "rerun with --run-tools",
                )
            )
        return
    dvc_cache_failed = False
    if "dvc" in capabilities and not ci:
        try:
            ensure_dvc_cache(root)
        except (OSError, RuntimeError, ValueError) as exc:
            dvc_cache_failed = True
            findings.append(
                _finding(
                    "P1",
                    "reproducibility",
                    "dvc-cache-configuration",
                    "The repository-local DVC cache could not be configured.",
                    str(exc),
                )
            )
    for capability, commands in configured.items():
        if capability == "dvc" and dvc_cache_failed:
            continue
        if ci and capability != "software":
            findings.append(
                _finding(
                    "P2",
                    "reproducibility",
                    f"{capability}-not-run",
                    "Limited CI does not execute source-dependent rendering/reproduction tools.",
                    "Strict local ship-ready remains required.",
                )
            )
            continue
        configured_path = {
            "software": software_path,
            "dvc": "dvc.yaml",
            "quarto": "reports/",
            "marimo": "notebooks/",
            "spatial": "data/spatial.yml",
        }[capability]
        for index, args in enumerate(commands):
            stage_name = capability
            if capability != "software":
                stage_name = f"capability.{capability}.{index + 1}"
            elif software_path != "justfile":
                stage_name = general_stage_names(len(commands))[index]
            elif index == 0:
                stage_name = "check"
            elif index == 1:
                stage_name = "integration"
            else:
                stage_name = verify_stage_names(len(commands) - 2)[index - 2]
            _run_required_tool(
                root,
                findings,
                check=capability,
                configured_path=configured_path,
                args=args,
                session=session,
                stage_name=stage_name,
            )


def _general_check_commands(root: Path, findings: list[Finding]) -> list[list[str]]:
    """CHECK argv for a General project, plus VERIFY when scientific validation declares it.

    Uses the same parser as `validate`, so the audit accepts and rejects exactly what it does.
    """
    try:
        commands = list(validation_commands(root, "check"))
    except ValueError as exc:
        findings.append(_software_config_finding(exc))
        return []
    verify = _scientific_verify_commands(root, findings)
    if verify is None:
        return []
    return commands + verify


def _scientific_verify_commands(root: Path, findings: list[Finding]) -> list[list[str]] | None:
    """VERIFY argv for a project that enables scientific validation.

    Undeclared VERIFY is reported as not run, never as a pass. It blocks only a material
    analysis, which a deliverable relies on. Exploratory work still sees the finding. Returns
    None when the declaration is malformed.
    """
    config = _project_config(root)
    capabilities = config.get("capabilities", [])
    if not isinstance(capabilities, list) or SCIENCE_CAPABILITIES[1] not in capabilities:
        return []
    declared = config.get("validation", {})
    if isinstance(declared, dict) and "verify" not in declared:
        analysis = config.get("analysis", {})
        material = isinstance(analysis, dict) and analysis.get("stage") == "material"
        findings.append(
            _finding(
                "P1" if material else "P2",
                "scientific-evidence",
                "verify-undeclared",
                "Scientific validation is enabled but validation.verify is not declared, "
                "so VERIFY did not run.",
                "declare validation.verify in .astack/project.toml"
                + ("" if material else " before analysis.stage becomes material"),
            )
        )
        return []
    try:
        return list(validation_commands(root, "verify"))
    except ValueError as exc:
        findings.append(_software_config_finding(exc))
        return None


def _software_config_finding(exc: ValueError) -> Finding:
    return _finding(
        "P1",
        "workflow",
        "software-config",
        "The declared validation commands cannot be run.",
        str(exc),
    )


def verify_stage_names(count: int) -> list[str]:
    """Session stage names for VERIFY commands that a scaffolded project runs after CHECK."""
    return ["verify" if index == 0 else f"verify.{index + 1}" for index in range(count)]


def general_stage_names(count: int) -> list[str]:
    """Session stage names for a General project's own commands."""
    return ["check" if index == 0 else f"check.{index + 1}" for index in range(count)]


def _project_config(root: Path) -> dict[str, Any]:
    return dict(project_config(root))


def _validation_commands(
    config: dict[str, Any],
) -> tuple[dict[str, list[list[str]]], list[str]]:
    declaration = config.get("validation")
    if declaration is None:
        return {}, []
    if not isinstance(declaration, dict):
        return {}, ["validation must be a table"]

    # CHECK runs through the shared project policy. VERIFY and RELEASE are interpreted here.
    errors = [
        f"unsupported tier {key!r}"
        for key in declaration
        if key not in ("check", *VALIDATION_TIERS)
    ]
    commands: dict[str, list[list[str]]] = {}
    for tier in VALIDATION_TIERS:
        if tier not in declaration:
            continue
        value = declaration[tier]
        if not isinstance(value, list) or not value:
            errors.append(f"validation.{tier} must contain one or more command arrays")
            continue
        if any(
            not isinstance(command, list)
            or not command
            or any(not isinstance(part, str) or not part for part in command)
            for command in value
        ):
            errors.append(f"validation.{tier} must contain non-empty string command arrays")
            continue
        commands[tier] = value
    return commands, errors


def _check_validation_config(config: dict[str, Any], findings: list[Finding]) -> None:
    _, errors = _validation_commands(config)
    for error in errors:
        findings.append(
            _finding(
                "P1",
                "workflow",
                "validation-config",
                "Validation tier configuration is invalid.",
                error,
            )
        )


# --- pipeline responsibility ---


def _safe_pipeline_path(value: object) -> str | None:
    text = str(value or "").strip()
    path = Path(text)
    windows_path = PureWindowsPath(text)
    if (
        not text
        or path.is_absolute()
        or windows_path.is_absolute()
        or windows_path.drive
        or any(part in {"", ".", ".."} for part in path.parts)
    ):
        return None
    return path.as_posix()


def _has_symlink_component(path: Path) -> bool:
    system_links = {Path("/tmp"), Path("/var"), Path("/etc")} if sys.platform == "darwin" else set()
    current = Path(path.anchor) if path.anchor else Path(".")
    for part in path.parts[1:] if path.anchor else path.parts:
        current = current / part
        if current in system_links:
            continue
        if current.is_symlink():
            return True
    return False


def _verify_private_ancestors(path: Path, *, label: str) -> None:
    if os.name == "nt":
        return
    system_links = {Path("/tmp"), Path("/var"), Path("/etc")} if sys.platform == "darwin" else set()
    parent = path.parent
    current = Path(parent.anchor) if parent.anchor else Path(".")
    for part in parent.parts[1:] if parent.anchor else parent.parts:
        current = current / part
        if current in system_links:
            continue
        if not current.exists():
            break
        info = current.stat()
        if info.st_uid not in {0, os.getuid()}:
            raise RuntimeError(f"Refusing to use {label} under a directory owned by another user")
        if info.st_mode & 0o022 != 0 and not (info.st_mode & stat.S_ISVTX):
            raise RuntimeError(f"Refusing to use {label} under a directory writable by other users")


def _verify_private_directory(path: Path, *, label: str, allow_other_read: bool = False) -> None:
    if _has_symlink_component(path):
        raise RuntimeError(f"Refusing to use a symlinked {label}")
    _verify_private_ancestors(path, label=label)
    if os.name != "nt" and path.exists():
        info = path.stat()
        forbidden = 0o022 if allow_other_read else 0o077
        if info.st_uid != os.getuid() or info.st_mode & forbidden != 0:
            detail = "writable by" if allow_other_read else "accessible to"
            raise RuntimeError(f"Refusing to use {label} {detail} other users")


def _ensure_private_directory(path: Path, *, label: str) -> None:
    # DVC's diskcache state uses pickle (CVE-2025-69872) and DVC creates site_cache_dir/repo with
    # mode 0777, so keep cache and state dirs owner-only on POSIX and refuse previously
    # group/other-writable directories or writable parents instead of reusing tampered contents.
    if _has_symlink_component(path):
        raise RuntimeError(f"Refusing to configure {label} through a symlink")
    _verify_private_ancestors(path, label=label)
    if os.name != "nt" and path.exists():
        info = path.stat()
        if info.st_uid != os.getuid() or info.st_mode & 0o022 != 0:
            raise RuntimeError(f"Refusing to reuse {label} writable by other users")
    path.mkdir(mode=0o700, parents=True, exist_ok=True)
    if os.name != "nt":
        os.chmod(path, 0o700)


def _unquote_dvc_config_value(raw: str) -> str:
    # DVC loads .dvc/config with ConfigObj, which strips outer quotes and inline # comments.
    value = raw.strip()
    for quote in ('"""', "'''", '"', "'"):
        if value.startswith(quote):
            end = value.find(quote, len(quote))
            if end != -1 and not value[end + len(quote) :].split("#", 1)[0].strip():
                return value[len(quote) : end]
    return value.split("#", 1)[0].strip()


def _quote_dvc_config_value(value: str) -> str:
    # ConfigObj treats unquoted `#` as an inline comment, so quote paths written to config.local.
    if "\n" in value or "\r" in value:
        raise RuntimeError("DVC cache path cannot contain line breaks")
    if '"' not in value:
        return f'"{value}"'
    if "'" not in value:
        return f"'{value}'"
    if '"""' not in value and not value.endswith('"'):
        return f'"""{value}"""'
    if "'''" not in value and not value.endswith("'"):
        return f"'''{value}'''"
    raise RuntimeError("DVC cache path cannot be safely serialized in DVC config")


def _unquote_dvc_section_name(raw: str) -> str:
    # Inside `[...]`, `#` is part of the section name; strip only matching outer quotes.
    value = raw.strip()
    for quote in ('"""', "'''", '"', "'"):
        if len(value) >= 2 * len(quote) and value.startswith(quote) and value.endswith(quote):
            return value[len(quote) : -len(quote)]
    return value


def _normalize_dvc_section_headers(text: str) -> str:
    # Match ConfigObj's section-header grammar so ConfigParser does not accept trailing garbage
    # or swallow bracketed inline comments like `[cache] # [note]` into the section name.
    pattern = re.compile(
        r"""^
        (\s*)
        ((?:\[\s*)+)
        (
            (?:"\s*\S.*?\s*")|
            (?:'\s*\S.*?\s*')|
            (?:[^'"\s].*?)
        )
        ((?:\s*\])+)
        \s*(\#.*)?
        $""",
        re.VERBOSE,
    )
    normalized: list[str] = []
    for raw_line in text.splitlines(keepends=True):
        if not raw_line.lstrip().startswith("["):
            normalized.append(raw_line)
            continue
        ending = "\n" if raw_line.endswith("\n") else ""
        stripped_line = raw_line.removesuffix("\n").removesuffix("\r")
        match = pattern.match(stripped_line)
        if match is None or match.group(2).count("[") != match.group(4).count("]"):
            raise RuntimeError("DVC configuration has an invalid section header")
        normalized.append(
            f"{match.group(1)}{match.group(2)}{match.group(3)}{match.group(4)}{ending}"
        )
    return "".join(normalized)


def _read_dvc_config_text(text: str, section: str, key: str) -> str | None:
    text = text.removeprefix("\ufeff")
    try:
        from configobj import ConfigObj, ConfigObjError  # type: ignore[import-not-found]
    except ImportError:
        normalized = _normalize_dvc_section_headers(text)
        parser = configparser.ConfigParser(interpolation=None)
        try:
            parser.read_string(normalized)
        except configparser.Error as exc:
            raise RuntimeError(f"DVC configuration is invalid: {exc}") from exc
        seen_section = False
        found: str | None = None
        for sec_name in parser.sections():
            if _unquote_dvc_section_name(sec_name).lower() != section:
                continue
            if seen_section:
                raise RuntimeError(f"Duplicate DVC configuration section: {section}") from None
            seen_section = True
            for raw_key, raw_value in parser.items(sec_name):
                if _unquote_dvc_config_value(raw_key).lower() == key:
                    if found is not None:
                        raise RuntimeError(
                            f"Duplicate DVC configuration for {section}.{key}"
                        ) from None
                    found = _unquote_dvc_config_value(raw_value)
        return found
    try:
        loaded = ConfigObj(io.StringIO(text)).dict()
    except ConfigObjError as exc:
        raise RuntimeError(f"DVC configuration is invalid: {exc}") from exc
    seen_section = False
    found = None
    for sec_name, values in loaded.items():
        if (
            not isinstance(sec_name, str)
            or sec_name.lower() != section
            or not isinstance(values, dict)
        ):
            continue
        if seen_section:
            raise RuntimeError(f"Duplicate DVC configuration section: {section}")
        seen_section = True
        for k, val in values.items():
            if isinstance(k, str) and k.lower() == key:
                if not isinstance(val, str):
                    raise RuntimeError(f"DVC configuration {section}.{key} must be a string")
                if found is not None:
                    raise RuntimeError(f"Duplicate DVC configuration for {section}.{key}")
                found = val
    return found


def _read_dvc_config_value(config_path: Path, section: str, key: str) -> str | None:
    if config_path.is_symlink():
        raise RuntimeError(f"Refusing to read symlinked DVC configuration: {config_path.name}")
    if not config_path.is_file():
        return None
    try:
        text = config_path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as exc:
        raise RuntimeError(f"DVC configuration is invalid: {exc}") from exc
    return _read_dvc_config_text(text, section, key)


def _set_dvc_config_value(
    parser: configparser.ConfigParser, section: str, key: str, value: str
) -> bool:
    matches = [
        name for name in parser.sections() if _unquote_dvc_section_name(name).lower() == section
    ]
    if len(matches) > 1:
        raise RuntimeError(f"Duplicate DVC configuration section: {section}")
    if matches:
        target_section = matches[0]
    else:
        parser.add_section(section)
        target_section = section
    key_matches = [
        (raw_key, raw_value)
        for raw_key, raw_value in parser.items(target_section)
        if _unquote_dvc_config_value(raw_key).lower() == key
    ]
    if len(key_matches) > 1:
        raise RuntimeError(f"Duplicate DVC configuration for {section}.{key}")
    if key_matches:
        existing_key, existing_value = key_matches[0]
        if existing_key == key and existing_value == value:
            return False
        if existing_key != key:
            parser.remove_option(target_section, existing_key)
    parser.set(target_section, key, value)
    return True


def _new_private_temp_site_cache() -> tempfile.TemporaryDirectory[str]:
    base = Path(tempfile.gettempdir())
    if _has_symlink_component(base):
        raise RuntimeError("Refusing to create a temporary DVC site cache through a symlink")
    _verify_private_ancestors(base / "probe", label="temporary DVC_SITE_CACHE_DIR")
    temp_dir = tempfile.TemporaryDirectory(prefix="astack-dvc-site-cache-")
    try:
        _verify_private_directory(Path(temp_dir.name), label="temporary DVC_SITE_CACHE_DIR")
    except Exception:
        temp_dir.cleanup()
        raise
    return temp_dir


def _configured_site_cache_dir(root: Path) -> tuple[Path | None, str]:
    # Match DVC's dvc.dirs.site_cache_dir(): use the exact DVC_SITE_CACHE_DIR string without
    # stripping whitespace or expanding ~ so validation checks the same path DVC opens.
    env_value = os.environ.get("DVC_SITE_CACHE_DIR")
    if env_value:
        raw = Path(env_value)
        return raw if raw.is_absolute() else root / raw, "env"
    for config_path in (root / ".dvc" / "config.local", root / ".dvc" / "config"):
        value = _read_dvc_config_value(config_path, "core", "site_cache_dir")
        if value is not None and value != "":
            raw = Path(value)
            return raw if raw.is_absolute() else root / raw, "config"
    return None, "default"


def _ensure_dvc_cache(root: Path) -> Path:
    config_path = root / ".dvc" / "config.local"
    tmp_dir = config_path.parent / "tmp"
    site_cache = tmp_dir / "site-cache"
    if (
        config_path.parent.is_symlink()
        or config_path.is_symlink()
        or tmp_dir.is_symlink()
        or site_cache.is_symlink()
    ):
        raise RuntimeError("Refusing to configure a DVC cache through a symlink")
    canonical = Path(canonical_checkout(root))
    raw_cache = Path(dvc_cache_configured_path(canonical))
    if _has_symlink_component(raw_cache):
        raise RuntimeError("Refusing to configure a DVC cache through a symlink")
    cache = Path(dvc_cache_root(canonical))
    if _has_symlink_component(cache):
        raise RuntimeError("Refusing to configure a DVC cache through a symlink")
    env_site, site_source = _configured_site_cache_dir(root)
    if site_source == "env" and env_site is not None:
        _verify_private_directory(env_site, label="DVC_SITE_CACHE_DIR")
        if not env_site.exists():
            _ensure_private_directory(env_site, label="DVC_SITE_CACHE_DIR")
    _ensure_private_directory(cache, label="DVC cache")
    config_path.parent.mkdir(parents=True, exist_ok=True)
    _ensure_private_directory(tmp_dir, label="DVC tmp directory")
    _ensure_private_directory(site_cache, label="DVC site_cache_dir")
    parser = configparser.ConfigParser(interpolation=None)
    original_text: str | None = None
    if config_path.exists():
        try:
            original_text = config_path.read_text(encoding="utf-8")
            cleaned = _normalize_dvc_section_headers(original_text.removeprefix("\ufeff"))
            parser.read_string(cleaned)
        except (OSError, UnicodeDecodeError, configparser.Error) as exc:
            raise RuntimeError(f"DVC local configuration is invalid: {exc}") from exc
    expected_cache = str(cache)
    expected_site_cache = str(site_cache.resolve())
    changed = _set_dvc_config_value(parser, "cache", "dir", _quote_dvc_config_value(expected_cache))
    changed = (
        _set_dvc_config_value(
            parser, "core", "site_cache_dir", _quote_dvc_config_value(expected_site_cache)
        )
        or changed
    )
    if changed:
        buffer = io.StringIO()
        parser.write(buffer)
        candidate_text = buffer.getvalue()
    else:
        candidate_text = original_text or ""
    if _read_dvc_config_text(candidate_text, "cache", "dir") != expected_cache:
        raise RuntimeError("DVC local cache.dir did not round-trip to the validated path")
    if _read_dvc_config_text(candidate_text, "core", "site_cache_dir") != expected_site_cache:
        raise RuntimeError("DVC local core.site_cache_dir did not round-trip to the validated path")
    if changed:
        config_path.write_text(candidate_text, encoding="utf-8")
    return cache


def _dvc_pipeline(
    root: Path,
    targets: list[str] | None = None,
    *,
    read_only: bool = False,
    stages_only: bool = False,
) -> tuple[dict[str, Any] | None, str]:
    """DVC's resolved stages and status, or None with the reason they could not be read.

    With targets, DVC also resolves which stages `dvc repro <targets>` would consider, and an
    unknown target fails the probe.
    Code review can use the stage declarations without hashing outputs or dependencies for status.
    """
    command = ["uv", "run", "--locked", "python", "-c", DVC_PIPELINE_PROBE]
    if stages_only:
        command.append("--stages-only")
    reading = read_only or _READ_ONLY["on"]
    temp_site_cache: tempfile.TemporaryDirectory[str] | None = None
    try:
        effective_site_cache: str | None = None
        if not reading:
            _ensure_dvc_cache(root)
            configured_site, site_source = _configured_site_cache_dir(root)
            if site_source == "env" and configured_site is not None:
                effective_site_cache = str(configured_site.resolve())
            else:
                effective_site_cache = str((root / ".dvc" / "tmp" / "site-cache").resolve())
        else:
            dvc_dir = root / ".dvc"
            tmp_dir = dvc_dir / "tmp"
            if dvc_dir.is_symlink() or tmp_dir.is_symlink():
                raise RuntimeError("Refusing to run DVC with a symlinked .dvc/tmp")
            _verify_private_directory(tmp_dir, label="DVC tmp directory", allow_other_read=True)
            configured_site, site_source = _configured_site_cache_dir(root)
            if site_source == "env" and configured_site is not None:
                _verify_private_directory(configured_site, label="DVC_SITE_CACHE_DIR")
                if os.name != "nt" and not configured_site.exists():
                    raise RuntimeError("DVC_SITE_CACHE_DIR does not exist")
                effective_site_cache = str(configured_site.resolve())
            elif site_source == "config" and configured_site is not None:
                _verify_private_directory(configured_site, label="DVC site_cache_dir")
                if configured_site.exists():
                    effective_site_cache = str(configured_site.resolve())
                else:
                    temp_site_cache = _new_private_temp_site_cache()
                    effective_site_cache = temp_site_cache.name
            else:
                temp_site_cache = _new_private_temp_site_cache()
                effective_site_cache = temp_site_cache.name
        options: dict[str, Any] = {"timeout": 120} if reading else {}
        env = os.environ.copy()
        if targets:
            env["ASTACK_DVC_TARGETS"] = json.dumps(targets)
        if effective_site_cache is not None:
            env["DVC_SITE_CACHE_DIR"] = effective_site_cache
        options["env"] = env
        result = _run(command, cwd=root, **options)
    except subprocess.TimeoutExpired:
        return None, "DVC timed out reading the pipeline"
    except (OSError, RuntimeError, UnicodeError) as exc:
        return None, f"DVC could not run: {exc}"
    finally:
        if temp_site_cache is not None:
            temp_site_cache.cleanup()
    if result.returncode != 0:
        detail = (result.stderr or result.stdout).strip().splitlines()
        return None, "DVC could not report: " + (detail[-1][:200] if detail else "no output")
    try:
        value = json.loads(result.stdout.strip().splitlines()[-1])
    except (IndexError, json.JSONDecodeError):
        return None, "DVC did not return JSON"
    if (
        not isinstance(value, dict)
        or (not stages_only and not isinstance(value.get("status"), dict))
        or not isinstance(value.get("stages"), list)
    ):
        return None, "DVC returned an unexpected shape"
    return value, ""


def _overlaps(left: str, right: str) -> bool:
    return left == right or left.startswith(right + "/") or right.startswith(left + "/")


def _derived_location(relative: str) -> bool:
    """Paths a pipeline writes, so a stage may read them only as another stage's output."""
    return _classify_output_path(relative)["lifecycle"] in DERIVED_LIFECYCLES


def _real_relative(root: Path, relative: str) -> str | None:
    """A project path's real location relative to the real project root, or None outside it."""
    try:
        return (root / relative).resolve().relative_to(root.resolve()).as_posix()
    except (OSError, ValueError, RuntimeError):
        return None


def _tracked_files(root: Path, stages: list[dict[str, Any]]) -> set[str]:
    """Real paths of every file DVC tracks as a stage output, ignored files excluded."""
    tracked: set[str] = set()
    for stage in stages:
        for out in stage["outs"]:
            if not isinstance(out, dict):
                continue
            members = (
                [str(item) for item in out.get("files", [])]
                if out.get("dir")
                else [str(out.get("path"))]
            )
            for member in members:
                real = _real_relative(root, member)
                if real is not None:
                    tracked.add(real)
    return tracked


def _uncovered_file(root: Path, dep: str, tracked: set[str]) -> str | None:
    """The first file under a derived dep that DVC does not track as an output, or None.

    Files are compared by real path, so a symlink to a declared output is covered, while a file
    `.dvcignore` hides inside a declared folder, or any undeclared file, is not.
    """
    real = _real_relative(root, dep)
    if real is None:
        return dep
    if real in tracked:
        return None
    folder = root.resolve() / real
    if not folder.is_dir():
        return dep
    for current, directories, files in os.walk(folder, followlinks=False):
        for name in sorted(directories):
            if Path(current, name).is_symlink():
                return Path(current, name).relative_to(root.resolve()).as_posix()
        for name in sorted(files):
            member = Path(current, name).relative_to(root.resolve()).as_posix()
            if _real_relative(root, member) not in tracked:
                return member
    return None


def _stage_edges(
    root: Path, stages: list[dict[str, Any]]
) -> tuple[dict[str, set[str]], dict[str, str]]:
    """Each stage's upstream stages, and the undeclared derived input of any stage that has one.

    A dep links to a stage when it overlaps one of that stage's outputs, by path, real path, or
    where a tracked symlink inside it points. Separately, a dep in a derived location must be
    fully covered by declared outputs: anything else means the pipeline wrote data DVC does not
    track, so nothing can vouch for it.
    """
    produced: list[tuple[str, str]] = []
    for stage in stages:
        for out in stage["outs"]:
            if not isinstance(out, dict):
                continue
            names = {str(out.get("path")), str(out.get("real") or out.get("path"))}
            aliases = out.get("aliases")
            names |= {str(item) for item in aliases} if isinstance(aliases, dict) else set()
            produced.extend((name, str(stage["name"])) for name in names)
    tracked = _tracked_files(root, stages)
    upstream: dict[str, set[str]] = {}
    orphans: dict[str, str] = {}
    for stage in stages:
        name = str(stage["name"])
        upstream[name] = set()
        for dep in stage.get("deps", []):
            if not isinstance(dep, dict):
                continue
            paths = {str(dep.get("path")), str(dep.get("real") or dep.get("path"))}
            upstream[name] |= {
                producer
                for path in paths
                for output, producer in produced
                if _overlaps(path, output)
            } - {name}
            lexical = str(dep.get("path"))
            if any(_safe_pipeline_path(path) and _derived_location(path) for path in paths):
                uncovered = _uncovered_file(root, lexical, tracked)
                if uncovered is not None:
                    orphans.setdefault(name, uncovered)
    return upstream, orphans


def _stage_states(
    root: Path,
    stages: list[dict[str, Any]],
    status: dict[str, Any],
    untrusted: dict[str, str] | None = None,
) -> dict[str, tuple[str, str]]:
    """Each stage's own state, then carried down the pipeline.

    `dvc status` checks only a stage's direct deps, so a stage downstream of a stale one looks
    unchanged until the upstream stage reruns. Unknown wins over outdated, so a frozen,
    unreadable or untraceable stage never lets anything below it count as current.
    """
    upstream, orphans = _stage_edges(root, stages)
    states: dict[str, tuple[str, str]] = {}
    for stage in stages:
        name = str(stage["name"])
        if stage.get("frozen"):
            states[name] = ("unknown", "its stage is frozen, so DVC does not check its inputs")
        elif untrusted and name in untrusted:
            states[name] = ("unknown", untrusted[name])
        elif name in orphans:
            states[name] = (
                "unknown",
                f"its stage reads {orphans[name]}, which no stage declares as an output",
            )
        elif name in status:
            states[name] = ("outdated", "")
        else:
            states[name] = ("current", "matches dvc.lock")
    changed = True
    while changed:
        changed = False
        for name, parents in upstream.items():
            if states[name][0] == "unknown":
                continue
            for parent in sorted(parents):
                label = states.get(parent, ("unknown", ""))[0]
                if label == "unknown" or (label != "current" and states[name][0] == "current"):
                    states[name] = (
                        "unknown" if label == "unknown" else "outdated",
                        f"upstream stage {parent} is {label}",
                    )
                    changed = True
                    break
    return states


# --- dependency_check responsibility ---


def _stage_order(stages: list[dict[str, Any]], upstream: dict[str, set[str]]) -> list[str]:
    """Stage names with every upstream stage first, ties broken by name."""
    names = sorted(str(stage["name"]) for stage in stages)
    remaining = {name: set(upstream.get(name, set())) & set(names) for name in names}
    order: list[str] = []
    while remaining:
        ready = sorted(name for name, parents in remaining.items() if not parents)
        if not ready:  # DVC refuses cycles, so this is only a safety net.
            ready = sorted(remaining)
        for name in ready:
            order.append(name)
            del remaining[name]
        for parents in remaining.values():
            parents.difference_update(ready)
    return order


def _tooling(relative: str) -> bool:
    """Top-level tooling folders and bytecode caches, which no stage reads or writes as data."""
    parts = relative.split("/")
    return parts[0] in SNAPSHOT_SKIPPED or BYTECODE_CACHE in parts


def _snapshot(root: Path, gaps: list[str] | None = None) -> dict[str, tuple[int, ...]]:
    """Every file and symlink in the project with its inode, size, mtime, ctime and mode.

    A program can restore a file's mtime but not its ctime, so any rewrite of a file that
    persists is seen. A file created and deleted within one stage cannot reach a later stage.
    """
    files: dict[str, tuple[int, ...]] = {}
    # Writes into a folder that cannot be inspected may still be possible (an ACL can deny reading
    # its metadata but allow writing), so each such folder is recorded in gaps, never skipped
    # silently, and is still walked where that works.
    raw_path = root / "data" / "raw"
    try:
        raw: Path | None = raw_path.resolve()
    except OSError:
        raw = None

    def unlisted(error: OSError) -> None:
        if gaps is None:
            return
        try:
            relative = Path(error.filename or root).relative_to(root).as_posix()
        except ValueError:
            relative = str(error.filename)
        if not _tooling(relative) and relative != "data/raw":
            gaps.append(f"{relative} (writes there could not be checked)")

    for current, directories, names in os.walk(root, onerror=unlisted, followlinks=False):
        here = Path(current)
        base = here.relative_to(root).as_posix()
        kept = []
        for name in sorted(directories):
            path = here / name
            relative = name if base == "." else f"{base}/{name}"
            try:
                if path.is_symlink():
                    names.append(name)
                    continue
                skip_raw = path == raw_path or (raw is not None and path.resolve() == raw)
            except OSError:
                if gaps is not None and not _tooling(relative):
                    gaps.append(f"{relative} (writes there could not be checked)")
                skip_raw = path == raw_path
            if not _tooling(relative) and not skip_raw:
                kept.append(name)
        directories[:] = kept
        for name in names:
            path = here / name
            relative = path.relative_to(root).as_posix()
            if _tooling(relative):
                continue
            try:
                metadata = path.lstat()
            except OSError:
                if gaps is not None:
                    gaps.append(f"{relative} (writes there could not be checked)")
                continue
            if gaps is not None and relative != "data/raw" and stat.S_ISLNK(metadata.st_mode):
                # The snapshot sees the link, not what it points at. A target inside the project
                # is snapshotted where it lives. One outside it, or unresolvable, is a gap.
                try:
                    outside = not path.resolve(strict=True).is_relative_to(root.resolve())
                except (OSError, RuntimeError):
                    outside = True
                if outside:
                    gaps.append(
                        f"{relative} (symlink out of the project; writes through it are not seen)"
                    )
            files[relative] = (
                metadata.st_ino,
                metadata.st_size,
                metadata.st_mtime_ns,
                metadata.st_ctime_ns,
                metadata.st_mode,
            )
    return files


def _ignored_change(relative: str) -> bool:
    """Files DVC itself writes while running a stage."""
    name = relative.rsplit("/", 1)[-1]
    return name in {"dvc.lock", ".gitignore"}


def _python_program(word: str, cwd: Path) -> bool:
    """Whether a command word starts Python: a python binary, or a script with a python shebang."""
    if Path(word).name.startswith("python"):
        return True
    found = shutil.which(word, path=os.environ.get("PATH")) if "/" not in word else None
    path = Path(found) if found else cwd / word
    try:
        with path.open("rb") as handle:
            first = handle.readline(256)
    except OSError:
        return False
    return first.startswith(b"#!") and b"python" in first


def _traceable(command: object, cwd: Path | None = None) -> bool:
    """Whether a stage command is one Python process, so all of its reads reach the hook."""
    if not isinstance(command, str) or any(token in command for token in SHELL_SYNTAX):
        return False
    try:
        words = shlex.split(command)
    except ValueError:
        return False
    if words[:2] == ["uv", "run"]:
        words = words[2:]
        while words and words[0].startswith("-"):
            words = words[1:]
    if not words or "=" in words[0]:  # A leading VAR=value can drop PYTHONPATH.
        return False
    return _python_program(words[0], cwd or Path.cwd()) and not _disables_hook(words)


def _trace_environment(folder: Path, trace_file: Path) -> dict[str, str]:
    hook = folder / "hook"
    hook.mkdir(exist_ok=True)
    (hook / "sitecustomize.py").write_text(TRACE_SITECUSTOMIZE, encoding="utf-8")
    existing = os.environ.get("PYTHONPATH")
    return {
        "PYTHONPATH": str(hook) + (os.pathsep + existing if existing else ""),
        TRACE_FILE_ENV: str(trace_file),
    }


def _disables_hook(argv: list[str]) -> bool:
    """Interpreter options that stop the hook: -S skips site, -I and -E ignore PYTHONPATH.

    Short options are read one letter at a time, as CPython does, so clusters like -uS count.
    -X and -W take the rest of their word, or the next word when they end it. -c and -m end
    the options.
    """
    words = iter(argv[1:])
    for word in words:
        if word == "--" or not word.startswith("-") or word == "-":
            return False
        if word.startswith("--"):
            if word == "--check-hash-based-pycs":
                next(words, None)  # Its value is a separate word.
            continue
        for index, letter in enumerate(word[1:], start=1):
            if letter in {"c", "m"}:
                return False
            if letter in {"S", "I", "E"}:
                return True
            if letter in {"X", "W"}:
                if index == len(word) - 1:
                    next(words, None)  # A separate value, as in -X utf8 or -uX utf8.
                break  # Otherwise the rest of the word is the value, as in -Xutf8.
    return False


def _read_trace(trace_file: Path) -> tuple[set[str], list[str], int]:
    """Files read, launched programs whose reads are not seen, and the number of traced processes.

    Each launch is judged on its own: a non-Python program is untraced, and so is a Python one
    whose environment drops the hook or whose options (-S, -I, -E) stop it loading.
    """
    reads: set[str] = set()
    starts: set[int] = set()
    untraced: set[str] = set()
    if not trace_file.exists():
        return reads, [], 0
    for line in trace_file.read_text(encoding="utf-8", errors="replace").splitlines():
        try:
            event = json.loads(line)
        except json.JSONDecodeError:
            continue
        if not isinstance(event, dict):
            continue
        kind, value, pid = event.get("kind"), event.get("value"), event.get("pid")
        if kind == "start" and isinstance(pid, int):
            starts.add(pid)
        elif kind == "read" and isinstance(value, str):
            reads.add(value)
        elif kind == "spawn" and isinstance(value, dict):
            program = str(value.get("program"))
            argv = [str(item) for item in value.get("argv") or []]
            if not Path(program).name.startswith("python"):
                untraced.add(program)
            elif value.get("hooked") is not True or _disables_hook(argv):
                untraced.add("a Python child process that cannot load the hook")
    return reads, sorted(untraced), len(starts)


def _source_of(relative: str) -> str:
    """The source file a bytecode read stands for: pkg/__pycache__/m.cpython-312.pyc -> pkg/m.py."""
    parts = relative.split("/")
    if len(parts) >= 2 and parts[-2] == BYTECODE_CACHE and parts[-1].endswith(".pyc"):
        return "/".join([*parts[:-2], parts[-1].split(".", 1)[0] + ".py"])
    return relative


def _project_relative(root: Path, absolute: str) -> str | None:
    """A traced path relative to the project, or None outside it or inside tooling folders.

    A bytecode read stands for its source, so an import served from __pycache__ still counts.
    """
    for base in (root, root.resolve()):
        try:
            relative = _source_of(Path(absolute).relative_to(base).as_posix())
        except ValueError:
            continue
        if not _tooling(relative) and not _ignored_change(relative):
            return relative
    return None


def _paths(entries: object) -> set[str]:
    names: set[str] = set()
    for entry in entries if isinstance(entries, list) else []:
        if isinstance(entry, dict):
            names |= {str(entry.get("path")), str(entry.get("real") or entry.get("path"))}
    return names


def check_ignore_patterns(config: dict[str, Any]) -> list[str]:
    """Project-declared scratch files a toolchain leaves behind, such as R's .Rhistory.

    Patterns match project-relative paths with fnmatch, where `*` also crosses folders.
    """
    reproduction = config.get("reproduction", {})
    value = reproduction.get("check_ignore", []) if isinstance(reproduction, dict) else []
    if not isinstance(value, list) or not all(isinstance(item, str) and item for item in value):
        raise RuntimeError("reproduction.check_ignore must be a list of path patterns")
    return list(value)


def _ignored_by_project(relative: str, patterns: list[str]) -> bool:
    """Whether a project pattern covers a path. Raw inputs can never be ignored."""
    if relative == "data/raw" or relative.startswith("data/raw/"):
        return False
    name = relative.rsplit("/", 1)[-1]
    return any(
        fnmatch.fnmatchcase(relative, pattern) or fnmatch.fnmatchcase(name, pattern)
        for pattern in patterns
    )


def _within_any(root: Path, relative: str, bases: set[str]) -> bool:
    real = _real_relative(root, relative)
    return any(
        path == base or path.startswith(base + "/")
        for path in {relative, real or relative}
        for base in bases
    )


def _journal_entries(root: Path) -> dict[str, dict[str, int]] | None:
    """The lock journal, validated in full, or None when there is none."""
    journal = root / INPUT_LOCK_JOURNAL
    try:
        recorded = json.loads(journal.read_text(encoding="utf-8"))
    except FileNotFoundError:
        return None
    except (OSError, json.JSONDecodeError) as exc:
        recorded = exc
    fields = ("mode", "locked_mode", "dev", "ino")
    if not isinstance(recorded, dict) or not all(
        isinstance(path, str)
        and isinstance(entry, dict)
        and all(isinstance(entry.get(field), int) for field in fields)
        for path, entry in recorded.items()
    ):
        raise RuntimeError(
            f"{INPUT_LOCK_JOURNAL} is malformed, so astack cannot tell which files it locked. "
            "It was kept. Restore read access by hand (for example `chmod u+r <file>` on files "
            "under the derived folders), then delete it."
        )
    return recorded


def _restore_locks(root: Path) -> list[str]:
    """Give locked files their recorded modes back, including after an interrupted run.

    Only a file that is still the locked one (same device, inode and locked mode) is touched,
    so a replacement, or a mode someone changed since, is left alone and returned.
    """
    recorded = _journal_entries(root)
    if recorded is None:
        return []
    skipped: list[str] = []
    failed: list[str] = []
    for relative, entry in sorted(recorded.items()):
        path = root / relative
        try:
            metadata = path.lstat()
        except FileNotFoundError:
            skipped.append(relative)  # Gone, so there is nothing to restore.
            continue
        except OSError:
            failed.append(relative)  # Still there but unreachable, so keep the journal.
            continue
        if (metadata.st_dev, metadata.st_ino) != (
            entry["dev"],
            entry["ino"],
        ) or metadata.st_mode & 0o7777 != entry["locked_mode"]:
            skipped.append(relative)
            continue
        try:
            os.chmod(path, entry["mode"], follow_symlinks=False)
        except (OSError, NotImplementedError):
            try:
                os.chmod(path, entry["mode"])
            except OSError:
                failed.append(relative)
    if failed:
        raise RuntimeError(
            "Could not restore read access on: "
            + ", ".join(failed)
            + f". {INPUT_LOCK_JOURNAL} was kept; the next run retries."
        )
    (root / INPUT_LOCK_JOURNAL).unlink()
    return skipped


def _lock_inputs(
    root: Path, stage: dict[str, Any], ignore: list[str]
) -> tuple[list[str], list[str]]:
    """Make derived files the stage does not declare unreadable.

    Returns the locked paths and the gaps: paths that could not be locked safely and verifiably.
    A symlink or a file with other hard links is never changed, because that would change a file
    elsewhere, possibly a shared cache. A file still readable after locking, as an ACL can allow,
    is a gap too. The journal is written before any change.
    """
    allowed = _paths(stage.get("deps")) | _paths(stage.get("outs"))
    candidates: dict[str, dict[str, int]] = {}
    gaps: list[str] = []
    for prefix in COMPONENT_LIFECYCLES:
        folder = root / prefix
        # A symlink anywhere on the way, such as data/ itself, would lead outside the project.
        parts = prefix.split("/")
        try:
            linked = next(
                (
                    "/".join(parts[: index + 1])
                    for index in range(len(parts))
                    if (root / "/".join(parts[: index + 1])).is_symlink()
                ),
                None,
            )
            present = folder.is_dir()
        except OSError:
            if not _within_any(root, prefix, allowed):
                gaps.append(f"{prefix} (could not be inspected)")
            continue
        if linked is not None:
            if not _within_any(root, prefix, allowed):
                gaps.append(
                    f"{prefix} (symlinked folder)"
                    if linked == prefix
                    else f"{prefix} (through symlinked folder {linked})"
                )
            continue
        if not present:
            continue

        def unlisted(error: OSError, prefix: str = prefix) -> None:
            # A folder that cannot be listed still lets a known path be read, so it is a gap.
            path = Path(error.filename or root / prefix)
            try:
                relative = path.relative_to(root).as_posix()
            except ValueError:
                relative = prefix
            if not _within_any(root, relative, allowed):
                gaps.append(f"{relative} (folder could not be listed)")

        for current, directories, files in os.walk(folder, onerror=unlisted, followlinks=False):
            for name in [*directories, *files]:
                path = Path(current, name)
                relative = path.relative_to(root).as_posix()
                if _within_any(root, relative, allowed) or _ignored_by_project(relative, ignore):
                    continue
                try:
                    metadata = path.lstat()
                except OSError:
                    # A folder that can be listed but not entered still hides this path.
                    gaps.append(f"{relative} (could not be inspected)")
                    continue
                if stat.S_ISLNK(metadata.st_mode):
                    gaps.append(f"{relative} (symlink)")
                    continue
                if name in directories:
                    continue
                if metadata.st_nlink > 1:
                    gaps.append(f"{relative} (hard link)")
                    continue
                mode = metadata.st_mode & 0o7777
                if not mode & 0o444:
                    if os.access(path, os.R_OK):
                        gaps.append(f"{relative} (still readable, for example through an ACL)")
                    continue
                candidates[relative] = {
                    "mode": mode,
                    "locked_mode": mode & ~0o444,
                    "dev": metadata.st_dev,
                    "ino": metadata.st_ino,
                }
    if not candidates:
        return [], sorted(gaps)
    journal = root / INPUT_LOCK_JOURNAL
    partial = journal.with_name(journal.name + ".tmp")
    try:
        journal.parent.mkdir(parents=True, exist_ok=True)
        partial.write_text(json.dumps(candidates, sort_keys=True), encoding="utf-8")
        os.replace(partial, journal)  # Atomic, so a crash never leaves half a journal.
    except OSError:
        try:
            partial.unlink(missing_ok=True)
        except OSError:
            pass  # Nothing was locked, and the next write replaces it.
        # Nothing is changed without a journal to undo it, so every candidate is a gap.
        return [], sorted(
            [*gaps, *(f"{relative} (lock journal could not be written)" for relative in candidates)]
        )
    locked: list[str] = []
    for relative, entry in sorted(candidates.items()):
        path = root / relative
        try:
            os.chmod(path, entry["locked_mode"])
        except OSError:
            gaps.append(f"{relative} (could not change permissions)")
            continue
        locked.append(relative)
        if os.access(path, os.R_OK):
            gaps.append(f"{relative} (still readable, for example through an ACL)")
    return locked, sorted(gaps)


def _locked_read_message(name: str, locked: list[str], output: str) -> str | None:
    """Name the undeclared derived files a failed stage tried to read, when its output shows it."""
    hits = [relative for relative in locked if relative in output]
    if not hits:
        return None
    return (
        f"Stage {name} tried to read {', '.join(hits)}, which it does not declare. "
        "Add it to the stage's deps in dvc.yaml."
    )


def _stage_check(
    root: Path,
    stage: dict[str, Any],
    changed: list[str],
    trace: tuple[set[str], list[str], int],
    ignore: list[str] | None = None,
) -> dict[str, Any]:
    outs = _paths(stage.get("outs"))
    deps = _paths(stage.get("deps"))
    ignore = ignore or []

    def within(relative: str, bases: set[str]) -> bool:
        return _within_any(root, relative, bases)

    writes = sorted(
        relative
        for relative in changed
        if not _ignored_change(relative)
        and not _tooling(relative)
        and not _ignored_by_project(relative, ignore)
        and not within(relative, outs)
    )
    reads_seen, untraced_programs, processes = trace
    reads = sorted(
        {
            relative
            for absolute in reads_seen
            if (relative := _project_relative(root, absolute)) is not None
            and not within(relative, deps | outs)
            and not _ignored_by_project(relative, ignore)
            and relative.rsplit("/", 1)[-1] != "dvc.yaml"
        }
    )
    untraced = None
    wdir = root / str(stage.get("wdir") or ".")
    if not _traceable(stage.get("cmd"), wdir):
        untraced = "its command is not a single Python process, so some reads are not seen"
    elif processes == 0:
        untraced = "the trace hook did not load in its Python process"
    elif untraced_programs:
        untraced = "it starts programs whose reads are not seen: " + ", ".join(untraced_programs)
    return {
        "undeclared_writes": writes,
        "undeclared_reads": reads,
        "untraced": untraced,
    }


def _lock_fingerprints(root: Path) -> dict[str, str]:
    """A digest of each stage's dvc.lock entry, so a check describes one exact run."""
    fingerprints: dict[str, str] = {}
    if yaml is None:
        return fingerprints
    for lock in sorted(root.rglob("dvc.lock")):
        if _tooling(lock.relative_to(root).as_posix()):
            continue
        try:
            with _open_regular_file(lock) as handle:
                data = yaml.safe_load(handle) or {}
        except (OSError, yaml.YAMLError):
            continue
        stages = data.get("stages") if isinstance(data, dict) else None
        folder = lock.parent.relative_to(root).as_posix()
        for name, entry in (stages or {}).items() if isinstance(stages, dict) else ():
            key = str(name) if folder == "." else f"{folder}/dvc.yaml:{name}"
            text = json.dumps(entry, sort_keys=True, default=str)
            fingerprints[key] = hashlib.sha256(text.encode()).hexdigest()
    return fingerprints


def _check_policy(root: Path) -> str:
    """What a saved check was judged under, so changing ignores or the checker invalidates it."""
    ignore = sorted(check_ignore_patterns(_project_config(root)))
    text = json.dumps({"version": DEPENDENCY_CHECK_VERSION, "ignore": ignore})
    return hashlib.sha256(text.encode()).hexdigest()


def _save_checks(root: Path, results: dict[str, dict[str, Any]]) -> None:
    path = root / DEPENDENCY_CHECK_PATH
    try:
        saved = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        saved = {}
    stages = saved.get("stages") if isinstance(saved, dict) else None
    stages = stages if isinstance(stages, dict) else {}
    fingerprints = _lock_fingerprints(root)
    policy = _check_policy(root)
    for name, result in results.items():
        stages[name] = {**result, "lock": fingerprints.get(name), "policy": policy}
    path.parent.mkdir(parents=True, exist_ok=True)
    payload = {"schema_version": 1, "limits": DEPENDENCY_CHECK_LIMITS, "stages": stages}
    path.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n", encoding="utf-8")


def dependency_checks(root: Path) -> dict[str, dict[str, Any]]:
    """Saved checks that still describe each stage's current dvc.lock entry."""
    try:
        with _open_regular_file(root / DEPENDENCY_CHECK_PATH) as handle:
            saved = json.loads(handle.read().decode("utf-8"))
    except (OSError, ValueError, RecursionError):
        return {}
    stages = saved.get("stages") if isinstance(saved, dict) else None
    if not isinstance(stages, dict):
        return {}
    fingerprints = _lock_fingerprints(root)
    try:
        policy = _check_policy(root)
    except RuntimeError:
        return {}
    return {
        str(name): result
        for name, result in stages.items()
        if isinstance(result, dict)
        and result.get("lock") is not None
        and result.get("lock") == fingerprints.get(str(name))
        and result.get("policy") == policy
    }


def run_checked_dvc_stages(
    root: Path, *, force: bool, targets: list[str], environment: dict[str, str]
) -> dict[str, Any]:
    """Run each stage that needs it, in pipeline order, and check its reads and writes.

    DVC still decides nothing here: astack forces each stage it runs, so every run is traced.
    """
    ignore = check_ignore_patterns(_project_config(root))
    _restore_locks(root)  # Repair anything an interrupted run left locked.
    pipeline, problem = _dvc_pipeline(root, targets)
    if pipeline is None:
        raise RuntimeError(problem)
    stages = [
        stage
        for stage in pipeline["stages"]
        if isinstance(stage, dict) and isinstance(stage.get("outs"), list)
    ]
    by_name = {str(stage["name"]): stage for stage in stages}
    upstream, _ = _stage_edges(root, stages)
    states = _stage_states(root, stages, pipeline["status"])
    order = _stage_order(stages, upstream)
    selected = pipeline.get("selected")
    chosen = set(order) if not targets else {str(name) for name in selected or []}
    if targets and not chosen:
        raise RuntimeError("The reproduction targets select no DVC stage: " + ", ".join(targets))
    checked = dependency_checks(root)
    results: dict[str, dict[str, Any]] = {}
    ran: set[str] = set()
    with tempfile.TemporaryDirectory(prefix="astack-trace-") as scratch:
        folder = Path(scratch)
        for name in order:
            stage = by_name[name]
            if name not in chosen or stage.get("frozen"):
                continue
            # A stage without a check for its current run reruns, so `just reproduce` repairs it.
            needed = (
                force
                or states[name][0] != "current"
                or bool(upstream[name] & ran)
                or name not in checked
            )
            if not needed:
                continue
            trace_file = folder / f"{len(ran)}.jsonl"
            locked: list[str] = []
            gaps: list[str] = []
            result = None
            try:
                locked, gaps = _lock_inputs(root, stage, ignore)
                before = _snapshot(root, gaps)
                result = _run(
                    ["uv", "run", "--locked", "dvc", "repro", "--single-item", "--force", name],
                    cwd=root,
                    env=os.environ | environment | _trace_environment(folder, trace_file),
                )
                after = _snapshot(root, gaps)
            finally:
                try:
                    _restore_locks(root)
                except RuntimeError as restore_error:
                    # Keep the stage's own failure next to the restore failure.
                    if result is not None and result.returncode != 0:
                        output = ((result.stderr or "") + (result.stdout or "")).strip()
                        raise RuntimeError(
                            f"{restore_error} Stage {name} also failed: {output[-2000:]}"
                        ) from restore_error
                    raise
            if result.returncode != 0:
                output = (result.stderr or "") + (result.stdout or "")
                raise RuntimeError(
                    _locked_read_message(name, locked, output)
                    or output.strip()
                    or f"Stage {name} failed"
                )
            changed = sorted(
                relative
                for relative in before.keys() | after.keys()
                if before.get(relative) != after.get(relative)
            )
            ran.add(name)
            results[name] = _stage_check(root, stage, changed, _read_trace(trace_file), ignore)
            if hasattr(os, "geteuid") and os.geteuid() == 0:
                gaps = ["every file (running as root ignores permissions)"]
            gaps = sorted(set(gaps))
            results[name]["inputs_locked"] = not gaps
            results[name]["lock_gaps"] = gaps
    _save_checks(root, results)
    return {"stages": results, "limits": DEPENDENCY_CHECK_LIMITS}


# --- reproduction responsibility ---


def _reproduction_config(config: dict[str, Any]) -> dict[str, Any]:
    value = config.get("reproduction", {})
    return value if isinstance(value, dict) else {}


def _reproduction_engine(root: Path, config: dict[str, Any]) -> str:
    reproduction = _reproduction_config(config)
    engine = reproduction.get("engine")
    if isinstance(engine, str) and engine:
        return engine
    tools = config.get("tools", [])
    if isinstance(tools, list) and "dvc" in tools and (root / "dvc.yaml").is_file():
        if "command" not in reproduction:
            return "dvc"
    return "command"


def _dvc_entry_path(entry: object) -> object:
    """A dvc.yaml output is a path, or a one-key map from the path to options like cache."""
    if not isinstance(entry, dict):
        return entry
    if "path" in entry:
        return entry["path"]
    return next(iter(entry)) if len(entry) == 1 else None


def _dvc_pipeline_outputs(root: Path) -> tuple[list[str], list[str]]:
    path = root / "dvc.yaml"
    if not path.exists():
        return [], ["dvc.yaml is missing"]
    if yaml is None:
        return [], ["PyYAML is unavailable"]
    try:
        value = yaml.safe_load(path.read_text(encoding="utf-8"))
    except (OSError, yaml.YAMLError) as exc:
        return [], [f"dvc.yaml is invalid: {exc}"]
    if not isinstance(value, dict) or not isinstance(value.get("stages"), dict):
        return [], ["dvc.yaml must contain a stages mapping"]
    stages = value["stages"]
    if not stages:
        return [], ["dvc.yaml must declare at least one stage"]
    outputs: list[str] = []
    errors: list[str] = []
    for stage_name, stage in stages.items():
        if not isinstance(stage_name, str) or not isinstance(stage, dict):
            errors.append("stage names and definitions must be mappings")
            continue
        for field in DVC_PIPELINE_FIELDS:
            entries = stage.get(field, [])
            if isinstance(entries, dict):
                entries = list(entries.values())
            if not isinstance(entries, list):
                errors.append(f"stage {stage_name!r} field {field!r} must be a list")
                continue
            for entry in entries:
                candidate = _dvc_entry_path(entry)
                relative = _safe_pipeline_path(candidate)
                if relative is None:
                    errors.append(f"stage {stage_name!r} has an unsafe {field} path")
                else:
                    outputs.append(relative)
    return sorted(set(outputs)), errors


def _dvc_command(root: Path, arguments: list[str]) -> subprocess.CompletedProcess[str]:
    _ensure_dvc_cache(root)
    return _run(["uv", "run", "--locked", "dvc", *arguments], cwd=root)


def _dvc_reproduction_targets(config: dict[str, Any]) -> list[str] | None:
    reproduction = _reproduction_config(config)
    targets = reproduction.get("targets", [])
    if not isinstance(targets, list) or not all(
        isinstance(target, str) and target and not target.startswith("-") for target in targets
    ):
        return None
    return targets


def _reproduction_command(root: Path, config: dict[str, Any]) -> list[str] | None:
    reproduction = _reproduction_config(config)
    if _reproduction_engine(root, config) == "dvc":
        targets = _dvc_reproduction_targets(config)
        if targets is None:
            return None
        return ["uv", "run", "--locked", "dvc", "repro", *targets]
    command = reproduction.get("command")
    if (
        not isinstance(command, list)
        or not command
        or not all(isinstance(part, str) and part for part in command)
    ):
        return None
    return command


def _acquisition_staged(config: dict[str, Any]) -> bool | None:
    """Acquisition is always staged. None means a removed in-place declaration remains.

    `staged = true` is accepted for projects written while staging was opt-in.
    """
    acquisition = config.get("acquisition", {})
    if not isinstance(acquisition, dict):
        return None
    return True if acquisition.get("staged", True) is True else None


def _acquisition_command(config: dict[str, Any]) -> list[str] | None:
    acquisition = config.get("acquisition", {})
    if not isinstance(acquisition, dict):
        return None
    command = acquisition.get("command")
    if (
        not isinstance(command, list)
        or not command
        or not all(isinstance(part, str) and part for part in command)
    ):
        return None
    return command


def _reproduction_state(root: Path) -> dict[str, Any]:
    commit = _run(["git", "rev-parse", "HEAD"], cwd=root)
    if commit.returncode != 0:
        raise RuntimeError("Reproduction requires a committed Git revision")
    sources_path = root / "data/sources.yml"
    lock_path = root / "uv.lock"
    version_path = root / ".astack/version"
    version = None
    if version_path.exists():
        with _open_regular_file(version_path) as handle:
            version = handle.read().decode("utf-8").strip().lstrip("v")
    state: dict[str, Any] = {
        "git_commit": commit.stdout.strip(),
        "sources_manifest_fingerprint": (
            _sha256(sources_path, regular_only=True) if sources_path.exists() else None
        ),
        "inputs": _raw_inputs_identity(root),
        "config_fingerprint": _sha256(root / ".astack/project.toml", regular_only=True),
        "lockfile_fingerprint": _sha256(lock_path, regular_only=True)
        if lock_path.exists()
        else None,
        "python_version": sys.version.split()[0],
        "workflow_version": version,
    }
    # Present only when in-place sources exist, so records from snapshot-only projects stay current.
    in_place = in_place_inputs_identity(root)
    if in_place:
        state["in_place_inputs"] = in_place
    return state


def _raw_inputs_identity(root: Path) -> dict[str, Any]:
    """Identify the raw bytes a run consumed, using cached per-file digests."""
    digest = hashlib.sha256()
    files = 0
    size = 0
    raw = root / "data/raw"
    for path in _raw_paths(raw):
        metadata = path.lstat()
        relative = path.relative_to(root).as_posix()
        if stat.S_ISLNK(metadata.st_mode) and path != raw:
            # A link's pathname is not byte identity: hash what it points to, or refuse.
            if not path.is_file():
                raise RuntimeError(
                    f"Raw input {relative} is a symlink to a directory or missing target; "
                    "link the whole data/raw root instead or copy the files"
                )
            target = os.readlink(path)
            digest.update(f"{relative}\0link:{target}\0{_cached_sha256(path)}\0".encode())
            files += 1
            size += path.stat().st_size
        elif stat.S_ISREG(metadata.st_mode):
            digest.update(f"{relative}\0{_cached_sha256(path)}\0".encode())
            files += 1
            size += metadata.st_size
    return {"files": files, "bytes": size, "sha256": digest.hexdigest()}


def _random_seed(config: dict[str, Any]) -> int | None:
    seed = _reproduction_config(config).get("random_seed")
    if seed is None:
        return None
    if isinstance(seed, bool) or not isinstance(seed, int):
        raise RuntimeError("reproduction.random_seed must be an integer")
    return int(seed)


def _probe_launcher(command: list[str] | None) -> list[str] | None:
    """Return how to start the Python interpreter the command itself runs, or None if unknown.

    Parsing is deliberately conservative: an interpreter flag other than `-m`, or a `uv run`
    option outside a small set that takes no value and does not change the environment, makes
    the environment unknown rather than guessed.
    """
    if command is None:
        return [sys.executable]

    def python_launcher(prefix: list[str], arguments: list[str]) -> list[str] | None:
        first = arguments[0] if arguments else ""
        if first.startswith("-") and first != "-m":
            return None
        return prefix

    program = Path(command[0]).name
    if re.fullmatch(r"python(3(\.\d+)?)?", program):
        return python_launcher([command[0]], command[1:])
    if program == "uv" and command[1:2] == ["run"]:
        for index in range(2, len(command)):
            if command[index] in UV_RUN_SAFE_FLAGS:
                continue
            if command[index].startswith("-"):
                return None
            target = Path(command[index]).name
            prefix = [*command[:index], "python"]
            if re.fullmatch(r"python(3(\.\d+)?)?", target):
                return python_launcher(prefix, command[index + 1 :])
            return prefix
    return None


def _environment_manifest(root: Path, command: list[str] | None = None) -> dict[str, Any]:
    """Capture the command's actual installed environment; never invent missing parts."""
    launcher = _probe_launcher(command)
    if launcher is None:
        return {
            "status": "unavailable",
            "reason": "the reproduction command does not start a recognized Python interpreter",
        }
    try:
        probe = subprocess.run(
            [*launcher, "-P", "-c", ENVIRONMENT_PROBE],
            cwd=root,
            check=False,
            capture_output=True,
            text=True,
            timeout=120,
        )
        value = json.loads(probe.stdout) if probe.returncode == 0 else None
    except (OSError, subprocess.TimeoutExpired, json.JSONDecodeError) as exc:
        return {"status": "unavailable", "reason": type(exc).__name__}
    if not isinstance(value, dict):
        return {"status": "unavailable", "reason": f"probe exited {probe.returncode}"}
    settings = {name: os.environ[name] for name in RUNTIME_SETTING_ENV if name in os.environ}
    return {"status": "captured", "launcher": launcher, **value, "settings": settings}


def _reproduction_path_fingerprint(root: Path, relative: str) -> str | None:
    path = root / relative
    try:
        if relative.rstrip("/") == "data/raw" and path.is_dir():
            digest = hashlib.sha256()
            for item in [path, *sorted(path.rglob("*"))]:
                metadata = item.lstat()
                digest.update(item.relative_to(root).as_posix().encode())
                digest.update(
                    f"\0{metadata.st_mode}\0{metadata.st_size}\0{metadata.st_mtime_ns}\0".encode()
                )
                if item.is_symlink():
                    digest.update(os.readlink(item).encode())
                elif item.is_file():
                    digest.update(_cached_sha256(item).encode())
                digest.update(b"\0")
            return f"raw-metadata:{digest.hexdigest()}"
        metadata = path.lstat()
        kind = "symlink" if path.is_symlink() else "directory" if path.is_dir() else "file"
        target = os.readlink(path) if path.is_symlink() else ""
        return f"{kind}:{metadata.st_mode}:{metadata.st_size}:{metadata.st_mtime_ns}:{target}"
    except OSError:
        return None


def _tooling_path(relative: str) -> bool:
    """The virtual environment and bytecode caches, which running Python rewrites as it imports.

    The environment manifest records the interpreter's packages separately.
    """
    parts = relative.rstrip("/").split("/")
    return parts[0] == ".venv" or "__pycache__" in parts


def _reproduction_git_state(root: Path) -> dict[str, tuple[str, str | None]]:
    result = _run(
        [
            "git",
            "status",
            "--porcelain=v1",
            "--untracked-files=all",
            "--ignored=matching",
            "-z",
        ],
        cwd=root,
    )
    if result.returncode != 0:
        raise RuntimeError(result.stderr.strip() or "Could not capture Git worktree state")
    fields = result.stdout.split("\0")
    state: dict[str, tuple[str, str | None]] = {}
    index = 0
    while index < len(fields):
        entry = fields[index]
        index += 1
        if not entry:
            continue
        if len(entry) < 4 or entry[2] != " ":
            raise RuntimeError("Could not parse Git worktree state")
        status = entry[:2]
        paths = [entry[3:]]
        if status[0] in {"R", "C"}:
            if index >= len(fields) or not fields[index]:
                raise RuntimeError("Could not parse Git rename state")
            paths.append(fields[index])
            index += 1
        for relative in paths:
            path = root / relative
            if _tooling_path(relative):
                continue
            if relative.rstrip("/") == "data/raw" and path.is_dir() and not path.is_symlink():
                expanded = [relative]
            elif path.is_dir() and not path.is_symlink():
                expanded = [child.relative_to(root).as_posix() for child in sorted(path.rglob("*"))]
            else:
                expanded = [relative]
            for expanded_relative in expanded:
                if _tooling_path(expanded_relative):
                    continue
                state[expanded_relative] = (
                    status,
                    _reproduction_path_fingerprint(root, expanded_relative),
                )
    return state


def _reproduction_output_allowed(root: Path, relative: str, config: dict[str, Any]) -> bool:
    try:
        _safe_managed_path(root, relative)
    except ValueError:
        return False
    if relative in DVC_CONTROL_PATHS or relative.startswith(".dvc/"):
        return _reproduction_engine(root, config) == "dvc"
    classification = _classify_output_path(relative)
    lifecycle = classification["lifecycle"]
    component_layout, declared = _output_policy(config)
    if (
        component_layout
        and lifecycle in {"figure", "table", "report"}
        and Path(relative).suffix.casefold() in MACHINE_OUTPUT_SUFFIXES
    ):
        return False
    if lifecycle == "legacy-evidence":
        return not component_layout
    if lifecycle == "scratch":
        return True
    if lifecycle == "routine":
        return True
    if lifecycle not in COMPONENT_LIFECYCLES.values():
        return False
    if not component_layout:
        return True
    component = classification["component"]
    return not classification["problem"] and component is not None and component in declared


def _record_matches_state(root: Path, record: object, config: dict[str, Any]) -> bool:
    """Return whether a run record describes the current committed inputs and configuration."""
    try:
        current = _reproduction_state(root)
    except RuntimeError:
        return False
    if not isinstance(record, dict) or record.get("schema_version") != RUN_RECORD_SCHEMA_VERSION:
        return False
    expected_command = _reproduction_command(root, config)
    if record.get("command") != expected_command:
        return False
    expected_engine = _reproduction_engine(root, config)
    if record.get("engine", expected_engine) != expected_engine:
        return False
    required = {
        "git_commit",
        "sources_manifest_fingerprint",
        "config_fingerprint",
        "lockfile_fingerprint",
        "python_version",
        "timestamp",
        "workflow_version",
    }
    if any(not record.get(field) for field in required):
        return False
    recorded_commit = str(record["git_commit"])
    if not re.fullmatch(r"[0-9a-f]{40,64}", recorded_commit):
        return False
    for field in ("sources_manifest_fingerprint", "config_fingerprint", "lockfile_fingerprint"):
        if not re.fullmatch(r"[0-9a-f]{64}", str(record[field])):
            return False
    inputs = record.get("inputs")
    if not isinstance(inputs, dict) or not re.fullmatch(r"[0-9a-f]{64}", str(inputs.get("sha256"))):
        return False
    for field, value in current.items():
        if field != "git_commit" and record.get(field) != value:
            return False
    if not isinstance(record.get("outputs"), dict) or not record["outputs"]:
        return False
    verification = record.get("verification")
    if not isinstance(verification, dict) or verification.get("status") not in (
        "verified",
        "unverified",
    ):
        return False
    if recorded_commit == current["git_commit"]:
        return True
    ancestor = _run(["git", "merge-base", "--is-ancestor", recorded_commit, "HEAD"], cwd=root)
    if ancestor.returncode != 0:
        return False
    changed = _run(["git", "diff", "--name-only", f"{recorded_commit}..HEAD"], cwd=root)
    if changed.returncode != 0:
        return False
    return all(
        (
            relative.startswith("reports/qa/runs/")
            or (relative.startswith("evidence/") and "/runs/" in relative)
        )
        for relative in changed.stdout.splitlines()
        if relative
    )


def _load_run_record(path: Path) -> dict[str, Any] | None:
    try:
        with _open_regular_file(path) as handle:
            record = json.loads(handle.read().decode("utf-8"))
    except (OSError, ValueError, RecursionError):
        return None
    return record if isinstance(record, dict) else None


def _outputs_match_record(root: Path, record: dict[str, Any]) -> bool:
    """Deleted or altered results must not keep being supported by an older record."""
    outputs = record.get("outputs")
    if not isinstance(outputs, dict):
        return False
    try:
        return all(
            isinstance(expected, dict) and _output_digest(root, relative) == expected
            for relative, expected in outputs.items()
        )
    except (OSError, RuntimeError, ValueError):
        return False


def _valid_run_record(root: Path, path: Path, config: dict[str, Any]) -> bool:
    record = _load_run_record(path)
    return (
        record is not None
        and _record_matches_state(root, record, config)
        and _outputs_match_record(root, record)
    )


def _verified_run_record(root: Path, path: Path, config: dict[str, Any]) -> bool:
    record = _load_run_record(path)
    if record is None or not _valid_run_record(root, path, config):
        return False
    verification = record["verification"]
    reference = verification.get("reference")
    if verification.get("status") != "verified" or not isinstance(reference, str):
        return False
    try:
        reference_path = _safe_managed_path(root, reference)
    except ValueError:
        return False
    if not reference_path.is_file() or _sha256(reference_path) != verification.get(
        "reference_sha256"
    ):
        return False
    # The reference must itself still be a valid promoted record for this state.
    reference_record = _load_run_record(reference_path)
    return reference_record is not None and _record_matches_state(root, reference_record, config)


def _reproduction_outputs(root: Path, config: dict[str, Any]) -> tuple[list[str], list[str]]:
    """Return declared reproduction outputs and configuration errors."""
    reproduction = _reproduction_config(config)
    declared = reproduction.get("outputs")
    if declared is None and _reproduction_engine(root, config) == "dvc":
        declared, errors = _dvc_pipeline_outputs(root)
        if errors:
            return [], errors
    if not isinstance(declared, list) or not declared:
        return [], [
            "material analysis must declare reproduction.outputs as a non-empty list of paths"
        ]
    outputs: list[str] = []
    errors = []
    for value in declared:
        relative = _safe_pipeline_path(value)
        if relative is None or not _reproduction_output_allowed(root, relative, config):
            errors.append(f"reproduction output is unsafe or not an allowed output path: {value}")
        elif _classify_output_path(relative)["lifecycle"] in {"raw", "routine", "scratch"}:
            errors.append(f"reproduction output must be a durable derived product: {value}")
        else:
            outputs.append(relative)
    tolerance = reproduction.get("tolerance", {})
    if not isinstance(tolerance, dict):
        errors.append("reproduction.tolerance must map output paths to command arrays")
    else:
        for relative, command in tolerance.items():
            if relative not in outputs:
                errors.append(f"reproduction.tolerance names an undeclared output: {relative}")
            elif (
                not isinstance(command, list)
                or not command
                or not all(isinstance(part, str) and part for part in command)
            ):
                errors.append(f"reproduction.tolerance for {relative} must be a command array")
    return sorted(set(outputs)), errors


def _output_digest(root: Path, relative: str) -> dict[str, str] | None:
    path = _safe_managed_path(root, relative)
    if path.is_symlink():
        raise RuntimeError(f"Reproduction output must not be a symlink: {relative}")
    if path.is_file():
        return {"kind": "file", "sha256": _cached_sha256(path)}
    if path.is_dir():
        return {"kind": "tree-v2", "sha256": _output_tree_sha256(path)}
    return None


def _output_stamp(root: Path, relative: str) -> dict[str, tuple[int, int, int]] | None:
    """Return per-file stamps for a declared output, so every retained file is checked."""
    path = root / relative
    if not path.exists() and not path.is_symlink():
        return None
    items = sorted(path.rglob("*")) if path.is_dir() else [path]
    stamps = {}
    for item in items:
        metadata = item.lstat()
        if not stat.S_ISDIR(metadata.st_mode):
            stamps[item.relative_to(root).as_posix()] = (
                metadata.st_ino,
                metadata.st_size,
                metadata.st_mtime_ns,
            )
    return stamps


def _stale_output_files(
    before: dict[str, tuple[int, int, int]] | None,
    after: dict[str, tuple[int, int, int]] | None,
) -> list[str]:
    """A retained file whose inode, size, and mtime are all unchanged was not rewritten."""
    if not before or not after:
        return []
    return sorted(name for name, stamp in before.items() if after.get(name) == stamp)


def _output_tree_sha256(directory: Path) -> str:
    """Unambiguous tree digest: each entry frames its path with NUL and a fixed-length hash."""
    digest = hashlib.sha256(b"astack-output-tree-v2\0")
    for path in sorted(directory.rglob("*")):
        if path.is_symlink() or not (path.is_file() or path.is_dir()):
            raise RuntimeError(f"Reproduction output tree contains a non-regular file: {path}")
        if path.is_dir():
            continue
        relative = path.relative_to(directory).as_posix()
        digest.update(relative.encode() + b"\0" + _cached_sha256(path).encode() + b"\n")
    return digest.hexdigest()


def _reference_record(
    root: Path, config: dict[str, Any], component_layout: bool, component: object
) -> tuple[Path, dict[str, Any]] | None:
    """Return the most recent promoted record that describes the current state."""
    durable = _durable_record_root(root, component_layout, component)
    for path in sorted(durable.glob("*.json"), reverse=True):
        record = _load_run_record(path)
        if record is not None and _record_matches_state(root, record, config):
            return path, record
    return None


def _compare_outputs(
    root: Path,
    config: dict[str, Any],
    outputs: dict[str, dict[str, str]],
    reference: tuple[Path, dict[str, Any]] | None,
) -> dict[str, Any]:
    if reference is None:
        return {
            "status": "unverified",
            "reason": (
                "no promoted reference record matches the current state; run "
                "`reproduce --promote`, commit the record, then rerun to verify"
            ),
        }
    reference_path, reference_record = reference
    reference_outputs = reference_record.get("outputs", {})
    tolerance = _reproduction_config(config).get("tolerance", {})
    methods: dict[str, str] = {}
    mismatches: list[dict[str, Any]] = []
    before = _reproduction_git_state(root)
    for relative, digest in sorted(outputs.items()):
        expected = reference_outputs.get(relative) if isinstance(reference_outputs, dict) else None
        if expected == digest:
            methods[relative] = "digest"
            continue
        command = tolerance.get(relative) if isinstance(tolerance, dict) else None
        if isinstance(expected, dict) and isinstance(command, list):
            environment = os.environ | {
                "ASTACK_OUTPUT": relative,
                "ASTACK_REFERENCE_RECORD": str(reference_path),
                "ASTACK_REFERENCE_SHA256": str(expected.get("sha256", "")),
            }
            checked = subprocess.run(
                command, cwd=root, env=environment, check=False, capture_output=True, text=True
            )
            if checked.returncode == 0:
                methods[relative] = "project-tolerance"
                continue
            mismatches.append(
                {
                    "path": relative,
                    "expected": expected,
                    "actual": digest,
                    "tolerance_check": command,
                    "detail": (checked.stderr or checked.stdout).strip()[-500:],
                }
            )
            continue
        mismatches.append({"path": relative, "expected": expected, "actual": digest})
    if _reproduction_git_state(root) != before:
        raise RuntimeError("A reproduction tolerance check changed the worktree")
    return {
        "status": "mismatch" if mismatches else "verified",
        "reference": reference_path.relative_to(root).as_posix(),
        "reference_sha256": _sha256(reference_path),
        "methods": methods,
        "mismatches": mismatches,
    }


def _snapshot_path(
    root: Path,
    path: Path,
    *,
    backup_root: Path | None = None,
) -> PathSnapshot:
    metadata = path.lstat()
    relative = path.relative_to(root).as_posix()
    backup = None
    target = None
    target_is_directory = False
    target_mode = None
    if stat.S_ISLNK(metadata.st_mode):
        kind = "symlink"
        target = os.readlink(path)
        target_is_directory = path.is_dir()
        if path.exists():
            target_mode = path.stat().st_mode & 0o777
        digest = None
    elif stat.S_ISREG(metadata.st_mode):
        kind = "file"
        digest = _cached_sha256(path)
        if backup_root is not None:
            backup = backup_root / relative
            backup.parent.mkdir(parents=True, exist_ok=True)
            _clone_or_copy(path, backup)
    elif stat.S_ISDIR(metadata.st_mode):
        kind = "directory"
        digest = None
    else:
        kind = "other"
        digest = None
    return PathSnapshot(
        digest=digest,
        mode=metadata.st_mode & 0o777,
        kind=kind,
        target=target,
        target_is_directory=target_is_directory,
        target_mode=target_mode,
        backup=backup,
    )


def _raw_paths(raw: Path) -> list[Path]:
    paths = [raw] if raw.exists() or raw.is_symlink() else []
    if raw.is_dir():
        for current, directories, files in os.walk(raw, followlinks=False):
            directories.sort()
            files.sort()
            paths.extend(Path(current) / name for name in [*directories, *files])
    return paths


def _raw_snapshot(root: Path) -> dict[str, PathSnapshot]:
    """Metadata and digests of every raw path. Staged acquisition never copies raw data."""
    return {
        path.relative_to(root).as_posix(): _snapshot_path(root, path)
        for path in _raw_paths(root / "data/raw")
    }


def _snapshot_paths(
    root: Path, relatives: set[str], *, backup_root: Path
) -> dict[str, PathSnapshot]:
    snapshots: dict[str, PathSnapshot] = {}
    for relative in sorted(relatives):
        path = root / relative
        if path.exists() or path.is_symlink():
            snapshots[relative] = _snapshot_path(root, path, backup_root=backup_root)
    return snapshots


def _tracked_paths(root: Path) -> set[str]:
    result = _run(["git", "ls-files", "-z"], cwd=root)
    if result.returncode != 0:
        raise RuntimeError(result.stderr.strip() or "Could not list tracked worktree paths")
    return {relative for relative in result.stdout.split("\0") if relative}


def _same_snapshot(left: PathSnapshot | None, right: PathSnapshot | None) -> bool:
    if left is None or right is None:
        return left is right
    return (
        left.digest,
        left.mode,
        left.kind,
        left.target,
        left.target_is_directory,
        left.target_mode,
    ) == (
        right.digest,
        right.mode,
        right.kind,
        right.target,
        right.target_is_directory,
        right.target_mode,
    )


def _restore_snapshot_path(root: Path, relative: str, state: PathSnapshot) -> None:
    """Restore one snapshot without deleting anything: an existing path raises FileExistsError."""
    path = root / relative
    path.parent.mkdir(parents=True, exist_ok=True)
    if state.kind == "file":
        if state.backup is None:
            raise RuntimeError("File snapshot backup is unavailable")
        _clone_or_copy(state.backup, path)
        path.chmod(state.mode)
    elif state.kind == "directory":
        if path.is_symlink() or path.exists():
            raise FileExistsError(errno.EEXIST, "Path exists", str(path))
        path.mkdir(parents=True, exist_ok=True)
        path.chmod(state.mode)
    elif state.kind == "symlink":
        if state.target is None:
            raise RuntimeError("Symlink snapshot target is unavailable")
        path.symlink_to(state.target, target_is_directory=state.target_is_directory)
    else:
        raise RuntimeError(f"Cannot restore unsupported path type: {relative}")


def _restore_worktree_changes(
    root: Path,
    changed: set[str],
    snapshots: dict[str, PathSnapshot],
    protected: set[tuple[int, int]],
    kept: list[str] | None = None,
    errors: list[str] | None = None,
) -> None:
    """Undo worktree changes, never removing an original raw inode.

    Kept paths and cleanup errors are appended to `kept` and `errors` as they happen.
    """
    kept = [] if kept is None else kept
    errors = [] if errors is None else errors
    for relative in sorted(changed, key=lambda value: len(Path(value).parts), reverse=True):
        state = snapshots.get(relative)
        path = root / relative
        # Every deletion goes through the inode check. Restores only create, never replace,
        # so a path that reappears after the check is left in place and reported.
        if path.is_symlink() or path.exists():
            held, failed = len(kept), len(errors)
            _remove_unprotected(path, protected, kept, errors)
            if len(kept) > held or len(errors) > failed:
                continue
        if state is not None:
            try:
                _restore_snapshot_path(root, relative, state)
            except FileExistsError:
                errors.append(f"{path}: reappeared during rollback and was left in place")
            except (OSError, RuntimeError) as exc:
                errors.append(f"{path}: {exc}")


def _raw_identities(root: Path) -> set[tuple[int, int]]:
    """Device and inode of every raw file and directory, from metadata only."""
    raw = root / "data/raw"
    identities: set[tuple[int, int]] = set()
    if not (raw.exists() or raw.is_symlink()):
        return identities

    def unreadable(error: OSError) -> None:
        raise RuntimeError(
            "Staged acquisition must read all of data/raw to protect it, but cannot list "
            f"{error.filename}. Make raw directories readable (chmod -R a+rX data/raw)."
        ) from error

    metadata = os.lstat(raw)
    identities.add((metadata.st_dev, metadata.st_ino))
    for current, directories, files in os.walk(raw, onerror=unreadable, followlinks=False):
        for name in [*directories, *files]:
            metadata = os.lstat(Path(current) / name)
            identities.add((metadata.st_dev, metadata.st_ino))
    if raw.is_symlink() and raw.is_dir():
        metadata = os.stat(raw)
        identities.add((metadata.st_dev, metadata.st_ino))
    return identities


def _remove_unprotected(
    path: Path, protected: set[tuple[int, int]], kept: list[str], errors: list[str]
) -> None:
    """Delete a tree, keeping every entry that is the last name of an original raw inode.

    Never raises for a filesystem error. Kept paths and errors are appended as they happen, so a
    later failure cannot hide where an original was kept. A directory holding a kept or
    undeletable entry is kept too. Nothing is followed through a symlink.
    """

    def visit(current: Path) -> bool:
        try:
            metadata = os.lstat(current)
        except FileNotFoundError:
            return True
        except OSError as exc:
            errors.append(f"{current}: {exc}")
            return False
        if (metadata.st_dev, metadata.st_ino) in protected and (
            stat.S_ISDIR(metadata.st_mode) or metadata.st_nlink <= 1
        ):
            kept.append(str(current))
            return False
        try:
            if stat.S_ISDIR(metadata.st_mode):
                try:
                    current.chmod(stat.S_IMODE(metadata.st_mode) | 0o700)
                except OSError:
                    pass
                removable = True
                for child in sorted(current.iterdir()):
                    removable = visit(child) and removable
                if not removable:
                    return False
                current.rmdir()
            else:
                # A protected name with another link may go: the bytes survive elsewhere, and each
                # name is checked again, so the last one is kept.
                current.unlink()
        except FileNotFoundError:
            return True
        except OSError as exc:
            errors.append(f"{current}: {exc}")
            return False
        return True

    visit(path)


def _acquisition_change_allowed(relative: str) -> bool:
    return (
        relative == "data/raw"
        or relative.startswith("data/raw/")
        or relative == "data/sources.yml"
        or relative.startswith("data/source-verification/")
        or relative == ".gitignore"
        or relative.startswith(".dvc/")
        or relative.endswith(".dvc")
        or relative.startswith(".cache/")
    )


def _is_raw_path(relative: str) -> bool:
    return relative == "data/raw" or relative.startswith("data/raw/")


def run_acquisition(root: Path) -> dict[str, Any]:
    _load_digest_cache(root)
    # Staged mode fills this in: raw inodes the cache must not replace, and whether raw
    # is still unverified.
    cache_guard: dict[str, Any] = {}
    try:
        return _run_acquisition(root, cache_guard)
    finally:
        if not cache_guard.get("unverified"):
            _save_digest_cache(root, cache_guard.get("protected"))


def _acquisition_scratch_candidates(root: Path) -> list[Path]:
    """Where scratch may go, best first. Same device as data/raw first, so promotion links.

    Candidates are the state directory beside the Git metadata and a hidden directory beside raw's
    real location. A candidate that resolves inside the tracked worktree is never used, because
    scratch there would count as a prohibited worktree change. Git metadata is allowed.
    """
    raw = root / "data/raw"
    worktree = root.resolve()
    named: list[Path] = []
    try:
        named.append(Path(state_path(Path(canonical_checkout(root)), "acquisition")))
    except (OSError, RuntimeError, ValueError):
        pass
    try:
        raw_device: int | None = os.stat(raw).st_dev
        named.append(Path(os.path.realpath(raw)).parent / ".astack-acquisition")
    except OSError:
        raw_device = None
    same: list[Path] = []
    other: list[Path] = []
    for candidate in named:
        if candidate.is_symlink():
            continue
        try:
            candidate.mkdir(parents=True, exist_ok=True)
            resolved = candidate.resolve(strict=True)
            device = os.stat(resolved).st_dev
        except OSError:
            continue
        if resolved.is_relative_to(worktree):
            inside = resolved.relative_to(worktree).parts
            if not inside or inside[0] != ".git":
                continue
        (same if raw_device is None or device == raw_device else other).append(resolved)
    return [*same, *other, Path(tempfile.gettempdir())]


def _acquisition_work_directory(root: Path) -> Path:
    """The preferred scratch parent. Creation still falls through to later candidates."""
    return _acquisition_scratch_candidates(root)[0]


def _create_acquisition_scratch(root: Path) -> tempfile.TemporaryDirectory[str]:
    """Create a private scratch directory in the first candidate that accepts one."""
    failures: list[str] = []
    for candidate in _acquisition_scratch_candidates(root):
        try:
            return tempfile.TemporaryDirectory(
                prefix="astack-acquisition-", dir=candidate, delete=False
            )
        except OSError as exc:
            failures.append(f"{candidate}: {exc}")
    raise RuntimeError("Could not create acquisition scratch: " + "; ".join(failures))


def _acquisition_worktree_rollback(
    root: Path,
    before: dict[str, tuple[str, str | None]],
    before_worktree: dict[str, PathSnapshot],
    protected: set[tuple[int, int]],
    kept: list[str] | None = None,
    errors: list[str] | None = None,
) -> None:
    try:
        after = _reproduction_git_state(root)
    except RuntimeError:
        after = before
    changed = {
        relative
        for relative in before.keys() | after.keys()
        if before.get(relative) != after.get(relative) and not _is_raw_path(relative)
    }
    _restore_worktree_changes(root, changed, before_worktree, protected, kept, errors)


def _prohibited_acquisition_changes(
    root: Path, before: dict[str, tuple[str, str | None]]
) -> list[str]:
    after = _reproduction_git_state(root)
    return sorted(
        relative
        for relative in before.keys() | after.keys()
        if before.get(relative) != after.get(relative) and not _acquisition_change_allowed(relative)
    )


def _run_acquisition(root: Path, cache_guard: dict[str, Any] | None = None) -> dict[str, Any]:
    config = _project_config(root)
    command = _acquisition_command(config)
    if command is None:
        raise RuntimeError("Acquisition requires [acquisition].command as a non-empty string array")
    if _acquisition_staged(config) is None:
        raise RuntimeError(
            "In-place acquisition was removed. Remove [acquisition].staged and have the command "
            f"write new inputs to ${ACQUISITION_DIR_ENV} instead of data/raw. "
            "See docs/migrations/staged-acquisition.md."
        )
    status = _run(["git", "status", "--porcelain", "--untracked-files=normal"], cwd=root)
    if status.returncode != 0 or status.stdout.strip():
        raise RuntimeError("Acquisition requires a clean Git worktree")
    return _run_staged_acquisition(root, command, {} if cache_guard is None else cache_guard)


def _writable_raw_paths(snapshot: dict[str, PathSnapshot]) -> list[str]:
    writable = []
    for relative, state in sorted(snapshot.items()):
        mode = state.mode
        if relative == "data/raw" and state.kind == "symlink":
            if state.target_mode is None:
                continue
            mode = state.target_mode
        elif state.kind not in {"file", "directory"}:
            continue
        if mode & 0o222:
            writable.append(relative)
    return writable


class AcquisitionLaunchError(OSError):
    """The acquisition command could not be started, so it changed nothing."""


def _read_output(path: Path) -> str:
    try:
        return path.read_text(errors="replace")
    except OSError:
        return ""


def _raw_anchor(root: Path) -> tuple[object, ...]:
    """Identify where data/raw lives: the project, data and raw inodes and raw's real target.

    Equal snapshots alone are not enough. A command could move the tree and leave a link that
    shows the same names and bytes, so cleanup would delete the only copy.
    """
    identities: list[object] = []
    for path in (root, root / "data", root / "data/raw"):
        try:
            metadata = os.lstat(path)
        except FileNotFoundError:
            identities.append(None)
            continue
        identities.append((metadata.st_dev, metadata.st_ino, stat.S_IFMT(metadata.st_mode)))
    raw = root / "data/raw"
    try:
        target = os.stat(raw)
        identities.append((os.path.realpath(raw), target.st_dev, target.st_ino))
    except FileNotFoundError:
        identities.append(None)
    return tuple(identities)


def _run_in_own_session(
    command: list[str], *, cwd: Path, env: dict[str, str], scratch: Path
) -> subprocess.CompletedProcess[str]:
    """Run a command, then stop anything it left running before astack touches its output.

    Output goes to files, not pipes, so a surviving background process cannot hold the
    acquisition open. A process that starts its own session escapes this cleanup.
    """
    stdout_path = scratch / "stdout"
    stderr_path = scratch / "stderr"
    with stdout_path.open("w") as stdout, stderr_path.open("w") as stderr:
        try:
            process = subprocess.Popen(
                command,
                cwd=cwd,
                env=env,
                stdin=subprocess.DEVNULL,
                stdout=stdout,
                stderr=stderr,
                start_new_session=os.name == "posix",
            )
        except OSError as exc:
            raise AcquisitionLaunchError(str(exc)) from exc
        try:
            returncode = process.wait()
        finally:
            if os.name == "posix":
                try:
                    os.killpg(process.pid, signal.SIGKILL)
                except (ProcessLookupError, PermissionError):
                    pass
            if process.poll() is None:
                process.kill()
                process.wait()
    return subprocess.CompletedProcess(
        command,
        returncode,
        _read_output(stdout_path),
        _read_output(stderr_path),
    )


def _run_staged_acquisition(
    root: Path, command: list[str], cache_guard: dict[str, Any]
) -> dict[str, Any]:
    """The command writes only into an empty staging directory. astack adds its files to raw.

    No copy of existing raw data is made, so existing raw inputs must already be read-only.
    astack then never needs to restore or delete anything in data/raw except paths it created.
    """
    before_raw = _raw_snapshot(root)
    linked = sorted(
        relative
        for relative, state in before_raw.items()
        if relative != "data/raw" and state.kind == "symlink"
    )
    if linked:
        # A nested link can point at a writable file outside raw that no snapshot protects.
        raise RuntimeError(
            "Staged acquisition requires raw inputs to be regular files, not symlinks. "
            "Use in-place acquisition, or replace these links with read-only files: "
            + ", ".join(linked[:10])
        )
    writable = _writable_raw_paths(before_raw)
    if writable:
        raise RuntimeError(
            "Staged acquisition keeps no copy of data/raw, so existing raw inputs must be "
            "read-only first. Run `chmod -R a-w data/raw`. Writable: " + ", ".join(writable[:10])
        )
    # Cleanup never deletes these, so a raw input moved anywhere astack cleans is kept.
    protected = _raw_identities(root)
    cache_guard["protected"] = protected
    held: list[str] = []
    cleanup_errors: list[str] = []

    def rollback() -> None:
        try:
            _acquisition_worktree_rollback(
                root, before, before_worktree, protected, held, cleanup_errors
            )
        except (OSError, RuntimeError) as exc:
            cleanup_errors.append(f"worktree rollback: {exc}")

    holder = _create_acquisition_scratch(root)
    scratch = Path(holder.name)
    keep_scratch = False
    try:
        staging = scratch / "staged"
        staging.mkdir()
        before = _reproduction_git_state(root)
        worktree_paths = _tracked_paths(root) | {
            relative for relative in before if not _is_raw_path(relative)
        }
        before_worktree = _snapshot_paths(root, worktree_paths, backup_root=scratch / "worktree")
        environment = {**os.environ, ACQUISITION_DIR_ENV: str(staging)}
        anchor = _raw_anchor(root)
        # From here until raw is shown intact, an error must not delete scratch or replace the
        # digest cache, either of which could hold a relocated original.
        keep_scratch = True
        cache_guard["unverified"] = True
        try:
            command_result = _run_in_own_session(
                command, cwd=root, env=environment, scratch=scratch
            )
        except AcquisitionLaunchError:
            keep_scratch = False
            cache_guard["unverified"] = False
            rollback()
            raise
        after_raw = _raw_snapshot(root)
        changed = sorted(
            path
            for path in before_raw.keys() | after_raw.keys()
            if not _same_snapshot(before_raw.get(path), after_raw.get(path))
        )
        if _raw_anchor(root) != anchor:
            changed.insert(0, "the location of data/raw")
        if changed:
            # Raw no longer matches, so originals may have been moved anywhere, including into
            # scratch. Deleting anything could destroy the only copy, so nothing is removed.
            raise RuntimeError(
                "Staged acquisition must not write to data/raw, but the command changed: "
                + ", ".join(changed[:20])
                + f". astack deleted nothing and kept its scratch directory at {scratch}, which "
                "may hold relocated raw inputs. Restore data/raw before acquiring again."
            )
        keep_scratch = False
        cache_guard["unverified"] = False
        if command_result.returncode != 0:
            rollback()
            raise RuntimeError(command_result.stderr.strip() or "Acquisition command failed")
        prohibited = _prohibited_acquisition_changes(root, before)
        if prohibited:
            rollback()
            raise RuntimeError(
                "Acquisition command made prohibited worktree changes: " + ", ".join(prohibited)
            )
        try:
            added = _promote_staged_inputs(root, staging, protected)
        except (OSError, RuntimeError):
            rollback()
            raise
        result = {
            "status": "acquired",
            "mode": "staged",
            "command": command,
            "added_raw_inputs": sorted(added),
            "added_raw_sha256": {
                relative: _cached_sha256(root / relative)
                for relative in sorted(added)
                if (root / relative).is_file()
            },
        }
    except BaseException as exc:
        if not keep_scratch:
            _remove_unprotected(scratch, protected, held, cleanup_errors)
        if held:
            exc.add_note(
                "astack kept these paths because they are original raw inputs: "
                + ", ".join(held[:20])
            )
        if cleanup_errors:
            exc.add_note("Cleanup could not remove: " + "; ".join(cleanup_errors[:20]))
        raise
    _remove_unprotected(scratch, protected, held, cleanup_errors)
    if held:
        failure = RuntimeError(
            "The inputs were added: "
            + ", ".join(result["added_raw_inputs"])
            + ". But original raw inputs were found outside data/raw and kept in place: "
            + ", ".join(held[:20])
        )
        if cleanup_errors:
            failure.add_note("Cleanup could not remove: " + "; ".join(cleanup_errors[:20]))
        raise failure
    if cleanup_errors:
        result["cleanup_errors"] = cleanup_errors
    return result


def _staged_entries(staging: Path) -> list[Path]:
    entries: list[Path] = []
    for current, directories, files in os.walk(staging, followlinks=False):
        directories.sort()
        files.sort()
        for name in [*directories, *files]:
            path = Path(current) / name
            metadata = path.lstat()
            relative = path.relative_to(staging).as_posix()
            if not (stat.S_ISDIR(metadata.st_mode) or stat.S_ISREG(metadata.st_mode)):
                raise RuntimeError(
                    "Staged inputs must be regular files or directories: " + relative
                )
            if stat.S_ISREG(metadata.st_mode) and metadata.st_nlink != 1:
                # A hard link shares its inode, so promoting it would alias another file.
                raise RuntimeError("Staged inputs must not be hard links: " + relative)
            entries.append(path)
    return entries


def _promote_staged_inputs(
    root: Path, staging: Path, protected: set[tuple[int, int]] | None = None
) -> list[str]:
    """Add staged files to data/raw, read-only. Refuse any existing path before moving anything.

    Every created path is recorded by inode as soon as it exists. On failure, cleanup removes a
    path only while it is still that inode, so an original raw input is never deleted.
    """
    raw = root / "data/raw"
    entries = _staged_entries(staging)
    conflicts = []
    for path in entries:
        target = raw / path.relative_to(staging)
        if not (target.is_symlink() or target.exists()):
            continue
        if path.is_dir() and target.is_dir() and not target.is_symlink():
            continue
        conflicts.append(target.relative_to(root).as_posix())
    if conflicts:
        raise RuntimeError(
            "Staged acquisition would replace existing raw inputs: " + ", ".join(conflicts)
        )
    if not entries:
        return []
    created: list[tuple[Path, os.stat_result]] = []
    unlocked: list[tuple[Path, int]] = []
    failure: BaseException | None = None
    try:
        if not (raw.is_symlink() or raw.exists()):
            raw.mkdir(parents=True, mode=0o755)
            created.append((raw, os.lstat(raw)))
        parents = sorted(
            {
                (raw / path.relative_to(staging)).parent
                for path in entries
                if (raw / path.relative_to(staging)).parent.is_dir()
            }
        )
        for parent in parents:
            mode = parent.stat().st_mode & 0o7777
            parent.chmod(mode | 0o700)
            unlocked.append((parent, mode))
        for path in entries:
            target = raw / path.relative_to(staging)
            if path.is_dir():
                if not target.is_dir():
                    target.mkdir(mode=0o755)
                    created.append((target, os.lstat(target)))
                continue
            _place_staged_file(path, target, created)
            target.chmod(path.stat().st_mode & 0o777 & ~0o222)
    except BaseException as exc:
        failure = exc
    restore_errors: list[str] = []
    preserved: list[str] = []
    if failure is not None:
        for target, identity in reversed(created):
            try:
                if not _same_inode(target, identity):
                    if target.exists() or target.is_symlink():
                        preserved.append(target.relative_to(root).as_posix())
                    continue
                current = os.lstat(target)
                if (
                    protected is not None
                    and (current.st_dev, current.st_ino) in protected
                    and (stat.S_ISDIR(current.st_mode) or current.st_nlink <= 1)
                ):
                    # An original raw inode moved over a staged source: this is its last name.
                    preserved.append(target.relative_to(root).as_posix())
                    continue
                if stat.S_ISDIR(identity.st_mode):
                    target.rmdir()
                else:
                    _unlink_if_same(target, identity)
            except OSError:
                preserved.append(target.relative_to(root).as_posix())
    else:
        for target, identity in created:
            if stat.S_ISDIR(identity.st_mode) and _same_inode(target, identity):
                try:
                    target.chmod(0o555)
                except OSError as exc:
                    restore_errors.append(f"{target.relative_to(root).as_posix()}: {exc}")
    for parent, mode in reversed(unlocked):
        try:
            parent.chmod(mode)
        except OSError as exc:
            restore_errors.append(f"{parent.relative_to(root).as_posix()}: {exc}")
    notes = []
    if restore_errors:
        notes.append("Could not restore raw directory permissions: " + "; ".join(restore_errors))
    if preserved:
        notes.append(
            "Left in place because astack could not prove it created them: " + ", ".join(preserved)
        )
    if failure is not None:
        for note in notes:
            failure.add_note(note)
        raise failure
    added = [target.relative_to(root).as_posix() for target, _ in created]
    if notes:
        raise RuntimeError(" ".join([*notes, "The inputs were added: " + ", ".join(added)]))
    return added


def _place_staged_file(
    source: Path, target: Path, created: list[tuple[Path, os.stat_result]]
) -> None:
    """Hard-link or copy one staged file into a new path. Never replaces an existing file."""
    identity = source.lstat()
    try:
        os.link(source, target)
    except FileExistsError:
        raise
    except OSError:
        _copy_exclusive(source, target, lambda made: created.append((target, made)))
        return
    created.append((target, identity))


def run_dvc_status(root: Path) -> dict[str, Any]:
    result = _dvc_command(root, ["status"])
    if result.returncode != 0:
        raise RuntimeError(result.stderr.strip() or "DVC status failed")
    canonical = Path(canonical_checkout(root))
    return {
        "status": "ok",
        "cache": str(Path(dvc_cache_root(canonical))),
        "output": result.stdout,
    }


def _dvc_metadata_hashes(value: object) -> set[str]:
    hashes: set[str] = set()
    if isinstance(value, dict):
        for key, nested in value.items():
            if key in {"md5", "etag", "checksum", "hash"} and isinstance(nested, str):
                if DVC_HASH_PATTERN.fullmatch(nested):
                    hashes.add(nested)
            hashes.update(_dvc_metadata_hashes(nested))
    elif isinstance(value, list):
        for nested in value:
            hashes.update(_dvc_metadata_hashes(nested))
    return hashes


def _dvc_hashes_from_text(text: str) -> set[str]:
    if yaml is None:
        return set()
    try:
        return _dvc_metadata_hashes(yaml.safe_load(text))
    except yaml.YAMLError:
        return set()


def _dvc_hashes_from_paths(root: Path, paths: list[Path]) -> set[str]:
    hashes: set[str] = set()
    for path in paths:
        try:
            hashes.update(_dvc_hashes_from_text(path.read_text(encoding="utf-8")))
        except (OSError, UnicodeError):
            continue
    return hashes


def _dvc_worktree_metadata_paths(root: Path) -> list[Path]:
    paths = [root / "dvc.lock"]
    paths.extend(sorted(root.glob("**/*.dvc")))
    return [
        path
        for path in paths
        if path.is_file() and ".git" not in path.parts and ".dvc" not in path.parts[:-1]
    ]


def _dvc_git_metadata_hashes(root: Path) -> tuple[set[str], str | None]:
    commits = _run(["git", "rev-list", "--all"], cwd=root)
    if commits.returncode != 0:
        return set(), commits.stderr.strip() or "could not enumerate Git history"
    hashes: set[str] = set()
    for commit in commits.stdout.splitlines():
        paths = _run(["git", "ls-tree", "-r", "--name-only", commit], cwd=root)
        if paths.returncode != 0:
            return set(), paths.stderr.strip() or "could not enumerate Git tree"
        metadata = [
            path
            for path in paths.stdout.splitlines()
            if path == "dvc.lock" or path.endswith(".dvc")
        ]
        for path in metadata:
            value = _run(["git", "show", f"{commit}:{path}"], cwd=root)
            if value.returncode != 0:
                return set(), value.stderr.strip() or f"could not read {commit}:{path}"
            hashes.update(_dvc_hashes_from_text(value.stdout))
    return hashes, None


def _dvc_cache_object_path(cache: Path, digest: str) -> list[Path]:
    bases = [cache / "files" / "md5", cache / "md5", cache]
    return [
        candidate
        for base in bases
        for candidate in (
            base / digest,
            base / digest[:2] / digest[2:],
            base / f"{digest}.dir",
            base / digest[:2] / f"{digest[2:]}.dir",
        )
    ]


def _expand_dvc_directory_hashes(cache: Path, hashes: set[str]) -> set[str]:
    expanded = set(hashes)
    pending = list(hashes)
    while pending:
        digest = pending.pop()
        object_path = next(
            (path for path in _dvc_cache_object_path(cache, digest) if path.is_file()), None
        )
        if object_path is None:
            continue
        try:
            value = json.loads(object_path.read_text(encoding="utf-8"))
        except (OSError, UnicodeError, json.JSONDecodeError):
            continue
        for nested in _dvc_metadata_hashes(value):
            if nested not in expanded:
                expanded.add(nested)
                pending.append(nested)
    return expanded


def _dvc_cache_configuration(root: Path) -> tuple[Path, str | None]:
    canonical = Path(canonical_checkout(root))
    expected = Path(dvc_cache_root(canonical))
    configured: Path | None = None
    for path in (root / ".dvc/config", root / ".dvc/config.local"):
        if not path.is_file():
            continue
        try:
            value = _read_dvc_config_value(path, "cache", "dir")
        except (OSError, RuntimeError) as exc:
            return expected, str(exc)
        if value:
            candidate = Path(value).expanduser()
            configured = (
                candidate if candidate.is_absolute() else path.parent / candidate
            ).resolve()
    if configured is not None and configured != expected:
        return expected, f"DVC cache {configured} differs from the repository cache {expected}"
    return expected, None


def _dvc_cache_inventory(cache: Path) -> tuple[list[dict[str, Any]], list[str]]:
    objects: list[dict[str, Any]] = []
    unknown: list[str] = []
    if not cache.is_dir():
        return objects, unknown
    seen: set[Path] = set()
    for path in sorted(cache.rglob("*")):
        if not path.is_file() or path in seen:
            continue
        seen.add(path)
        relative = path.relative_to(cache).as_posix()
        if path.name == ".gitignore":
            continue
        candidates = [path.name.removesuffix(".dir")]
        if len(path.parts) >= 2:
            candidates.append("".join(path.parts[-2:]).removesuffix(".dir"))
        digest = next((value for value in candidates if DVC_HASH_PATTERN.fullmatch(value)), None)
        if digest is None:
            unknown.append(relative)
            continue
        objects.append({"path": relative, "digest": digest, "bytes": path.stat().st_size})
    return objects, unknown


def _dvc_active_worktree_hashes(root: Path) -> tuple[set[str], list[str]]:
    hashes: set[str] = set()
    active: list[str] = []
    for record in list_worktrees(root):
        path = Path(str(record["path"]))
        if not path.exists():
            continue
        active.append(str(path))
        hashes.update(_dvc_hashes_from_paths(path, _dvc_worktree_metadata_paths(path)))
    return hashes, active


def run_dvc_cache_status(root: Path) -> dict[str, Any]:
    config = _project_config(root)
    tools = config.get("tools", [])
    if "dvc" not in tools or not (root / ".dvc/config").is_file():
        return {
            "status": "not-configured",
            "cache": None,
            "reason": "DVC is not configured for this project",
        }
    cache, configuration_error = _dvc_cache_configuration(root)
    if configuration_error:
        return {"status": "blocked", "cache": str(cache), "reason": configuration_error}
    if not cache.is_dir():
        return {
            "status": "blocked",
            "cache": str(cache),
            "cache_exists": False,
            "reason": "DVC cache is unavailable",
        }
    try:
        objects, unknown = _dvc_cache_inventory(cache)
    except OSError as exc:
        return {
            "status": "blocked",
            "cache": str(cache),
            "cache_exists": True,
            "reason": f"DVC cache could not be inspected: {exc}",
        }
    current_hashes = _dvc_hashes_from_paths(root, _dvc_worktree_metadata_paths(root))
    history_hashes, history_error = _dvc_git_metadata_hashes(root)
    active_hashes, active_worktrees = _dvc_active_worktree_hashes(root)
    protected = _expand_dvc_directory_hashes(cache, current_hashes | history_hashes | active_hashes)
    candidates = [value for value in objects if value["digest"] not in protected]
    status = "blocked" if history_error or unknown else "ok"
    reason = history_error or (
        f"unrecognized cache entries: {', '.join(unknown)}" if unknown else None
    )
    return {
        "status": status,
        "cache": str(cache),
        "cache_exists": cache.is_dir(),
        "object_count": len(objects),
        "cache_bytes": sum(int(value["bytes"]) for value in objects),
        "protected_objects": len(
            {value["digest"] for value in objects if value["digest"] in protected}
        ),
        "reclaimable_objects": len(candidates),
        "reclaimable_bytes": sum(int(value["bytes"]) for value in candidates),
        "candidates": candidates,
        "unknown_entries": unknown,
        "active_worktrees": sorted(set(active_worktrees)),
        "reason": reason,
    }


def run_dvc_cache_gc(root: Path, *, apply: bool = False) -> dict[str, Any]:
    status = run_dvc_cache_status(root)
    if status["status"] == "not-configured":
        return status | {"operation": "gc", "applied": False}
    if status["status"] != "ok":
        return status | {"operation": "gc", "applied": False, "reason": status["reason"]}
    canonical = Path(canonical_checkout(root))
    current = root.resolve()
    other_worktrees = [
        path
        for path in status["active_worktrees"]
        if Path(path).resolve() not in {canonical.resolve(), current}
    ]
    if apply and other_worktrees:
        return status | {
            "operation": "gc",
            "applied": False,
            "reason": "refusing cache deletion while linked worktrees are active",
            "blocking_worktrees": other_worktrees,
        }
    if apply:
        dirty = _run(["git", "status", "--porcelain", "--untracked-files=normal"], cwd=root)
        if dirty.returncode != 0 or dirty.stdout.strip():
            return status | {
                "operation": "gc",
                "applied": False,
                "reason": "refusing cache deletion from a dirty project worktree",
            }
        removed: list[str] = []
        cache = Path(status["cache"])
        for value in status["candidates"]:
            path = cache / str(value["path"])
            if path.is_file():
                path.unlink()
                removed.append(str(value["path"]))
        return status | {"operation": "gc", "applied": True, "removed": removed}
    return status | {"operation": "gc", "applied": False, "dry_run": True}


def _validated_component(component: object) -> str:
    if not isinstance(component, str) or not COMPONENT_PATTERN.fullmatch(component):
        raise RuntimeError("Reproduction component must be a lowercase slug")
    return component


def _run_record_root(root: Path, component: object) -> Path:
    slug = _validated_component(component) if component is not None else "project"
    return _safe_managed_path(root, f".cache/runs/{slug}")


def _durable_record_root(root: Path, component_layout: bool, component: object) -> Path:
    if component_layout:
        slug = _validated_component(component)
        return _safe_managed_path(root, f"evidence/{slug}/runs")
    return _safe_managed_path(root, "reports/qa/runs")


def _record_filename(timestamp: str) -> str:
    return f"{timestamp.replace(':', '').replace('.', '-')}.json"


def _write_record(path: Path, record: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(record, indent=2, sort_keys=True) + "\n", encoding="utf-8")


def run_validation(root: Path, tier: str) -> dict[str, Any]:
    if project_profile(root) != "data-science" or tier == "check":
        return dict(run_project_validation(root, tier))
    if tier not in VALIDATION_TIERS:
        raise RuntimeError(f"Validation tier must be one of: {', '.join(VALIDATION_TIERS)}")
    config = _project_config(root)
    commands, errors = _validation_commands(config)
    if errors:
        raise RuntimeError("Invalid validation configuration: " + "; ".join(errors))
    configured = commands.get(tier)
    if configured is None:
        raise RuntimeError(f"Validation tier {tier!r} is not configured in .astack/project.toml")
    if tier == "release":
        status = _run(["git", "status", "--porcelain", "--untracked-files=normal"], cwd=root)
        if status.returncode != 0 or status.stdout.strip():
            raise RuntimeError("RELEASE validation requires a clean Git worktree")
    for command in configured:
        try:
            result = _run(command, cwd=root)
        except OSError as exc:
            raise RuntimeError(
                f"{tier.upper()} validation command is unavailable: {' '.join(command)}"
            ) from exc
        if result.returncode != 0:
            detail = result.stderr.strip() or result.stdout.strip() or "command failed"
            raise RuntimeError(f"{tier.upper()} validation failed: {' '.join(command)}: {detail}")
    return {"status": "passed", "tier": tier, "commands": configured}


def run_reproduction(root: Path, *, promote: bool = False, verify: bool = False) -> dict[str, Any]:
    _load_digest_cache(root)
    try:
        return _run_reproduction(root, promote=promote, verify=verify)
    finally:
        _save_digest_cache(root)


def _run_reproduction(root: Path, *, promote: bool, verify: bool) -> dict[str, Any]:
    """Run the pipeline, digest declared outputs, and compare with the promoted reference.

    `command-succeeded` means the command ran and produced its declared outputs. Only
    `verified` means a rerun matched a promoted reference record.
    """
    del verify  # Verification is attempted on every run; the CLI enforces --verify.
    config = _project_config(root)
    analysis = config.get("analysis", {})
    if not isinstance(analysis, dict) or analysis.get("stage") != "material":
        raise RuntimeError("Reproduction is available only after analysis.stage is set to material")
    reproduction = _reproduction_config(config)
    engine = _reproduction_engine(root, config)
    command = _reproduction_command(root, config)
    component_layout, declared_components = _output_policy(config)
    component = reproduction.get("component")
    if engine not in REPRODUCTION_ENGINES:
        raise RuntimeError("Reproduction engine must be `command` or `dvc`")
    if command is None:
        raise RuntimeError("Configured reproduction engine has no valid command")
    if component_layout and component not in declared_components:
        raise RuntimeError("Material analysis requires a declared reproduction.component")
    record_root = _run_record_root(root, component)
    durable_root = _durable_record_root(root, component_layout, component)
    if engine == "dvc":
        _, pipeline_errors = _dvc_pipeline_outputs(root)
        if pipeline_errors:
            raise RuntimeError("Invalid DVC pipeline: " + "; ".join(pipeline_errors))
        _ensure_dvc_cache(root)
    seed = _random_seed(config)
    declared_outputs, output_errors = _reproduction_outputs(root, config)
    if output_errors:
        raise RuntimeError(
            "Reproduction requires declared outputs; declare reproduction.outputs: "
            + "; ".join(output_errors)
        )
    status = _run(["git", "status", "--porcelain", "--untracked-files=normal"], cwd=root)
    if status.returncode != 0 or status.stdout.strip():
        raise RuntimeError("Reproduction requires a clean Git worktree")
    reference = _reference_record(root, config, component_layout, component)
    executed = list(command)
    if engine == "dvc" and reference is not None:
        # A verification run must recompute stages instead of reusing cached outputs.
        executed = [*command[:4], "repro", "--force", *command[5:]]
    # Probe first: starting the interpreter through `uv run` may sync the environment, which must
    # not be mistaken for a change made by the pipeline.
    environment = _environment_manifest(root, executed)
    before = _reproduction_git_state(root)
    state = _reproduction_state(root)
    stamps = {relative: _output_stamp(root, relative) for relative in declared_outputs}
    timestamp = datetime.now(UTC).isoformat(timespec="microseconds").replace("+00:00", "Z")
    run_environment = in_place_root_environment(root)
    if seed is not None:
        run_environment[RANDOM_SEED_ENV] = str(seed)
    dependency_check: dict[str, Any] | None = None
    if engine == "dvc":
        # Stage by stage, so each one's reads and writes can be checked against dvc.yaml.
        dependency_check = run_checked_dvc_stages(
            root,
            force=reference is not None,
            targets=_dvc_reproduction_targets(config) or [],
            environment=run_environment,
        )
    elif run_environment:
        command_result = _run(executed, cwd=root, env=os.environ | run_environment)
    else:
        command_result = _run(executed, cwd=root)
    if engine != "dvc" and command_result.returncode != 0:
        raise RuntimeError(command_result.stderr.strip() or "Reproduction command failed")
    after = _reproduction_git_state(root)
    changed = sorted(
        relative
        for relative in before.keys() | after.keys()
        if before.get(relative) != after.get(relative)
    )
    ignore = check_ignore_patterns(config)
    prohibited = [
        relative
        for relative in changed
        if not _reproduction_output_allowed(root, relative, config)
        and not _ignored_by_project(relative, ignore)
    ]
    if prohibited:
        raw_changes = [
            relative
            for relative in prohibited
            if relative == "data/raw" or relative.startswith("data/raw/")
        ]
        if raw_changes:
            raise RuntimeError("Reproduction command changed raw input: " + ", ".join(raw_changes))
        raise RuntimeError(
            "Reproduction command made prohibited worktree changes: " + ", ".join(prohibited)
        )
    if _reproduction_state(root) != state:
        raise RuntimeError("Reproduction command changed its recorded input or environment state")
    outputs: dict[str, dict[str, str]] = {}
    for relative in declared_outputs:
        digest = _output_digest(root, relative)
        if digest is None:
            raise RuntimeError(f"Reproduction did not produce declared output: {relative}")
        if engine == "command":
            stale = _stale_output_files(stamps[relative], _output_stamp(root, relative))
            if stale:
                raise RuntimeError(
                    f"Declared output was not written by this run: {', '.join(stale)}. "
                    "Make the pipeline regenerate it or remove the stale copy."
                )
        outputs[relative] = digest
    verification = _compare_outputs(root, config, outputs, reference)
    environment_fingerprint = hashlib.sha256(
        json.dumps(environment, sort_keys=True).encode()
    ).hexdigest()
    if reference is not None:
        # Informational: a verified rerun on a different environment is stronger evidence.
        reference_environment = reference[1].get("environment")
        both_captured = environment.get("status") == "captured" and (
            isinstance(reference_environment, dict)
            and reference_environment.get("status") == "captured"
        )
        verification["environment_matches_reference"] = (
            reference[1].get("environment_fingerprint") == environment_fingerprint
            if both_captured
            else "unknown"
        )
    record = {
        "schema_version": RUN_RECORD_SCHEMA_VERSION,
        "timestamp": timestamp,
        "command": command,
        "executed_command": executed,
        "engine": engine,
        "random_seed": seed,
        "rng": {
            "seed": seed,
            "delivered_as": f"environment:{RANDOM_SEED_ENV}" if seed is not None else None,
            "consumption": (
                "project-defined; astack delivers the seed but has not verified that the "
                "pipeline uses it. Repeatability is shown only by a verified rerun."
            ),
        },
        "environment": environment,
        "environment_fingerprint": environment_fingerprint,
        "outputs": outputs,
        "verification": verification,
        **state,
    }
    if dependency_check is not None:
        record["dependency_check"] = dependency_check
    filename = _record_filename(timestamp)
    output = record_root / filename
    _write_record(output, record)
    result_status = {
        "verified": "verified",
        "unverified": "command-succeeded",
        "mismatch": "mismatch",
    }[verification["status"]]
    result: dict[str, Any] = {
        "status": result_status,
        "record": str(output),
        "provenance": record,
    }
    if promote and result_status != "mismatch":
        durable = durable_root / filename
        _write_record(durable, record)
        result["promoted_record"] = str(durable)
    return result


# --- staleness responsibility ---


def _stage_reason(changes: object, output: str) -> tuple[str, str]:
    """Label and reason for one output of a stage that `dvc status` reports as changed."""
    reasons: list[str] = []
    for change in changes if isinstance(changes, list) else [changes]:
        if isinstance(change, str):
            reasons.append(change)
            continue
        if not isinstance(change, dict):
            continue
        for kind, detail in change.items():
            if kind == "changed outs" and isinstance(detail, dict) and output in detail:
                if detail[output] == "deleted":
                    return "missing", "deleted since its run"
                reasons.append(f"changed since its run ({detail[output]})")
            elif kind == "changed deps" and isinstance(detail, dict):
                reasons.append("inputs or code changed: " + ", ".join(sorted(detail)))
            elif kind != "changed outs":
                reasons.append(kind)
    return "outdated", "; ".join(reasons) or "its stage is not up to date"


def _untrusted_stages(root: Path) -> dict[str, str]:
    """Stages whose last checked run read or wrote files dvc.yaml does not declare."""
    reasons: dict[str, str] = {}
    for name, check in dependency_checks(root).items():
        writes, reads = check.get("undeclared_writes") or [], check.get("undeclared_reads") or []
        if writes:
            reasons[name] = f"its stage wrote undeclared files: {', '.join(writes[:3])}"
        elif reads:
            reasons[name] = f"its stage read undeclared files: {', '.join(reads[:3])}"
    return reasons


def _dvc_labels(root: Path) -> tuple[list[dict[str, Any]], str]:
    pipeline, problem = _dvc_pipeline(root)
    if pipeline is None:
        return [], problem
    status = pipeline["status"]
    stages = [
        stage
        for stage in pipeline["stages"]
        if isinstance(stage, dict) and isinstance(stage.get("outs"), list)
    ]
    # DVC status already lists a stage whose outputs were deleted, so that carries down too.
    checks = dependency_checks(root)
    states = _stage_states(root, stages, status, _untrusted_stages(root))
    labels: list[dict[str, Any]] = []
    for stage in stages:
        name = str(stage["name"])
        for out in stage["outs"]:
            relative = _safe_pipeline_path(out.get("path") if isinstance(out, dict) else None)
            if relative is None:
                continue  # Outside the project, so no report can cite it.
            entry: dict[str, Any] = {"path": relative, "stage": name}
            real = _safe_pipeline_path(out.get("real"))
            if real is not None and real != relative:
                entry["real"] = real
            if out.get("dir"):
                entry["files"] = [str(item) for item in out.get("files", [])]
                aliases = out.get("aliases")
                if isinstance(aliases, dict):
                    entry["aliases"] = {
                        str(real): str(lexical)
                        for real, lexical in aliases.items()
                        if _safe_pipeline_path(real) is not None
                    }
            check = checks.get(name)
            if check is None:
                entry["dependency_check"] = "not-run"
            elif check.get("untraced"):
                entry["dependency_check"] = "untraced"
            elif check.get("inputs_locked") is False:
                entry["dependency_check"] = "inputs-not-locked"
            else:
                entry["dependency_check"] = "passed"
            label, reason = states[name]
            if not (root / relative).exists():
                entry |= {"label": "missing", "reason": "not produced yet"}
            elif label == "outdated" and name in status and not reason:
                label, reason = _stage_reason(status[name], relative)
                entry |= {"label": label, "reason": reason}
            else:
                entry |= {"label": label, "reason": reason}
            labels.append(entry)
    return labels, ""


def _command_labels(root: Path, config: dict[str, Any]) -> list[dict[str, Any]]:
    outputs, errors = _reproduction_outputs(root, config)
    if errors or not outputs:
        return []
    component = config.get("reproduction", {}).get("component")
    component_layout, _ = _output_policy(config)
    try:
        folders = [
            _run_record_root(root, component),
            _durable_record_root(root, component_layout, component),
        ]
    except (RuntimeError, ValueError):
        folders = []
    records = [path for folder in folders for path in folder.glob("*.json")]
    current: set[str] = set()
    recorded: set[str] = set()
    for path in records:
        record = _load_run_record(path)
        covered = record.get("outputs") if isinstance(record, dict) else None
        if not isinstance(covered, dict):
            continue
        recorded.update(covered)
        if _valid_run_record(root, path, config):
            current.update(covered)
    labels: list[dict[str, Any]] = []
    for output in outputs:
        entry: dict[str, Any] = {"path": output, "stage": "reproduction"}
        if not (root / output).exists():
            entry |= {"label": "missing", "reason": "not produced yet"}
        elif output in current:
            entry |= {"label": "current", "reason": "matches a current run record"}
        elif output in recorded:
            entry |= {
                "label": "outdated",
                "reason": "inputs, code, configuration or the output changed since its run",
            }
        else:
            entry |= {"label": "outdated", "reason": "no run record"}
        labels.append(entry)
    return labels


def _covering(labels: list[dict[str, Any]], relative: str) -> dict[str, Any] | None:
    """The output that holds a file. A DVC directory output holds only the files it tracks.

    A citation resolves symlinks, so an output also matches through its real path.
    """
    for entry in labels:
        # A tracked symlink inside a directory output resolves to wherever it points.
        lexical = entry.get("aliases", {}).get(relative)
        if lexical is not None and lexical in entry.get("files", []):
            return entry
    for entry in labels:
        output = str(entry["path"])
        for base in dict.fromkeys([output, str(entry.get("real") or output)]):
            if relative == base:
                return entry
            if relative.startswith(base.rstrip("/") + "/"):
                files = entry.get("files")
                lexical = output.rstrip("/") + relative[len(base.rstrip("/")) :]
                if files is None or lexical in files:
                    return entry
    return None


def output_status(root: Path) -> dict[str, Any]:
    """Label every pipeline output current, outdated, missing or unknown, with a reason.

    DVC projects use `dvc status` against dvc.lock. Command projects use run records.
    Files under reports/figures, reports/tables and artifacts that no stage or run declares
    are outdated, because nothing records how they were made.
    """
    config = _project_config(root)
    engine = _reproduction_engine(root, config)
    problem = ""
    if engine == "dvc":
        labels, problem = _dvc_labels(root)
    else:
        labels = _command_labels(root, config)
    for prefix in LABELED_OUTPUT_ROOTS:
        folder = root / prefix
        if not folder.is_dir():
            continue
        for path in sorted(folder.rglob("*")):
            if not path.is_file() or path.name.startswith("."):
                continue
            relative = path.relative_to(root).as_posix()
            if _covering(labels, relative) is None:
                labels.append(
                    {
                        "path": relative,
                        "stage": None,
                        "label": "outdated",
                        "reason": "no run record",
                    }
                )
    counts = {
        label: sum(entry["label"] == label for entry in labels)
        for label in ("current", "outdated", "missing", "unknown")
    }
    return {
        "engine": engine,
        "status": "unknown" if problem else "available",
        "problem": problem or None,
        "counts": counts,
        "outputs": labels,
    }


def evidence_label(status: dict[str, Any], relative: str) -> dict[str, Any] | None:
    """The label of the output that holds a cited file, or None when no run produced it."""
    return _covering(list(status.get("outputs", [])), relative)


def run_record_citation(root: Path, relative: str) -> bool | None:
    """Whether a cited run record is a current one, or None when the path is not a run record.

    A run record is evidence about a run, not a pipeline output, so it may be cited only while
    it still describes the current state.
    """
    if not (relative.startswith("evidence/") and "/runs/" in relative):
        return None
    if not relative.endswith(".json"):
        return False
    try:
        return _valid_run_record(root, root / relative, _project_config(root))
    except (OSError, RuntimeError, ValueError):
        return False


# --- output_contract responsibility ---


def _audit_output_contract_summary(root: Path, scope: str | None = None) -> dict[str, Any]:
    """Scope only by an explicit analysis key. Without one, every declared output is audited."""
    return dict(output_contract_summary(root, scope))


def _check_output_contract(root: Path, findings: list[Finding], scope: str | None = None) -> None:
    """Report every blocker in the declared scientific output registry as a finding.

    An undeclared project has no blockers unless an analysis was named, which then fails.
    """
    summary = _audit_output_contract_summary(root, scope)
    for blocker in summary["blockers"]:
        findings.append(
            _finding(
                "P1",
                "scientific-output",
                "scientific-output-registry",
                str(blocker),
                summary.get("path") or ".astack/project.toml",
            )
        )


# --- publication responsibility ---


def _marker(commit: str, scope: str) -> str:
    return f"<!-- ds-repo-audit:v1 commit={commit} scope={scope} -->"


def _fingerprint(body: str) -> str:
    return hashlib.sha256(body.encode()).hexdigest()


def _sanitize_public(body: str) -> str:
    start = "<!-- public-summary:start -->"
    end = "<!-- public-summary:end -->"
    if body.count(start) != 1 or body.count(end) != 1:
        raise RuntimeError("Public audit requires exactly one explicit public-summary block")
    start_index = body.index(start)
    end_index = body.index(end)
    if start_index >= end_index:
        raise RuntimeError("Public audit summary markers are reversed")
    summary = body[start_index + len(start) : end_index].strip()
    if not summary:
        raise RuntimeError("Public audit summary is empty")
    if "<!-- sensitive-details:" in summary:
        raise RuntimeError("Public audit summary contains a sensitive-details marker")
    long_token = re.search(r"[A-Za-z0-9_+=.-]{32,}", summary)
    if (
        "/" in summary
        or "\\" in summary
        or "@" in summary
        or long_token
        or any(pattern.search(summary) for pattern in SECRET_PATTERNS)
    ):
        raise RuntimeError("Public audit summary contains a likely path, identifier, or credential")
    return summary + "\n\nSensitive remediation details remain in the ignored local audit report."


def _gh_json(root: Path, args: list[str]) -> Any:
    result = _run(["gh", *args], cwd=root)
    if result.returncode != 0:
        raise RuntimeError(result.stderr.strip() or "GitHub CLI command failed")
    return json.loads(result.stdout or "null")


def _write_body_file(body: str) -> str:
    handle = tempfile.NamedTemporaryFile(mode="w", encoding="utf-8", delete=False, suffix=".md")
    with handle:
        handle.write(body)
    return handle.name


def _validated_audit_report(root: Path, report: Path) -> Path:
    audit_path = root / "reports" / "audits"
    current = audit_path
    while current != root and current != current.parent:
        if current.is_symlink():
            raise RuntimeError("Audit report directory must not use symlinks")
        current = current.parent
    audit_directory = audit_path.resolve()
    candidate = report.resolve()
    if candidate.parent != audit_directory or not candidate.is_file():
        raise RuntimeError("Audit report must be a file directly under reports/audits")
    current = report
    while current != root and current != current.parent:
        if current.is_symlink():
            raise RuntimeError("Audit report path must not use symlinks")
        current = current.parent
    return candidate


def _verify_audit_identity(root: Path, commit: str) -> None:
    if not re.fullmatch(r"[0-9a-f]{40}", commit):
        raise RuntimeError("Audit commit must be a full lowercase Git SHA")
    top_level = subprocess.run(
        ["git", "rev-parse", "--show-toplevel"],
        cwd=root,
        check=False,
        capture_output=True,
        text=True,
    )
    head = subprocess.run(
        ["git", "rev-parse", "HEAD"],
        cwd=root,
        check=False,
        capture_output=True,
        text=True,
    )
    status = subprocess.run(
        ["git", "status", "--porcelain"],
        cwd=root,
        check=False,
        capture_output=True,
        text=True,
    )
    if top_level.returncode != 0 or Path(top_level.stdout.strip()).resolve() != root:
        raise RuntimeError("Audit publication root is not the current Git repository root")
    if head.returncode != 0 or head.stdout.strip() != commit:
        raise RuntimeError("Audit commit does not match repository HEAD")
    if status.returncode != 0 or status.stdout.strip():
        raise RuntimeError("Audit issue publication requires a clean worktree")


def _assert_remote_report_safe(root: Path, report: Path) -> None:
    relative = report.relative_to(root).as_posix()
    tracked = _run(["git", "ls-files", "--error-unmatch", "--", relative], cwd=root)
    if tracked.returncode == 0:
        raise RuntimeError("Audit report must be untracked before remote publication")
    if tracked.returncode != 1:
        raise RuntimeError(tracked.stderr.strip() or "Could not verify audit report tracking")
    ignored = _run(["git", "check-ignore", "--quiet", "--", relative], cwd=root)
    if ignored.returncode == 0:
        return
    if ignored.returncode == 1:
        raise RuntimeError("Audit report must be Git-ignored before remote publication")
    raise RuntimeError(ignored.stderr.strip() or "Could not verify audit report ignore status")


def publish_audit(
    root: Path,
    report: Path,
    *,
    commit: str,
    scope: str,
    publish: str,
    actionable_count: int,
    remove_on_success: bool,
) -> dict[str, Any]:
    root = root.resolve()
    if scope not in ALLOWED_SCOPES:
        raise RuntimeError(f"Unsupported audit scope: {scope}")
    report = _validated_audit_report(root, report)
    if publish in {"local", "none"}:
        return {"status": publish, "report": str(report), "url": None}
    try:
        _verify_audit_identity(root, commit)
        repository = _gh_json(
            root, ["repo", "view", "--json", "isPrivate,hasIssuesEnabled,nameWithOwner"]
        )
        if not repository["hasIssuesEnabled"]:
            raise RuntimeError("GitHub Issues are disabled")
        is_private = bool(repository["isPrivate"])
        _assert_remote_report_safe(root, report)
        body = report.read_text(encoding="utf-8")
        if any(pattern.search(body) for pattern in SECRET_PATTERNS):
            raise RuntimeError("Audit report contains a likely credential and cannot be published")
        if not is_private:
            body = _sanitize_public(body)
        marker = _marker(commit, scope)
        body = body.rstrip() + f"\n\n{marker}\n"
        fingerprint = _fingerprint(body)
        body += f"<!-- ds-repo-audit:fingerprint={fingerprint} -->\n"
        issue_pages = _gh_json(
            root,
            [
                "api",
                "--paginate",
                "--slurp",
                f"repos/{repository['nameWithOwner']}/issues?state=all&per_page=100",
            ],
        )
        issues = (
            [issue for page in issue_pages for issue in page]
            if issue_pages and isinstance(issue_pages[0], list)
            else issue_pages
        )
        issues = [issue for issue in issues if "pull_request" not in issue]
        matches = [issue for issue in issues if marker in str(issue.get("body", ""))]
        if len(matches) > 1:
            raise RuntimeError("Multiple audit issues match the same commit and scope")
        body_file = _write_body_file(body)
        try:
            if matches:
                issue = matches[0]
                if f"ds-repo-audit:fingerprint={fingerprint}" not in str(issue.get("body", "")):
                    result = _run(
                        ["gh", "issue", "edit", str(issue["number"]), "--body-file", body_file],
                        cwd=root,
                    )
                    if result.returncode != 0:
                        raise RuntimeError(result.stderr.strip() or "Could not update audit issue")
                number = str(issue["number"])
                url = str(issue.get("url") or issue.get("html_url"))
                state = str(issue["state"]).upper()
            else:
                title = f"[Audit] {scope} at {commit[:12]}"
                result = _run(
                    [
                        "gh",
                        "issue",
                        "create",
                        "--title",
                        title,
                        "--body-file",
                        body_file,
                    ],
                    cwd=root,
                )
                if result.returncode != 0:
                    raise RuntimeError(result.stderr.strip() or "Could not create audit issue")
                url = result.stdout.strip()
                number = url.rsplit("/", 1)[-1]
                state = "OPEN"
            if actionable_count > 0 and state == "CLOSED":
                result = _run(["gh", "issue", "reopen", number], cwd=root)
                if result.returncode != 0:
                    raise RuntimeError(result.stderr.strip() or "Could not reopen audit issue")
            if actionable_count == 0 and state == "OPEN":
                result = _run(["gh", "issue", "close", number, "--reason", "completed"], cwd=root)
                if result.returncode != 0:
                    raise RuntimeError(result.stderr.strip() or "Could not close clean audit issue")
        finally:
            Path(body_file).unlink(missing_ok=True)
        if remove_on_success and is_private:
            report.unlink(missing_ok=True)
        return {
            "status": "github",
            "report": None if not report.exists() else str(report),
            "url": url,
        }
    except (FileNotFoundError, KeyError, TypeError, json.JSONDecodeError, RuntimeError) as exc:
        if publish == "github":
            return {
                "status": "github-failed-local-retained",
                "report": str(report),
                "url": None,
                "error": str(exc),
            }
        return {"status": "local-fallback", "report": str(report), "url": None, "error": str(exc)}


def _export_matches(path: str, patterns: list[str]) -> bool:
    """A pattern is an exact tracked path or a directory prefix ending in `/**`."""
    for pattern in patterns:
        literal = pattern.removesuffix("/**")
        if any(character in literal for character in "*?["):
            raise RuntimeError(f"Unsupported export pattern {pattern!r}: use a path or 'dir/**'")
        if (pattern.endswith("/**") and path.startswith(literal + "/")) or path == pattern:
            return True
    return False


def _git_bytes(root: Path, args: list[str]) -> bytes:
    result = subprocess.run(["git", *args], cwd=root, check=False, capture_output=True)
    if result.returncode != 0:
        raise RuntimeError(result.stderr.decode(errors="replace").strip() or "Git read failed")
    return result.stdout


def _committed_text(root: Path, head: str, relative: str) -> str | None:
    """Read a file from the pinned commit, never from the worktree; None when absent."""
    result = subprocess.run(
        ["git", "show", f"{head}:{relative}"], cwd=root, check=False, capture_output=True
    )
    return result.stdout.decode("utf-8") if result.returncode == 0 else None


def _export_config(root: Path, head: str) -> tuple[list[str], list[str], list[list[str]]]:
    text = _committed_text(root, head, ".astack/project.toml")
    try:
        config = tomllib.loads(text) if text is not None else {}
    except (tomllib.TOMLDecodeError, UnicodeError) as exc:
        raise RuntimeError(f"Committed .astack/project.toml is invalid: {exc}") from exc
    declaration = config.get("public_export")
    if not isinstance(declaration, dict):
        raise RuntimeError("Public export requires a [public_export] include allowlist")
    include = declaration.get("include")
    exclude = declaration.get("exclude", [])
    scan = declaration.get("scan", [])
    if (
        not isinstance(include, list)
        or not include
        or not all(isinstance(item, str) and item for item in include)
    ):
        raise RuntimeError("public_export.include must be a non-empty list of paths")
    if not isinstance(exclude, list) or not all(isinstance(item, str) for item in exclude):
        raise RuntimeError("public_export.exclude must be a list of paths")
    if not isinstance(scan, list) or not all(
        isinstance(command, list)
        and command
        and all(isinstance(part, str) and part for part in command)
        for command in scan
    ):
        raise RuntimeError("public_export.scan must be a list of command arrays")
    return include, exclude, scan


def _pinned_commit_entries(root: Path) -> tuple[str, list[tuple[str, str, str]]]:
    """Pin HEAD and list (mode, blob, path) from that commit's tree, not from the worktree."""
    status = _run(["git", "status", "--porcelain", "--untracked-files=all"], cwd=root)
    if status.returncode != 0 or status.stdout.strip():
        raise RuntimeError("Public export requires a clean Git worktree with no untracked files")
    head = _run(["git", "rev-parse", "--verify", "HEAD^{commit}"], cwd=root)
    if head.returncode != 0:
        raise RuntimeError("Public export requires a committed HEAD")
    commit = head.stdout.strip()
    listing = _git_bytes(root, ["ls-tree", "-r", "-z", "--full-tree", commit]).decode("utf-8")
    entries = []
    for entry in filter(None, listing.split("\0")):
        meta, path = entry.split("\t", 1)
        mode, _kind, blob = meta.split(" ")
        entries.append((mode, blob, path))
    return commit, entries


def _source_allows_public(record: object) -> bool:
    """Structured known redistribution evidence that does not deny it, plus explicit permission.

    Free text cannot be read for intent reliably, so the explicit `public-export` entry in
    `allowed_outputs` is the grant, and doubtful redistribution wording always refuses.
    """
    if not isinstance(record, dict):
        return False
    redistribution = record.get("redistribution")
    if not isinstance(redistribution, dict) or redistribution.get("status") != "known":
        return False
    redistribution = redistribution.get("value")
    if not isinstance(redistribution, str) or not _has_source_evidence(redistribution):
        return False
    folded = " ".join(redistribution.split()).casefold()
    if any(denial in folded for denial in REDISTRIBUTION_DENIALS):
        return False
    outputs = record.get("allowed_outputs")
    return isinstance(outputs, list) and "public-export" in outputs


def _export_private(path: str) -> bool:
    """Never exported, compared case-insensitively for case-insensitive filesystems."""
    return path.casefold().startswith(EXPORT_PRIVATE_PREFIXES) or _is_sensitive_filename(
        Path(path).name
    )


def _derived_export_path(path: str) -> bool:
    folded = path.casefold()
    return folded.startswith(("data/", "artifacts/", "evidence/", "reports/")) and (
        folded not in EXPORT_SOURCE_METADATA
    )


def _export_source_problems(root: Path, head: str, selected: list[str]) -> list[str]:
    """Data and derived outputs need data/sources.yml permission; code and docs do not."""
    governed = [path for path in selected if _derived_export_path(path)]
    if not governed:
        return []
    try:
        document = yaml.safe_load(_committed_text(root, head, "data/sources.yml") or "") or {}
    except (UnicodeError, ValueError, yaml.YAMLError) as exc:
        return [f"data/sources.yml is unreadable: {exc}"]
    sources = document.get("sources") if isinstance(document, dict) else None
    if not isinstance(sources, dict):
        return ["data/sources.yml has no sources mapping"]
    problems = []
    for path in governed:
        folded = path.casefold()
        covering = [
            source_id
            for source_id, record in sources.items()
            if isinstance(record, dict)
            and isinstance(record.get("path"), str)
            and (
                folded == record["path"].casefold()
                or folded.startswith(record["path"].rstrip("/").casefold() + "/")
            )
        ]
        # A derived product may embed any source, so every source must permit publication.
        responsible = covering or list(sources)
        if not responsible:
            problems.append(f"{path}: no source in data/sources.yml grants public-export")
            continue
        refused = [
            str(source_id)
            for source_id in responsible
            if not _source_allows_public(sources[source_id])
        ]
        if refused:
            problems.append(
                f"{path}: source(s) {', '.join(sorted(refused))} lack known redistribution "
                "and `public-export` in allowed_outputs"
            )
    return problems


def _secret_hits(directory: Path, files: list[str]) -> list[str]:
    """Stream-scan every text file; a file that cannot be scanned fails closed."""
    hits = []
    for relative in files:
        path = directory / relative
        if _is_sensitive_filename(path.name):
            hits.append(relative)
            continue
        if path.suffix.casefold() in BINARY_SUFFIXES:
            continue
        try:
            if _stream_contains_secret(path):
                hits.append(relative)
        except (OSError, UnicodeError):
            hits.append(f"{relative} (not scannable as UTF-8 text)")
    return hits


def _staged_manifest(staging: Path) -> dict[str, tuple[str, int]]:
    """(SHA-256, permission bits) of every staged entry; anything but a regular file refuses."""
    manifest = {}
    for path in sorted(staging.rglob("*")):
        metadata = path.lstat()
        if stat.S_ISDIR(metadata.st_mode):
            continue
        if not stat.S_ISREG(metadata.st_mode):
            raise RuntimeError(f"Public export staging holds a non-regular file: {path.name}")
        manifest[path.relative_to(staging).as_posix()] = (
            hashlib.sha256(path.read_bytes()).hexdigest(),
            stat.S_IMODE(metadata.st_mode),
        )
    return manifest


def export_public(root: Path, out: Path) -> dict[str, Any]:
    """Write an allowlisted, history-free public copy of the committed project to `out`."""
    root = root.resolve()
    out = out.resolve()
    if out == root or root in out.parents:
        raise RuntimeError("Public export destination must be outside the project")
    if out.exists() and (not out.is_dir() or any(out.iterdir())):
        raise RuntimeError(f"Public export destination must be new or empty: {out}")
    head, entries = _pinned_commit_entries(root)
    include, exclude, scans = _export_config(root, head)
    selected: list[str] = []
    modes: dict[str, str] = {}
    blobs: dict[str, str] = {}
    refused_private: list[str] = []
    for mode, blob, path in entries:
        if not _export_matches(path, include) or _export_matches(path, exclude):
            continue
        if _export_private(path):
            refused_private.append(path)
            continue
        if mode in {"120000", "160000"}:
            raise RuntimeError(f"Public export refuses symlinks and submodules: {path}")
        selected.append(path)
        modes[path] = mode
        blobs[path] = blob
    if not selected:
        raise RuntimeError("Public export allowlist selected no tracked files")
    problems = _export_source_problems(root, head, selected)
    if problems:
        raise RuntimeError("Public export blocked by data/sources.yml: " + "; ".join(problems))
    staging = Path(tempfile.mkdtemp(prefix=".astack-export-", dir=out.parent))
    try:
        for relative in sorted(selected):
            target = staging / relative
            target.parent.mkdir(parents=True, exist_ok=True)
            # Bytes and executable bit come from the pinned commit, never from the worktree.
            target.write_bytes(_git_bytes(root, ["cat-file", "blob", blobs[relative]]))
            target.chmod(0o755 if modes[relative] == "100755" else 0o644)
        hits = _secret_hits(staging, selected)
        if hits:
            raise RuntimeError("Public export blocked by the secret scan: " + ", ".join(hits))
        scanned = _staged_manifest(staging)
        staging_identity = (staging.lstat().st_dev, staging.lstat().st_ino)
        for command in scans:
            argv = [part.replace("{out}", str(staging)) for part in command]
            try:
                checked = subprocess.run(argv, cwd=root, check=False, capture_output=True)
            except OSError as exc:
                raise RuntimeError(f"Public export scan is unavailable: {argv[0]}") from exc
            if checked.returncode != 0:
                raise RuntimeError(f"Public export scan failed: {' '.join(command)}")
        root_metadata = staging.lstat()
        if (
            not stat.S_ISDIR(root_metadata.st_mode)
            or (
                root_metadata.st_dev,
                root_metadata.st_ino,
            )
            != staging_identity
        ):
            raise RuntimeError("A public export scan hook replaced the staging directory")
        manifest = _staged_manifest(staging)
        if manifest != scanned or sorted(manifest) != sorted(selected):
            raise RuntimeError("A public export scan hook added, removed, or changed files")
        digest = hashlib.sha256()
        for relative in sorted(selected):
            digest.update(f"{relative}\0{modes[relative]}\0{manifest[relative][0]}\0".encode())
        if out.exists():
            out.rmdir()
        staging.rename(out)
    except BaseException:
        shutil.rmtree(staging, ignore_errors=True)
        raise
    return {
        "status": "exported",
        "destination": str(out),
        "source_commit": head,
        "files": sorted(selected),
        "file_sha256": {relative: value[0] for relative, value in manifest.items()},
        "export_sha256": digest.hexdigest(),
        "refused_private": sorted(refused_private),
        "scans": len(scans),
        "history": "none: blobs are read from the pinned commit without .git",
        "publication": "not performed: creating or pushing a repository needs separate approval",
    }


def _publication_declaration(root: Path) -> object:
    """Return the raw [publication] value, or None when the key is absent."""
    try:
        return _project_config(root).get("publication")
    except (OSError, ValueError):
        return None


def _check_publication(root: Path, findings: list[Finding]) -> None:
    """Opt-in journal/archive handoff. Undeclared means not assessed, never complete."""
    declaration = _publication_declaration(root)
    if declaration is None:
        return
    if not isinstance(declaration, dict):
        findings.append(
            _finding(
                "P1",
                "publication",
                "publication-metadata",
                "Declared publication metadata is missing or incomplete.",
                "[publication] must be a table of file paths",
            )
        )
        return

    def incomplete(field: str, problem: str) -> None:
        findings.append(
            _finding(
                "P1",
                "publication",
                "publication-metadata",
                "Declared publication metadata is missing or incomplete.",
                f"{field}: {problem}",
            )
        )

    texts: dict[str, str] = {}
    for field in PUBLICATION_FILES:
        relative = declaration.get(field)
        if not isinstance(relative, str) or not relative.strip():
            incomplete(field, "declare its project-relative path in [publication]")
            continue
        try:
            path = _safe_managed_path(root, relative.strip())
            text = path.read_text(encoding="utf-8")
        except (OSError, UnicodeError, ValueError) as exc:
            incomplete(field, f"{relative} is unreadable or missing ({type(exc).__name__})")
            continue
        if "TODO(publication)" in text:
            incomplete(field, f"{relative} still contains TODO(publication)")
        elif len(" ".join(text.split())) < 40:
            incomplete(field, f"{relative} is too short to be a real {field.replace('_', ' ')}")
        else:
            texts[field] = text
    doi = declaration.get("doi")
    citation_doi = None
    if "citation" in texts:
        citation: object = None
        try:
            citation = yaml.safe_load(texts["citation"]) if yaml is not None else None
        except (ValueError, yaml.YAMLError) as exc:
            incomplete("citation", f"CITATION.cff is not valid YAML: {exc}")
        else:
            if not isinstance(citation, dict):
                incomplete("citation", "CITATION.cff must be a mapping of citation fields")
        if isinstance(citation, dict):
            missing = [
                key
                for key in ("cff-version", "message", "title", "authors", "version")
                if not citation.get(key)
            ]
            if missing:
                incomplete("citation", "CITATION.cff lacks " + ", ".join(missing))
            citation_doi = citation.get("doi")
    for label, value in (("[publication].doi", doi), ("CITATION.cff doi", citation_doi)):
        if value is not None and not (
            isinstance(value, str) and re.fullmatch(r"10\.\d{4,9}/\S+", value)
        ):
            incomplete(label, "a DOI must look like 10.NNNN/suffix")
    if doi is not None and citation_doi is not None and doi != citation_doi:
        incomplete("doi", "[publication].doi and CITATION.cff doi differ")
    if doi is not None or citation_doi is not None:
        findings.append(
            _finding(
                "P2",
                "publication",
                "publication-doi-unverified",
                (
                    "A DOI is recorded but astack cannot check offline that it resolves to this "
                    "release's archive deposit. Confirm it before submission."
                ),
                str(doi or citation_doi),
            )
        )


# --- reports responsibility ---


def _report_paths(root: Path, requested: list[Path]) -> list[Path]:
    if requested:
        return [path if path.is_absolute() else root / path for path in requested]
    reports = root / "reports"
    if not reports.is_dir():
        return []
    found = [
        path
        for pattern in ("*.md", "*.qmd")
        for path in reports.rglob(pattern)
        if path.is_file()
        and not any(part in {"figures", "tables"} for part in path.relative_to(reports).parts)
        and path.name != "README.md"
    ]
    return sorted(found)


def _report_front_matter(lines: list[str]) -> tuple[int, dict[str, Any] | None]:
    """Return how many lines the front matter spans and its mapping (None when unreadable)."""
    if not lines or lines[0].rstrip() != "---":
        return 0, {}
    for index in range(1, len(lines)):
        if lines[index].rstrip() in {"---", "..."}:
            try:
                data = yaml.safe_load("\n".join(lines[1:index]))
            except yaml.YAMLError:
                return index + 1, None
            if data is None:
                return index + 1, {}
            return index + 1, data if isinstance(data, dict) else None
    return len(lines), None  # An opening delimiter with no closing one.


def _report_is_marker(text: str) -> bool:
    """`[UNRESOLVED: x](url)` renders its text without the bracket, so check both forms."""
    return bool(REPORT_UNRESOLVED.search(text)) or text.lstrip().startswith("UNRESOLVED")


def _report_marker_lines(segments: list[tuple[int, str]]) -> list[int]:
    """Join visible text segments, find UNRESOLVED markers, and map each to its start line."""
    text = "".join(data for _, data in segments)
    starts, offset = [], 0
    for line, data in segments:
        starts.append((offset, line, data))
        offset += len(data)
    lines = []
    for match in REPORT_UNRESOLVED.finditer(text):
        for begin, line, data in reversed(starts):
            if begin <= match.start():
                lines.append(line + data[: match.start() - begin].count("\n"))
                break
    return lines


def _report_html_problem(content: str) -> str | None:
    """Raw HTML may only be well-formed comments. Return why anything else is rejected."""
    if REPORT_HTML_COMMENTS.fullmatch(content):
        return None
    if content.lstrip().startswith("<!--"):
        return "a malformed or unclosed <!-- comment -->"
    tag = re.match(r"\s*<\s*(/?[A-Za-z][A-Za-z0-9-]*|[!?][^\s>]*)", content)
    return f"<{tag.group(1)}>" if tag else "raw HTML"


def _report_pandoc_problem(
    text: str,
    after_target: bool,
    escaped: frozenset[int] = frozenset(),
    attributes: str | None = None,
) -> str | None:
    """Pandoc/Quarto syntax CommonMark reads as text, but that changes what a reader sees.

    `escaped` holds the offsets of backslash-escaped characters, which stay literal text.
    """

    def plain(*offsets: int) -> bool:
        return not any(offset in escaped for offset in offsets)

    for match in re.finditer(r"\{\{[<%]", text):
        if plain(match.start(), match.start() + 1):
            return "a Quarto shortcode ({{< ... >}}), which pulls in content this check can't see"
    for match in re.finditer(r"\]\{", text):
        if plain(match.start(), match.start() + 1):
            return "a bracketed span ([text]{...}), which changes the visible text"
    if after_target and text.startswith("{") and plain(0):
        attributes = text if attributes is None else attributes  # may run onto later lines
        close = attributes.find("}")
        block = attributes[1:close] if close > 0 else attributes[1:]
        if close < 0 or not all(REPORT_SAFE_ATTRIBUTE.fullmatch(part) for part in block.split()):
            return (
                f"the attributes {{{block}}}. Only width, height, #id and .class are allowed "
                "after an image, link or inline code"
            )
    return None


def _report_join_text(state: Any) -> None:
    """Join adjacent text like markdown-it's text_join, but remember escaped characters.

    Pandoc reads `\\{` and `&#123;` as literal braces, so `[x]\\{.a}` is text, not a span.
    markdown-it drops that difference when it joins text, so record each literal offset.
    """
    for block in state.tokens:
        if block.type == "inline" and block.children:
            block.children = _report_joined(block.children)


def _report_joined(tokens: list[Any]) -> list[Any]:
    children: list[Any] = []
    for child in tokens:
        if child.type == "image" and child.children:
            child.children = _report_joined(child.children)  # alt text
        if child.type not in {"text", "text_special"}:
            children.append(child)
            continue
        # Backslash escapes and entities (`&#123;`) both decode to literal characters.
        literal = child.type == "text_special"
        previous = children[-1] if children else None
        if previous is not None and previous.type == "text":
            offset = len(previous.content)
            previous.content += child.content
        else:
            child.type, offset = "text", 0
            child.meta["escaped"] = frozenset()
            children.append(child)
            previous = child
        if literal:
            span = range(offset, offset + len(child.content))
            previous.meta["escaped"] = previous.meta["escaped"] | set(span)
    return children


def _report_attribute_text(children: list[Any], index: int) -> str:
    """Return the text at `index`, joined with the next lines when a `{` block wraps.

    Pandoc lets `{.python` and `#fit}` sit on two lines, so read on to the closing brace.
    """
    text: str = children[index].content
    if not text.startswith("{") or "}" in text:
        return text
    for child in children[index + 1 :]:
        if child.type == "softbreak":
            text += "\n"
        elif child.type == "text":
            text += child.content
            if "}" in child.content:
                break
        else:
            break
    return text


def _report_positioned(rule: Any) -> Any:
    """Wrap an inline rule so each token it creates records where in the source it began."""

    def wrapped(state: Any, silent: bool) -> bool:
        start, count = state.pos, len(state.tokens)
        found = bool(rule(state, silent))
        if found and not silent:
            for token in state.tokens[count:]:
                token.meta.setdefault("pos", start)
                token.meta.setdefault("end", state.pos)
        return found

    return wrapped


def _report_parser() -> Any:
    parser = markdown_it("commonmark").enable(["table", "strikethrough"])
    ruler = parser.inline.ruler
    for rule in list(ruler.__rules__):
        ruler.at(rule.name, _report_positioned(rule.fn), {"alt": list(rule.alt)})
    parser.core.ruler.at("text_join", _report_join_text)
    return parser


def _report_items(text: str) -> list[tuple[str, int, Any, str]]:
    """Return (kind, line, destination, text) for figures, links, markers and raw HTML."""
    items: list[tuple[str, int, Any, str]] = []
    parser = _report_parser()
    for token in parser.parse(text):
        start = token.map[0] + 1 if token.map else 1
        if token.type == "html_block":
            problem = _report_html_problem(token.content)
            if problem is not None:
                items.append(("unsupported", start, problem, ""))
            continue
        if token.type == "fence" and re.match(r"\s*\{\s*=", token.info):
            # ```{=html} is a Pandoc raw block, which renders its content unchecked.
            problem = f"a raw block ```{token.info.strip()}, which renders unchecked content"
            items.append(("unsupported-syntax", start, problem, ""))
            continue
        if token.type != "inline" or not token.children:
            continue
        source = token.content
        breaks = [index for index, character in enumerate(source) if character == "\n"]

        def line_at(offset: int) -> int:
            return start + bisect_right(breaks, offset - 1)  # noqa: B023

        line, last_end, previous = start, 0, ""
        prose: list[tuple[int, str]] = []  # (line, visible text) between line breaks
        link: list[Any] | None = None  # [line, href, text parts]
        for index, child in enumerate(token.children):
            # Text flushed at the end of a paragraph has no rule of its own, so it starts
            # where the previous token ended.
            line = line_at(child.meta.get("pos", last_end))
            last_end = child.meta.get("end", last_end)
            if child.type in {"softbreak", "hardbreak"}:
                items.extend(("marker", found, None, "") for found in _report_marker_lines(prose))
                prose = []
                if link is not None:
                    link[2].append(" ")
            elif child.type in {"text", "code_inline"}:
                if child.type == "text":
                    prose.append((line, child.content))
                    problem = _report_pandoc_problem(
                        child.content,
                        previous in {"image", "link_close", "code_inline"},
                        child.meta.get("escaped", frozenset()),
                        _report_attribute_text(token.children, index),
                    )
                    if problem is not None:
                        items.append(("unsupported-syntax", line, problem, ""))
                if link is not None:
                    link[2].append(child.content)
            elif child.type == "image":
                # Alt text shows when the image can't load, so it counts as visible text.
                # Render it the way markdown-it writes the alt attribute.
                alt = parser.renderer.renderInlineAsText(child.children, parser.options, {})
                items.append(("figure", line, child.attrs.get("src", ""), alt))
                prose.append((line, alt))
                if _report_is_marker(alt):
                    items.append(("marker", line, None, ""))
                if link is not None:
                    link[2].append(alt)
            elif child.type == "html_inline":
                # Only comments are allowed. They show nothing, so [0.<!-- x -->83] reads 0.83.
                problem = _report_html_problem(child.content)
                if problem is not None:
                    items.append(("unsupported", line, problem, ""))
            elif child.type == "link_open":
                link = [line, child.attrs.get("href", ""), []]
            elif child.type == "link_close" and link is not None:
                label = "".join(link[2])
                items.append(("link", link[0], link[1], label))
                if _report_is_marker(label):
                    items.append(("marker", link[0], None, ""))
                link = None
            previous = child.type
        items.extend(("marker", found, None, "") for found in _report_marker_lines(prose))
    return items


def _json_pointer(document: Any, pointer: str) -> Any:
    if pointer == "":
        return document
    if not pointer.startswith("/"):
        raise KeyError(pointer)
    current = document
    for raw in pointer[1:].split("/"):
        token = raw.replace("~1", "/").replace("~0", "~")
        if isinstance(current, list):
            if not token.isdigit():
                raise KeyError(pointer)
            current = current[int(token)]
        elif isinstance(current, dict):
            current = current[token]
        else:
            raise KeyError(pointer)
    return current


def _is_cited_value(text: str) -> bool:
    return bool(REPORT_CITED_VALUE.fullmatch(text.strip()))


def _cited_value_matches(displayed: str, value: Any) -> bool:
    """Round the stored value half-up to the last digit shown, then compare exactly."""
    text = displayed.strip().replace(",", "").replace("\u2212", "-").removesuffix("%")
    shown = Decimal(text)  # InvalidOperation is reported by the caller.
    if isinstance(value, bool) or not isinstance(value, (int, Decimal)):
        return False
    exponent = shown.as_tuple().exponent
    if not isinstance(exponent, int):  # NaN or infinity
        raise InvalidOperation(text)
    step = Decimal((0, (1,), exponent))
    context = Context(prec=1000, rounding=ROUND_HALF_UP)
    return Decimal(value).quantize(step, context=context) == shown


def _problem(line: int, kind: str, message: str) -> dict[str, Any]:
    return {"line": line, "kind": kind, "message": message}


def _report_inner_parent(location: str) -> bool:
    """True when `..` follows a named folder, as in `figures/../x.png`.

    Leading `../` steps (from reports/ to evidence/) resolve the same way in a browser and on
    disk. A later `..` can resolve differently once a folder is a symlink, so it is rejected.
    """
    segments = location.split("/")
    leading = 0
    while leading < len(segments) and segments[leading] == "..":
        leading += 1
    return ".." in segments[leading:]


def _evidence_problems(
    evidence: tuple[dict[str, Any], bool, list[dict[str, Any]], Path] | None,
    line: int,
    kind: str,
    relative: str,
) -> list[dict[str, Any]]:
    """A report may cite only current pipeline outputs.

    Outdated or missing outputs always fail. Files no run produced, and outputs whose state
    could not be read, fail a final report and are listed for a draft.
    """
    if evidence is None:
        return []
    status, final, notes, root = evidence
    record = run_record_citation(root, relative)
    if record is not None:
        if record and kind != "figure":
            return []
        return [
            _problem(
                line,
                "outdated-evidence",
                f"The {kind} cites {relative}, which is not a current run record",
            )
        ]
    entry = evidence_label(status, relative)
    if entry is not None and entry["label"] == "current":
        # Declared deps still decide staleness. A stage whose reads could not be checked, such
        # as an R or shell stage, is disclosed, never failed.
        if entry.get("dependency_check") in {"untraced", "not-run", "inputs-not-locked"}:
            notes.append(
                _problem(
                    line,
                    "reads-not-checked",
                    f"The {kind} cites {relative}, whose stage's reads were not fully checked "
                    f"({entry['dependency_check']}). Its declared deps still decide staleness.",
                )
            )
        return []
    if entry is not None and entry["label"] in {"outdated", "missing"} and entry["stage"]:
        return [
            _problem(
                line,
                "outdated-evidence",
                f"The {kind} cites {relative}, which is {entry['label']}: {entry['reason']}",
            )
        ]
    if entry is not None and entry["label"] == "unknown":
        problem = _problem(
            line,
            "unverified-evidence",
            f"The {kind} cites {relative}, whose state could not be checked: {entry['reason']}",
        )
    elif status.get("status") == "unknown":
        problem = _problem(
            line,
            "unverified-evidence",
            f"The {kind} cites {relative}, but output state could not be checked: "
            f"{status.get('problem')}",
        )
    else:
        problem = _problem(
            line,
            "unrecorded-evidence",
            f"The {kind} cites {relative}, which no recorded pipeline run produced",
        )
    if final:
        return [problem]
    notes.append(problem)
    return []


def _check_report_link(
    root: Path,
    report: Path,
    line: int,
    text: str,
    destination: str,
    image: bool,
    evidence: tuple[dict[str, Any], bool, list[dict[str, Any]], Path] | None = None,
) -> list[dict[str, Any]]:
    cited = _is_cited_value(text)
    kind = "figure" if image else "cited value" if cited else None
    if not destination or destination.startswith("#") or destination.startswith("//"):
        external = True
    else:
        external = bool(REPORT_URL_SCHEME.match(destination))
    if external:
        if kind is None:
            return []
        return [
            _problem(
                line,
                "not-evidence",
                f"The {kind} points at {destination or 'nothing'}, not a file in the project",
            )
        ]
    location, _, fragment = destination.partition("#")
    raw_path = location.split("?", 1)[0]
    location = unquote(raw_path)
    fragment = unquote(fragment)
    if kind is not None and (
        destination != destination.strip(" \t\n\f\r")
        or location != location.strip(" \t\n\f\r")
        or any(
            character == "\\" or ord(character) < 0x20 or ord(character) == 0x7F
            for character in destination + location
        )
        # Browsers keep empty segments and never split on an encoded separator, while the
        # filesystem collapses `//` and decoding turns %2F into "/".
        or "//" in raw_path
        or re.search(r"%(2f|5c)", raw_path, re.IGNORECASE)
        or _report_inner_parent(location)
    ):
        # Browsers read a backslash as "/", drop control characters and trim surrounding
        # spaces, so the file they load isn't the one a literal path names.
        return [
            _problem(
                line,
                "unsupported-path",
                f"The {kind} path has a backslash, control character, surrounding space, `//`, "
                "encoded separator or a `..` after a folder name: "
                f"{destination!r}",
            )
        ]
    # Resolve `..` the way a browser does, by the text of the path, before the filesystem
    # follows any symlink.
    resolved = Path(posixpath.normpath(posixpath.join(report.parent.as_posix(), location)))
    resolved = resolved.resolve()
    if kind is None:
        if not resolved.exists():
            return [_problem(line, "missing-file", f"Link target does not exist: {location}")]
        return []
    try:
        relative = resolved.relative_to(root).as_posix()
    except ValueError:
        return [
            _problem(line, "outside-project", f"The {kind} points outside the project: {location}")
        ]
    if not any(relative.startswith(prefix) for prefix in REPORT_EVIDENCE_ROOTS):
        allowed = ", ".join(REPORT_EVIDENCE_ROOTS)
        return [
            _problem(
                line,
                "not-evidence",
                f"The {kind} points at {relative}, which is not under {allowed}",
            )
        ]
    if not resolved.is_file():
        return [_problem(line, "missing-file", f"The {kind} points at a missing file: {relative}")]
    problems = _evidence_problems(evidence, line, kind, relative)
    if image or not fragment:
        return problems
    if resolved.suffix.lower() != ".json":
        return problems + [
            _problem(
                line, "unsupported-pointer", f"A value pointer needs a JSON file, not {relative}"
            )
        ]
    try:
        document = json.loads(resolved.read_text(encoding="utf-8"), parse_float=Decimal)
        value = _json_pointer(document, fragment)
    except (KeyError, IndexError, ValueError, UnicodeDecodeError):
        return problems + [_problem(line, "missing-value", f"No value at {relative}#{fragment}")]
    try:
        matches = _cited_value_matches(text, value)
    except InvalidOperation:
        return problems + [_problem(line, "invalid-number", f"Not a number: {text.strip()}")]
    if not matches:
        return problems + [
            _problem(
                line,
                "value-mismatch",
                f"The report shows {text.strip()}, but {relative}#{fragment} is {value}",
            )
        ]
    return problems


def check_report(
    root: Path, report: Path, output_state: dict[str, Any] | None = None
) -> dict[str, Any]:
    report = report.resolve()
    relative = report.relative_to(root).as_posix() if report.is_relative_to(root) else str(report)
    if not report.is_file():
        return {
            "path": relative,
            "status": "failed",
            "final": False,
            "problems": [_problem(0, "missing-report", f"Report not found: {relative}")],
        }
    result = _check_report_text(root, report, report.read_text(encoding="utf-8"), output_state)
    for finding in [*result["problems"], *result["evidence_notes"]]:
        finding.pop("item", None)
    return result


def _check_report_text(
    root: Path, report: Path, text: str, output_state: dict[str, Any] | None = None
) -> dict[str, Any]:
    """Check one already-read report. A finding from a link or figure names its parsed `item`."""
    relative = report.relative_to(root).as_posix() if report.is_relative_to(root) else str(report)
    lines = text.split("\n")
    skip, front_matter = _report_front_matter(lines)
    problems: list[dict[str, Any]] = []
    if front_matter is None:
        problems.append(
            _problem(1, "invalid-front-matter", "Front matter is not a closed YAML mapping")
        )
    status = str((front_matter or {}).get("status", "")).strip().casefold()
    final = front_matter is None or status == "final"
    # Blank the front matter so parser line numbers stay true to the file.
    body = "\n".join([""] * skip + lines[skip:])
    figures = cited = 0
    unresolved: list[int] = []
    notes: list[dict[str, Any]] = []
    evidence = None if output_state is None else (output_state, final, notes, root)
    for index, (kind, line, destination, label) in enumerate(_report_items(body)):
        if kind in {"figure", "link"}:
            figures += kind == "figure"
            cited += kind == "link" and _is_cited_value(label)
            noted = len(notes)
            found = _check_report_link(
                root, report, line, label, destination, kind == "figure", evidence
            )
            for finding in [*found, *notes[noted:]]:
                finding["item"] = index
            problems.extend(found)
        elif kind == "unsupported-syntax":
            problems.append(_problem(line, "unsupported-syntax", f"The report uses {destination}"))
        elif kind == "unsupported":
            problems.append(
                _problem(
                    line,
                    "unsupported-html",
                    f"Raw HTML ({destination}) isn't checked, so reports can't use it. "
                    "Use Markdown links and images. HTML comments are fine",
                )
            )
        elif (kind == "marker" or REPORT_UNRESOLVED.search(label)) and line not in unresolved:
            unresolved.append(line)
    unresolved.sort()
    if final:
        problems.extend(
            _problem(number, "unresolved", "A final report still has an UNRESOLVED marker")
            for number in unresolved
        )
    problems.sort(key=lambda problem: problem["line"])
    return {
        "path": relative,
        "status": "failed" if problems else "passed",
        "final": final,
        "figures": figures,
        "cited_values": cited,
        "unresolved_lines": unresolved,
        "problems": problems,
        "evidence_notes": notes,
    }


def report_check(root: Path, requested: list[Path]) -> dict[str, Any]:
    """Check reports, or every report under `reports/` when none is named."""
    if markdown_it is None or yaml is None:
        return {
            "status": "unavailable",
            "summary": (
                'report-check needs markdown-it-py and PyYAML. Add "markdown-it-py>=3.0" and '
                '"pyyaml>=6.0" to [dependency-groups] dev in pyproject.toml, then run uv sync.'
            ),
            "reports": [],
        }
    paths = _report_paths(root, requested)
    if not paths:
        return {
            "status": "no-reports",
            "summary": "No reports found under reports/. Nothing was checked.",
            "reports": [],
        }
    try:
        outputs = output_status(root)
    except (OSError, RuntimeError, ValueError) as exc:
        outputs = {"status": "unknown", "problem": str(exc), "outputs": []}
    results = [check_report(root, path, outputs) for path in paths]
    failed = [result for result in results if result["status"] == "failed"]
    return {
        "status": "failed" if failed else "passed",
        "summary": (
            f"{len(failed)} of {len(results)} report(s) failed."
            if failed
            else f"{len(results)} report(s) passed."
        ),
        "reports": results,
    }


# --- review responsibility ---


def _review_git(root: Path, *arguments: str) -> subprocess.CompletedProcess[str]:
    try:
        return _run(["git", *arguments], cwd=root, timeout=30)
    except subprocess.TimeoutExpired as error:
        raise OSError("Git timed out while reading review state") from error
    except UnicodeError as error:
        raise OSError("Git returned unreadable review state") from error


def _git(root: Path, *arguments: str) -> str | None:
    try:
        result = _review_git(root, "--no-replace-objects", *arguments)
    except OSError:
        return None
    return result.stdout.strip() if result.returncode == 0 else None


def _git_on_paths(
    root: Path, *arguments: str, paths: list[str]
) -> subprocess.CompletedProcess[str]:
    """Run git on exact paths: literal pathspecs, so a name like `a*b.py` never globs."""
    return _review_git(
        root, "--no-replace-objects", "--literal-pathspecs", *arguments, "--", *paths
    )


def _stored_blobs(root: Path, commit: str, files: list[str]) -> dict[str, tuple[str, str]] | None:
    """Each file's mode and blob id at a commit, or None when git cannot say."""
    tree = _git_on_paths(root, "ls-tree", "-z", commit, paths=files)
    if tree.returncode != 0:
        return None
    blobs: dict[str, tuple[str, str]] = {}
    for item in filter(None, tree.stdout.split("\0")):
        meta, _, relative = item.partition("\t")
        mode, _, blob = meta.split(" ")
        blobs[relative] = (mode, blob)
    return blobs


def _raw_blob_ids(root: Path, files: list[str]) -> list[str]:
    """The blob id of each file's raw bytes, with no clean filter or line-ending conversion."""
    for relative in files:
        _require_regular_file(root / relative)
    result = _git_on_paths(root, "hash-object", "--no-filters", paths=files)
    hashes = result.stdout.split()
    if result.returncode != 0 or len(hashes) != len(files):
        detail = result.stderr.strip().splitlines()
        raise OSError(
            "Git could not hash review files" + (f": {detail[-1][:200]}" if detail else "")
        )
    return hashes


def _uncommitted(root: Path, files: list[str], revision: str = "HEAD") -> list[str]:
    """Code files a commit (HEAD by default) does not store byte for byte.

    Compared on raw bytes: a clean filter or line-ending conversion can make git call a file
    unchanged while the bytes that run differ. A symlink counts as uncommitted, since the code
    read is its target, which HEAD does not store under that name. If git cannot tell, every
    file counts.
    """
    if not files:
        return []
    links = [relative for relative in files if (root / relative).is_symlink()]
    if links:
        return links
    stored = _stored_blobs(root, revision, files)
    if stored is None:
        return list(files)
    hashes = _raw_blob_ids(root, files)
    return [
        relative
        for relative, blob in zip(files, hashes, strict=True)
        if stored.get(relative) not in {("100644", blob), ("100755", blob)}
    ]


def _visible(text: str) -> str:
    """Carriage returns, tabs and spaces at a line's end as markers, so every byte shows."""
    text = text.replace("\r", "\u240d").replace("\t", "\u21e5")
    # Try each run of spaces once. Retrying at every space makes internal runs quadratic.
    return re.sub(r"(?<! ) +(?=\n|\Z)", lambda match: "\u2423" * len(match.group()), text)


def _raw_diff(
    root: Path, relative: str, blob: str | None, data: bytes, context: int = 3
) -> tuple[str | None, str]:
    """A unified diff of a file's stored bytes against its bytes on disk, or why there is none.

    Built here rather than by git diff, so no filter, driver or setting can change what is shown.
    Carriage returns, tabs and trailing spaces show as markers. A file that already contains a
    marker needs a full read, as does any change that would display as no change.
    """
    import difflib

    old = b""
    if blob is not None:
        try:
            shown = subprocess.run(
                ["git", "--no-replace-objects", "cat-file", "blob", blob],
                cwd=root,
                capture_output=True,
                check=False,
                timeout=30,
            )
        except (OSError, subprocess.TimeoutExpired):
            return None, f"git could not read the reviewed {relative}"
        if shown.returncode != 0:
            return None, f"git could not read the reviewed {relative}"
        old = shown.stdout
    try:
        before, after = old.decode("utf-8"), data.decode("utf-8")
    except UnicodeDecodeError:
        return None, f"{relative} changed and is not UTF-8 text, so it cannot be shown as a diff"
    # Shown so every byte is visible: carriage returns, tabs and spaces at a line's end get a
    # marker, and a file already holding a marker needs a full read, so no two texts look alike.
    markers = "\u240d\u21e5\u2423"
    if any(marker in before or marker in after for marker in markers):
        return None, f"{relative} contains a character used to show whitespace"
    # An invisible, control or line-separator character (other than newline, tab and carriage
    # return) could hide or fake a change.
    if any(not (char.isprintable() or char in "\n\t\r") for char in before + after):
        return None, f"{relative} contains invisible or control characters"
    before, after = _visible(before), _visible(after)
    if before == after:
        return None, f"{relative} changed in a way a text diff cannot show"
    lines = difflib.unified_diff(
        before.splitlines(keepends=True),
        after.splitlines(keepends=True),
        f"a/{relative}" if blob else "/dev/null",
        f"b/{relative}",
        n=context,
    )
    return "".join(
        line if line.endswith("\n") else line + "\n\\ No newline at end of file\n" for line in lines
    ), ""


def _header(root: Path) -> dict[str, Any]:
    status = _git(root, "status", "--porcelain", "--untracked-files=normal")
    return {
        "branch": _git(root, "rev-parse", "--abbrev-ref", "HEAD"),
        "commit": _git(root, "rev-parse", "--short", "HEAD"),
        "uncommitted_changes": None if status is None else bool(status),
    }


def _files(root: Path, relative: str) -> tuple[list[str], str | None]:
    """A code dep's files, or why they cannot all be listed.

    A missing dep, or a symlinked folder inside one (its target could change unseen), means the
    code set is unknown, never empty. Symlinked files are hashed by their target's bytes.
    """
    path = root / relative

    def fail(error: OSError) -> None:
        raise error

    files: list[str] = []
    try:
        mode = path.stat().st_mode
        if stat.S_ISREG(mode):
            return [relative], None
        if not stat.S_ISDIR(mode):
            return [], f"{relative} is not a regular file or folder"
        for current, directories, names in os.walk(path, followlinks=False, onerror=fail):
            here = Path(current)
            for name in directories:
                if (here / name).is_symlink():
                    return [], f"{(here / name).relative_to(root).as_posix()} is a symlinked folder"
            directories[:] = [name for name in directories if name != "__pycache__"]
            files.extend((here / name).relative_to(root).as_posix() for name in names)
    except FileNotFoundError:
        return [], f"{relative} is missing"
    except (OSError, ValueError) as error:
        return [], f"Could not list {relative}: {error}"
    return sorted(files), None


def _step_name(stage: str) -> str:
    """The step a DVC stage belongs to: `clean@north` is an item of the `clean` group."""
    return stage.split("@", 1)[0]


def _new_unit(unit: str, kind: str) -> dict[str, Any]:
    return {
        "unit": unit,
        "kind": kind,
        "items": [],
        "files": set(),
        "shared": [],
        "commands": [],
        "params": {},
        "declared_in": set(),
        "unknown": None,
        "upstream": set(),
        "downstream": set(),
        "used_by": [],
    }


def _add_stage(root: Path, unit: dict[str, Any], stage: dict[str, Any], reads: list[str]) -> None:
    """Add one resolved DVC stage to its step: its command, parameters, code and data inputs."""
    name = str(stage.get("name"))
    item: dict[str, Any] = {
        "name": name,
        "key": name.split("@", 1)[1] if "@" in name else None,
        "command": stage.get("cmd"),
        "wdir": str(stage.get("wdir") or "."),
        "frozen": bool(stage.get("frozen")),
        "settings": stage.get("settings") or {},
        "code": [],
        "inputs": [],
        "outputs": [str(out.get("path")) for out in stage.get("outs", []) if isinstance(out, dict)],
    }
    unit["items"].append(item)
    if stage.get("dvcfile"):
        unit["declared_in"].add(str(stage["dvcfile"]))
    if reads and unit["unknown"] is None:
        unit["unknown"] = f"stage {name} reads undeclared files: {', '.join(reads[:3])}"
    values: dict[str, Any] = {}
    for dep in stage.get("deps", []):
        path = str(dep.get("path")) if isinstance(dep, dict) else ""
        if isinstance(dep, dict) and "params_problem" in dep:
            unit["unknown"] = unit["unknown"] or dep["params_problem"]
            continue
        if isinstance(dep, dict) and "params" in dep:
            values |= {f"{path}:{key}": value for key, value in dep["params"].items()}
            unit["declared_in"].add(path)
            if dep.get("params_missing") and unit["unknown"] is None:
                missing = ", ".join(map(str, dep["params_missing"][:3]))
                unit["unknown"] = f"stage {name} names parameters {path} lacks: {missing}"
            continue
        if not path or path in UNREVIEWED_CODE:
            continue
        if _classify_output_path(path)["lifecycle"] in NOT_CODE_LIFECYCLES:
            item["inputs"].append(path)
            continue
        item["code"].append(path)
        found, missing_dep = _files(root, path)
        unit["files"].update(found)
        if missing_dep and unit["unknown"] is None:
            unit["unknown"] = missing_dep
    unit["params"][name] = values
    # Which data a stage reads and writes is signed off by path. Data contents are not code.
    unit["commands"].append(
        json.dumps(
            [
                name,
                stage.get("cmd"),
                stage.get("wdir"),
                sorted(item["inputs"]),
                sorted(item["outputs"]),
                sorted(item["code"]),
                item["frozen"],
                item["settings"],
            ],
            default=str,
        )
    )


def _dvc_units(root: Path) -> tuple[dict[str, dict[str, Any]], str | None]:
    """One unit per DVC step. `foreach` and `matrix` items are one step, since they share code."""
    pipeline, problem = _dvc_pipeline(root, read_only=True, stages_only=True)
    if pipeline is None:
        return {}, problem
    stages = [stage for stage in pipeline["stages"] if isinstance(stage, dict)]
    checks = dependency_checks(root)
    units: dict[str, dict[str, Any]] = {}
    for stage in stages:
        name = str(stage.get("name"))
        step = _step_name(name)
        reads = (checks.get(name) or {}).get("undeclared_reads") or []
        _add_stage(root, units.setdefault(step, _new_unit(step, "step")), stage, reads)
    edges, _ = _stage_edges(root, stages)
    for name, parents in edges.items():
        for parent in parents:
            child, source = _step_name(name), _step_name(parent)
            if child != source:
                units[child]["upstream"].add(source)
                units[source]["downstream"].add(child)
    return units, None


def _command_unit(root: Path, config: dict[str, Any]) -> dict[str, dict[str, Any]]:
    """A project without DVC has one step: its reproduction command and tracked code."""
    import shlex

    reproduction = config.get("reproduction", {})
    command = reproduction.get("command")
    if not command:
        return {}
    name = str(reproduction.get("component") or "pipeline")
    unit = _new_unit(name, "step")
    # -z gives raw names: without it Git quotes non-ASCII paths like caf\303\251.py.
    try:
        listing = _review_git(root, "ls-files", "-z", "--", "src", "scripts")
    except OSError as error:
        unit["unknown"] = f"Git could not list src/ and scripts/: {error}"
    else:
        if listing.returncode != 0:
            unit["unknown"] = "git could not list src/ and scripts/"
        else:
            unit["files"].update(item for item in listing.stdout.split("\0") if item)
    # How the code is run is part of what is reviewed.
    outputs = [str(item) for item in reproduction.get("outputs", [])]
    # Same shape as a DVC stage's identity, so outputs are signed off and changes read the same.
    unit["commands"].append(
        json.dumps(["command", command, ".", [], sorted(outputs), [], False, {}], default=str)
    )
    unit["declared_in"].add(".astack/project.toml")
    # Quoted, so `["a b"]` and `["a", "b"]` never read the same.
    text = shlex.join(map(str, command)) if isinstance(command, list) else str(command)
    unit["items"].append(
        {
            "name": name,
            "key": None,
            "command": text,
            "wdir": ".",
            "frozen": False,
            "settings": {},
            "code": [],
            "inputs": [],
            "outputs": outputs,
        }
    )
    unit["params"][name] = {}
    return {name: unit}


def _in_pipeline_order(units: dict[str, dict[str, Any]]) -> list[str]:
    """Steps with everything upstream first, ties in the order DVC lists them."""
    depth: dict[str, int] = {}

    def depth_of(name: str, seen: frozenset[str] = frozenset()) -> int:
        if name not in depth:
            parents = [item for item in units[name]["upstream"] if item not in seen]
            depth[name] = 1 + max((depth_of(item, seen | {name}) for item in parents), default=-1)
        return depth[name]

    for name in units:
        units[name]["depth"] = depth_of(name)
    return sorted(units, key=lambda name: units[name]["depth"])


def _review_units(
    root: Path, config: dict[str, Any]
) -> tuple[dict[str, dict[str, Any]], str | None]:
    """Everything a person signs off: each pipeline step, then code that several steps share.

    A file used by two or more steps is signed off once, on its own, so a change to it asks for
    one review rather than one per step. Which files a step uses comes from its declared deps,
    and a saved dependency check showing undeclared reads makes the step `unknown`.
    """
    reproduction = config.get("reproduction", {})
    if not isinstance(reproduction, dict):
        return {}, "Project configuration: reproduction must be a table"
    if _reproduction_engine(root, config) == "dvc":
        found, problem = _dvc_units(root)
        if problem:
            return {}, problem
    else:
        if not isinstance(reproduction.get("outputs", []), list):
            return {}, "Project configuration: reproduction.outputs must be a list of paths"
        if "command" in reproduction and not _reproduction_command(root, config):
            return (
                {},
                "Project configuration: reproduction.command must be a non-empty command array",
            )
        found = _command_unit(root, config)
    steps = {name: found[name] for name in _in_pipeline_order(found)}
    users: dict[str, list[str]] = {}
    for name, unit in steps.items():
        unit["files"] -= UNREVIEWED_CODE
        for relative in unit["files"]:
            users.setdefault(relative, []).append(name)
    common = {relative for relative, names in users.items() if len(names) > 1}
    units = dict(steps)
    for unit in steps.values():
        unit["shared"] = sorted(unit["files"] & common)
        unit["files"] = sorted(unit["files"] - common)
    for relative in sorted(common):
        unit = _new_unit(f"shared:{relative}", "shared")
        unit["files"] = [relative]
        unit["used_by"] = users[relative]
        units[unit["unit"]] = unit
    for unit in units.values():
        unit["commands"] = sorted(unit["commands"])
    return units, None


def _code_checksum(
    root: Path,
    files: list[str],
    commands: list[str],
    params: dict[str, Any] | None = None,
    shared: list[str] | None = None,
    *,
    rendered: dict[str, bytes] | None = None,
) -> str:
    digest = hashlib.sha256(b"astack-review-code-v3\0")
    for command in commands:
        digest.update(f"command\0{command}\n".encode())
    digest.update(f"params\0{json.dumps(params or {}, sort_keys=True, default=str)}\n".encode())
    digest.update(f"shared\0{json.dumps(shared or [])}\n".encode())
    for relative in files:
        file_hash = (
            _sha256(root / relative, regular_only=True)
            if rendered is None
            else hashlib.sha256(rendered[relative]).hexdigest()
        )
        digest.update(f"{relative}\0{file_hash}\n".encode())
    return digest.hexdigest()


def _record_name(text: str) -> str:
    """A file name for any unit: readable, and unique through a short hash of the exact name."""
    slug = re.sub(r"[^a-z0-9_-]+", "-", text.lower()).strip("-")[:80]
    return f"{slug}-{hashlib.sha256(text.encode()).hexdigest()[:12]}"


def _review_record_path(root: Path, unit: str) -> Path:
    """Records are workflow metadata, kept out of the derived folders pipelines read."""
    if unit.startswith("shared:"):
        return root / REVIEW_RECORD_ROOT / "shared" / f"{_record_name(unit[7:])}.json"
    name = unit if re.fullmatch(r"[a-z0-9][a-z0-9_-]*", unit) else _record_name(unit)
    return root / REVIEW_RECORD_ROOT / f"{name}.json"


def _valid_sign_off(record: dict[str, Any]) -> bool:
    return (
        isinstance(record.get("reviewer"), str)
        and bool(record["reviewer"].strip())
        and isinstance(record.get("commit"), str)
        and re.fullmatch(r"[0-9a-f]{40,64}", record["commit"]) is not None
        and isinstance(record.get("reviewed_at"), str)
        and bool(record["reviewed_at"])
        and isinstance(record.get("code_checksum"), str)
        and re.fullmatch(r"[0-9a-f]{64}", record["code_checksum"]) is not None
    )


def _valid_review(record: object, unit: str) -> bool:
    """A record counts only with its own unit and either a complete sign-off or revocation."""
    if not isinstance(record, dict):
        return False
    if record.get("schema_version") != 2 or record.get("unit") != unit:
        return False
    if record.get("revoked") is True:
        return (
            isinstance(record.get("by"), str)
            and bool(record["by"].strip())
            and isinstance(record.get("at"), str)
            and bool(record["at"])
            and isinstance(record.get("reason"), str)
        )
    return "revoked" not in record and _valid_sign_off(record)


def _load_review(root: Path, unit: str) -> tuple[dict[str, Any] | None, bool]:
    """The record and whether it is valid. A missing record is (None, True)."""
    path = _review_record_path(root, unit)
    try:
        mode = path.lstat().st_mode
    except FileNotFoundError:
        return None, True
    except OSError:
        return None, False
    try:
        if not stat.S_ISREG(mode):
            return None, False
        with _open_regular_file(path) as handle:
            record = json.loads(handle.read().decode("utf-8"))
    except (OSError, ValueError, RecursionError):
        return None, False
    return (record, True) if _valid_review(record, unit) else (None, False)


def _param_changes(old: dict[str, Any], new: dict[str, Any]) -> list[dict[str, Any]]:
    """Each parameter value that differs from the signed-off one, per stage."""
    changes: list[dict[str, Any]] = []
    for stage in sorted(set(old) | set(new)):
        before, after = old.get(stage) or {}, new.get(stage) or {}
        for key in sorted(set(before) | set(after)):
            if key not in before or key not in after or before[key] != after[key]:
                changes.append(
                    {
                        "stage": stage,
                        "key": key,
                        "was": before.get(key),
                        "now": after.get(key),
                        "added": key not in before,
                        "removed": key not in after,
                    }
                )
    return changes


def _since_review(root: Path, row: dict[str, Any], commands: list[str]) -> dict[str, Any]:
    """What changed in a unit's code since its last sign-off, or why only a full read will do.

    A diff stands in for a full review only when it provably covers every change: the sign-off
    recorded its files, commands and parameters, the signed-off code was committed, that commit
    is in this branch's history, and every file still in the unit is tracked. Otherwise the
    reviewer is told to read the whole unit and why.
    """
    record = row["review"]

    def full(why: str) -> dict[str, Any]:
        return {"mode": "full", "why": why}

    if not isinstance(record, dict):
        return full("its sign-off was revoked" if row.get("revoked") else "no earlier sign-off")
    old_files, old_commands = record.get("files"), record.get("commands")
    old_params, old_shared = record.get("params"), record.get("shared")
    if (
        not isinstance(old_files, list)
        or not isinstance(old_commands, list)
        or not isinstance(old_params, dict)
        or any(not isinstance(values, dict) for values in old_params.values())
        or not isinstance(old_shared, list)
    ):
        return full("the earlier sign-off did not record what it covered")
    if record.get("code_committed") is not True:
        return full("the earlier review covered uncommitted code, so no commit shows what was read")
    commit = str(record["commit"])
    ancestor = _review_git(
        root, "--no-replace-objects", "merge-base", "--is-ancestor", commit, "HEAD"
    )
    if ancestor.returncode != 0:
        return full(
            f"git could not verify the reviewed commit {commit[:12]} is in this branch's history"
        )
    kept = sorted(set(row["files"]) & {str(item) for item in old_files})
    symlinked = "some of its files are symlinks, and git diffs the link, not the code it points to"
    if any((root / relative).is_symlink() for relative in kept):
        return full(symlinked)
    changed: list[str] = []
    reviewed: dict[str, tuple[str, str]] = {}
    if kept:
        listing = _git_on_paths(root, "ls-files", "-z", paths=kept)
        tracked = set(filter(None, listing.stdout.split("\0")))
        if listing.returncode != 0:
            return full("git could not list the tracked files")
        if tracked != set(kept):
            return full("some of its files are not tracked by git, so a diff would miss them")
        # Which files changed, and what is shown, come from raw bytes: the stored blob against
        # the file on disk, the same bytes the checksum hashes. git diff is never used, since
        # filters, drivers and settings can change what it shows.
        stored_blobs = _stored_blobs(root, commit, kept)
        if stored_blobs is None:
            return full("git could not read the reviewed commit")
        hashes = _raw_blob_ids(root, kept)
        reviewed = stored_blobs
        if any(mode == "120000" for mode, _ in reviewed.values()):
            return full(symlinked)
        changed = [
            relative
            for relative, blob in zip(kept, hashes, strict=True)
            if reviewed.get(relative, ("", ""))[1] != blob
        ]
    parts: list[str] = []
    for relative in changed:
        stored = reviewed.get(relative)
        try:
            with _open_regular_file(root / relative) as handle:
                data = handle.read()
        except OSError:
            return full(f"{relative} could not be read")
        part, why = _raw_diff(root, relative, stored[1] if stored else None, data)
        if part is None:
            return full(why)
        parts.append(part)
    text = "".join(parts)
    lines = text.split("\n")
    if lines and not lines[-1]:
        lines.pop()
    result = {
        "mode": "diff",
        "since": commit,
        "commands_removed": sorted(set(map(str, old_commands)) - set(commands)),
        "commands_added": sorted(set(commands) - set(map(str, old_commands))),
        "files_added": sorted(set(row["files"]) - {str(item) for item in old_files}),
        "files_removed": sorted({str(item) for item in old_files} - set(row["files"])),
        "files_changed": changed,
        "shared_added": sorted(set(row["shared"]) - {str(item) for item in old_shared}),
        "shared_removed": sorted({str(item) for item in old_shared} - set(row["shared"])),
        "params_changed": _param_changes(old_params, row["params"]),
        "diff": "\n".join(lines[:REVIEW_DIFF_LINE_LIMIT]),
        "truncated": len(lines) > REVIEW_DIFF_LINE_LIMIT,
    }
    if not (
        text.strip()
        or any(
            result[key]
            for key in (
                "commands_removed",
                "commands_added",
                "files_added",
                "files_removed",
                "shared_added",
                "shared_removed",
                "params_changed",
            )
        )
    ):
        return full("its code changed in a way git does not show, such as a file mode")
    return result


def _code_fix(row: dict[str, Any]) -> str | None:
    """The next step that clears a unit's status, or None when nothing is needed."""
    status = row["status"]
    if status in {"unreviewed", "changed-since-review", "revoked"}:
        if row.get("uncommitted"):
            return "Commit these files, then sign off: " + ", ".join(row["uncommitted"][:5])
        return "Read the code shown, then sign off"
    if status == "invalid-record":
        return f"Delete {row['record']}, then review again"
    if status == "unknown":
        return "Fix the cause shown, then rerun this notebook"
    return None


def _code_review(root: Path, config: dict[str, Any]) -> tuple[list[dict[str, Any]], str | None]:
    """One row per step or shared file. Status is recomputed every time from the code as it is."""
    units, problem = _review_units(root, config)
    rows: list[dict[str, Any]] = []
    for name, unit in units.items():
        record, valid = _load_review(root, name)
        revoked = record if record and record.get("revoked") else None
        signed = None if revoked else record
        row: dict[str, Any] = {
            key: unit[key]
            for key in ("unit", "kind", "items", "files", "shared", "commands", "params")
        } | {
            "upstream": sorted(unit["upstream"]),
            "downstream": sorted(unit["downstream"]),
            "used_by": unit["used_by"],
            "depth": unit.get("depth", 0),
            "declared_in": sorted(unit["declared_in"]),
            "review": signed,
            "revoked": revoked,
            "checksum": None,
            "record": _review_record_path(root, name).relative_to(root).as_posix(),
        }
        try:
            if unit["unknown"]:
                raise OSError(unit["unknown"])
            checksum = _code_checksum(
                root, unit["files"], unit["commands"], unit["params"], unit["shared"]
            )
            row["checksum"] = checksum
            if not valid:
                row["status"] = "invalid-record"
            elif revoked:
                row["status"] = "revoked"
            elif signed is None:
                row["status"] = "unreviewed"
            elif signed["code_checksum"] == checksum:
                row["status"] = "reviewed"
            else:
                row["status"] = "changed-since-review"
            if row["status"] in {"unreviewed", "changed-since-review", "revoked"}:
                uncommitted = _uncommitted(root, [*unit["files"], *sorted(unit["declared_in"])])
                row["since_review"] = _since_review(root, row, unit["commands"])
                row["uncommitted"] = uncommitted
        except (OSError, ValueError) as error:
            row |= {"status": "unknown", "checksum": None, "why": str(error)}
        row["fix"] = _code_fix(row)
        rows.append(row)
    return rows, problem


def _last_review(root: Path, rows: list[dict[str, Any]]) -> dict[str, Any] | None:
    """The newest sign-off on record and how far the branch has moved since, when git can tell."""
    records = [row["review"] for row in rows if isinstance(row["review"], dict)]
    if not records:
        return None
    newest = max(records, key=lambda record: str(record["reviewed_at"]))
    commit = str(newest["commit"])
    summary: dict[str, Any] = {
        "reviewer": newest["reviewer"],
        "reviewed_at": newest["reviewed_at"],
        "commit": commit,
        "commits_since": None,
        "files_changed": None,
    }
    if _git(root, "merge-base", "--is-ancestor", commit, "HEAD") is not None:
        count = _git(root, "rev-list", "--count", f"{commit}..HEAD")
        changed = _git(root, "diff", "--name-only", "-z", commit)
        summary["commits_since"] = int(count) if count and count.isdigit() else None
        if changed is not None:
            summary["files_changed"] = len(list(filter(None, changed.split("\0"))))
    return summary


def review_status(root: Path) -> dict[str, Any]:
    """What the review notebook shows: each step and shared file, and whether a person signed it.

    Only the person's work. Output labels (`outputs`) and audit findings (`audit`) are the
    agent's, so they are not repeated here.
    """
    previous = _READ_ONLY["on"]
    _READ_ONLY["on"] = True  # Viewing never writes: no markers, no DVC cache configuration.
    rows: list[dict[str, Any]]
    problem: str | None
    try:
        try:
            _check_review_config_file(root)
            config = _project_config(root)
        except (OSError, ValueError) as error:
            rows, problem = [], f"Could not read .astack/project.toml: {error}"
        else:
            rows, problem = _code_review(root, config)
        return {
            "header": _header(root),
            "to_sign_off": sum(row["status"] != "reviewed" for row in rows) + bool(problem),
            "last_review": _last_review(root, rows),
            "units": rows,
            "problem": problem,
        }
    finally:
        _READ_ONLY["on"] = previous


def _check_review_config_file(root: Path) -> None:
    try:
        _require_regular_file(root / ".astack/project.toml")
    except FileNotFoundError:
        pass  # The project policy supports a missing configuration.


def _review_output_status(root: Path) -> dict[str, Any]:
    try:
        _check_review_config_file(root)
        return output_status(root)
    except (OSError, RuntimeError, ValueError) as error:
        return {"status": "unknown", "problem": str(error), "outputs": []}


def review_labels(root: Path) -> dict[str, str]:
    """Each output's current label, read without writing anything."""
    previous = _READ_ONLY["on"]
    _READ_ONLY["on"] = True
    try:
        outputs = _review_output_status(root).get("outputs", [])
    finally:
        _READ_ONLY["on"] = previous
    return {str(item.get("path")): str(item.get("label")) for item in outputs}


def review_display_status(row: dict[str, Any]) -> str:
    """The status a person sees. Code that must be committed first says so."""
    if row["status"] != "reviewed" and row.get("uncommitted"):
        return "commit first"
    return REVIEW_STATUS_LABELS[row["status"]]


def review_label(row: dict[str, Any]) -> str:
    """A unit's short name: a group shows its item count, shared code its file name."""
    if row["kind"] == "shared":
        return str(row["unit"]).rsplit("/", 1)[-1]
    count = len(row["items"])
    return f"{row['unit']} × {count}" if count > 1 else str(row["unit"])


def review_item(row: dict[str, Any]) -> str:
    """A unit's name in the overview table: shared code shows its whole path."""
    return str(row["unit"])[7:] if row["kind"] == "shared" else review_label(row)


def _purpose(root: Path, row: dict[str, Any]) -> str | None:
    """A unit's one-line purpose: the docstring of the script its command runs."""
    import ast

    commands = " ".join(str(item.get("command")) for item in row["items"])
    named = [item for item in row["files"] if item in commands]
    for relative in [*named, *row["files"]]:
        if not relative.endswith(".py"):
            continue
        try:
            with _open_regular_file(root / relative) as handle:
                doc = ast.get_docstring(ast.parse(handle.read()))
        except (OSError, SyntaxError, ValueError):
            continue
        if doc and doc.strip():
            return doc.strip().splitlines()[0]
    return None


def review_overview(
    root: Path,
    status: dict[str, Any],
    labels: dict[str, str],
    *,
    opened: frozenset[str] = frozenset(),
    only_pending: bool = True,
) -> list[dict[str, str]]:
    """The overview table: one row per unit, most of it answerable without opening anything."""
    rows: list[dict[str, str]] = []
    for row in status["units"]:
        if only_pending and row["status"] == "reviewed":
            continue
        since = row.get("since_review") or {}
        if row["status"] == "reviewed":
            changed = "none"
        elif since.get("mode") == "diff":
            # A parameter changed for all six items of a group is one change.
            counts_by_kind = {
                "changed file": len(since["files_changed"]),
                "new file": len(since["files_added"]),
                "parameter": len({change["key"] for change in since["params_changed"]}),
                "run setting": len(_run_changes(since)),
                "removed file": len(since["files_removed"]),
                "shared code change": len(since["shared_added"]) + len(since["shared_removed"]),
            }
            parts = [
                f"{count} {name}{'' if count == 1 else 's'}"
                for name, count in counts_by_kind.items()
                if count
            ]
            changed = ", ".join(parts) or "see page"
        else:
            changed = str(since.get("why") or row.get("why") or "")
        counts: dict[str, int] = {}
        for item in row["items"]:
            for path in item["outputs"]:
                label = labels.get(path, "unknown")
                counts[label] = counts.get(label, 0) + 1
        rows.append(
            {
                "item": str(row["unit"]),
                "status": review_display_status(row),
                "changed since sign-off": changed,
                "outputs": ", ".join(f"{n} {name}" for name, n in sorted(counts.items())) or "-",
                "opened": "yes" if row["unit"] in opened else "no",
                "purpose": _purpose(root, row) or "",
            }
        )
    return rows


def review_literal_label(text: str) -> str:
    """A `mo.ui.button` label that shows `text` exactly, since marimo renders labels as Markdown."""
    return "".join(char if char.isalnum() else f"&#{ord(char)};" for char in text)


def review_item_links(
    mo: Any, status: dict[str, Any], rows: list[dict[str, str]], set_page: Any
) -> Any:
    """One button per row, keyed by unit id. The notebook holds this as a named dictionary."""
    names = {str(row["unit"]): review_item(row) for row in status["units"]}
    return mo.ui.dictionary(
        {
            row["item"]: mo.ui.button(
                label=review_literal_label(names[row["item"]]),
                on_click=lambda _, unit=row["item"]: set_page(f"unit:{unit}"),
            )
            for row in rows
        }
    )


def review_link_buttons(mo: Any, units: list[str], set_page: Any, prefix: str = "") -> Any:
    """Buttons that open units, each showing its name literally, in one named dictionary."""
    return mo.ui.dictionary(
        {
            unit: mo.ui.button(
                label=review_literal_label(f"{prefix}{review_link_label(unit)}"),
                on_click=lambda _, name=unit: set_page(f"unit:{name}"),
            )
            for unit in dict.fromkeys(units)
        }
    )


def review_items_table(mo: Any, rows: list[dict[str, str]], links: Any) -> Any:
    """The Items table. Cells hold plain unit ids for search, sort and bulk. Buttons are display."""
    formats = {"item": lambda unit: links[unit]} if rows else None
    return mo.ui.table(rows, selection="multi", format_mapping=formats)


def review_empty_items(status: dict[str, Any]) -> tuple[str, str]:
    """Why the Items table has no rows. Only real sign-offs may read as done."""
    if status["problem"]:
        return "warn", "Steps could not be read. Fix the problem shown above."
    if not status["units"]:
        return "info", "This project has no steps to review yet."
    return "success", "All done. Every step and shared file is signed off."


def review_overview_view(
    mo: Any,
    status: dict[str, Any],
    rows: list[dict[str, str]],
    pipeline_map: Any,
    only_pending: Any,
    picker: Any,
) -> Any:
    """The overview's map and Items table, or a clear message when no row needs showing."""
    if rows:
        hint = "Click an item's name to open it. Tick boxes only to sign off several at once."
        table = mo.vstack([mo.md(hint), picker])
    else:
        kind, text = review_empty_items(status)
        table = mo.callout(mo.plain_text(text), kind=kind)
    return mo.vstack(
        [
            mo.md("Click a box to open it. Hover to see what feeds it and what it feeds."),
            pipeline_map,
            mo.hstack([mo.md("**Items**"), only_pending], justify="space-between"),
            table,
        ]
    )


def review_link_label(unit: str) -> str:
    """A page link's label. Shared code shows its whole path, so that path is on the page."""
    return unit[7:] if unit.startswith("shared:") else unit.rsplit("/", 1)[-1]


def review_map(status: dict[str, Any]) -> dict[str, Any]:
    """The pipeline map: steps by depth, left to right, with shared code in a strip on top."""
    nodes: list[dict[str, Any]] = []
    edges: list[dict[str, str]] = []
    filled: dict[int, int] = {}
    strip = 0
    for row in status["units"]:
        shown = review_display_status(row)
        if row["kind"] == "shared":
            count = len(row["used_by"])
            nodes.append(
                {
                    "id": row["unit"],
                    "label": review_label(row),
                    "status": shown,
                    "x": strip,
                    "y": -1,
                    "shape": "pill",
                    "sub": f"{count} steps",
                }
            )
            strip += 1
            continue
        column = int(row["depth"])
        filled[column] = filled.get(column, -1) + 1
        nodes.append(
            {
                "id": row["unit"],
                "label": review_label(row),
                "status": shown,
                "x": column,
                "y": filled[column],
                "shape": "box",
                "sub": "",
            }
        )
        edges.extend({"from": parent, "to": row["unit"]} for parent in row["upstream"])
    return {"nodes": nodes, "edges": edges, "colors": REVIEW_STATUS_COLORS}


def review_bulk_plan(
    status: dict[str, Any], picked: list[dict[str, Any]], opened: dict[str, str]
) -> tuple[list[tuple[str, str]], list[str]]:
    """What a bulk sign-off may cover: only items opened, at the code seen when opened."""
    rows = {str(row["unit"]): row for row in status["units"]}
    allowed: list[tuple[str, str]] = []
    skipped: list[str] = []
    for choice in picked:
        row = rows[str(choice["item"])]
        if row["status"] == "reviewed":
            continue
        if row["unit"] in opened:
            allowed.append((str(row["unit"]), opened[row["unit"]]))
        else:
            skipped.append(f"{review_item(row)} (open it first)")
    return allowed, skipped


def next_to_sign_off(status: dict[str, Any], after: str | None = None) -> str | None:
    """The next unit needing a sign-off after this one, wrapping around, in pipeline order."""
    order = [str(row["unit"]) for row in status["units"]]
    pending = {str(row["unit"]) for row in status["units"] if row["status"] != "reviewed"}
    start = order.index(after) + 1 if after in order else 0
    for unit in order[start:] + order[:start]:
        if unit in pending and unit != after:
            return unit
    return None


def _key_template(text: str, key: str | None) -> str:
    """Mask an item's key where it stands alone, so key `n` never rewrites `clean.py`."""
    if not key:
        return text
    return re.sub(rf"(?<![A-Za-z0-9]){re.escape(key)}(?![A-Za-z0-9])", "${key}", text)


def _difference_flag(
    values: dict[str, str], before: set[str]
) -> tuple[str | None, dict[str, str], bool]:
    """The flag these differing tokens sit under, their values, and whether `=` joins them."""
    joined = [re.fullmatch(r"(--?[A-Za-z][\w-]*)=(.+)", value) for value in values.values()]
    if all(joined) and len({match.group(1) for match in joined if match}) == 1:
        flag = next(match.group(1) for match in joined if match)
        return flag, {key: value.partition("=")[2] for key, value in values.items()}, True
    if any(re.match(r"--?[A-Za-z]", value) for value in values.values()) or len(before) != 1:
        return None, values, False
    previous = next(iter(before))
    return (previous if re.fullmatch(r"--?[A-Za-z][\w-]*", previous) else None), values, False


def _shell_arguments(text: str) -> tuple[list[str], tuple[str, ...]]:
    """Each argument exactly as written, and the exact text between arguments.

    Together they rebuild `text`, so two commands that match on both are the same command.
    Unbalanced quotes raise ValueError.
    """
    import io
    import shlex

    shlex.split(text)  # Refuses unbalanced quotes and a dangling escape.
    # With a final separator, the lexer always reads exactly one character past an argument.
    stream = io.StringIO(f"{text} ")
    lexer = shlex.shlex(stream, posix=True)
    lexer.whitespace_split = True
    lexer.commenters = ""
    arguments: list[str] = []
    gaps: list[str] = []
    start = previous_end = 0
    for _ in lexer:
        end = stream.tell()
        stop = end - 1
        raw = text[start:stop]
        first = start + len(raw) - len(raw.lstrip(lexer.whitespace))
        gaps.append(text[previous_end:first])
        arguments.append(text[first:stop])
        previous_end = stop
        start = end
    gaps.append(text[previous_end:])
    return arguments, tuple(gaps)


def _difference_parts(items: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """How a group's items differ beyond their own key, so an odd one out cannot hide.

    Compared on what actually runs: each item's resolved command with its key masked. A value
    set on an item that its command, inputs or outputs never use has no effect. A value is named
    by its flag only when every item clearly has that flag. Otherwise it is named by position.
    Commands that differ in a way the arguments cannot show still get a warning.
    """
    if len(items) < 2:
        return []
    masked = {str(item["key"]): _key_template(str(item["command"]), item["key"]) for item in items}
    if len(set(masked.values())) < 2:
        return []
    unclear = [{"plain": "Items run different commands: compare them in the table below."}]
    try:
        parsed = {key: _shell_arguments(text) for key, text in masked.items()}
    except ValueError:
        return unclear
    shapes = {key: arguments for key, (arguments, _) in parsed.items()}
    lengths = {len(tokens) for tokens in shapes.values()}
    if len(lengths) > 1:
        return unclear
    parts: list[dict[str, Any]] = []
    for position in range(lengths.pop()):
        values = {key: tokens[position] for key, tokens in shapes.items()}
        if len(set(values.values())) < 2:
            continue
        before = {tokens[position - 1] for tokens in shapes.values()} if position else set()
        flag, values, joined = _difference_flag(values, before)
        distinct = sorted(set(values.values()))
        common = max(distinct, key=lambda value: list(values.values()).count(value))
        parts.append(
            {
                "flag": flag,
                "joined": joined,
                "position": position + 1,
                "common": common,
                "odd": [(key, value) for key, value in values.items() if value != common],
            }
        )
    # Arguments are compared as written, quotes included, so every difference in them is named.
    # Only the text between them can still differ, and a newline there starts a new command.
    return parts + unclear if len({gaps for _, gaps in parsed.values()}) > 1 else parts


def _difference_note(part: dict[str, Any], code: Any, plain: Any = str) -> str:
    """One difference as a sentence, with values marked by `code` and other text by `plain`."""
    if "plain" in part:
        return str(plain(part["plain"]))
    if part["flag"] and part["joined"]:
        subject = code(part["flag"])
    elif part["flag"]:
        # A space does not prove the value belongs to the flag, which may take no value.
        subject = f"{plain('Value after ')}{code(part['flag'])}"
    else:
        subject = plain(f"Argument {part['position']}")
    odd = ", ".join(f"{plain(key)} ({code(value)})" for key, value in part["odd"])
    return f"{subject} is {code(part['common'])}, except {odd}"


def _item_differences(items: list[dict[str, Any]]) -> list[str]:
    """Each difference as plain text."""
    return [_difference_note(part, lambda value: f"`{value}`") for part in _difference_parts(items)]


def _difference_html(items: list[dict[str, Any]]) -> list[str]:
    """Each difference as escaped HTML, with its flag and values set as code."""
    import html

    return [
        _difference_note(
            part,
            lambda value: f'<code style="white-space:pre-wrap">{html.escape(value)}</code>',
            html.escape,
        )
        for part in _difference_parts(items)
    ]


def _input_rows(row: dict[str, Any], owners: dict[str, str]) -> list[dict[str, str]]:
    """Data inputs, written once. A group's per-item paths collapse to their `${key}` template."""
    seen: dict[str, str] = {}
    for item in row["items"]:
        for path in item["inputs"]:
            shown = _key_template(path, item["key"])
            source = owners.get(path)
            seen.setdefault(shown, f"step {source}" if source else "source data")
    return [{"input": path, "from": source} for path, source in seen.items()]


def _param_rows(row: dict[str, Any], since: dict[str, Any]) -> list[dict[str, str]]:
    """Parameters and what changed. Items agreeing on both share a row, others get their own."""
    changes = {(c["stage"], c["key"]): c for c in since.get("params_changed") or []}

    def note(stage: str, key: str) -> str:
        change = changes.get((stage, key))
        if change is None:
            return "unchanged" if row["review"] else ""
        if change["added"]:
            return "new"
        return f"changed, was {json.dumps(change['was'], default=str)}"

    rows: list[dict[str, str]] = []
    for key in sorted({key for values in row["params"].values() for key in values}):
        shown = {
            stage: (json.dumps(values[key], sort_keys=True, default=str), note(stage, key))
            for stage, values in row["params"].items()
            if key in values
        }
        # One row only when every item declares it and agrees, so its scope is never implied.
        if len(shown) == len(row["params"]) and len(set(shown.values())) == 1:
            value, change = next(iter(shown.values()))
            rows.append({"parameter": key, "value": value, "since sign-off": change})
            continue
        rows.extend(
            {"parameter": f"{key} ({stage})", "value": value, "since sign-off": change}
            for stage, (value, change) in shown.items()
        )
    for (stage, key), change in sorted(changes.items()):
        if change["removed"]:
            was = json.dumps(change["was"], default=str)
            rows.append(
                {
                    "parameter": f"{key} ({stage})",
                    "value": "-",
                    "since sign-off": f"removed, was {was}",
                }
            )
    return rows


def _run_changes(since: dict[str, Any]) -> list[dict[str, str]]:
    """What changed in how each stage runs: its command, folder, data inputs or outputs."""

    def parse(entries: list[str]) -> dict[str, list[Any]]:
        parsed = [json.loads(entry) for entry in entries]
        return {str(entry[0]): entry[1:] for entry in parsed}

    before = parse(since.get("commands_removed") or [])
    after = parse(since.get("commands_added") or [])
    fields = ("command", "folder", "inputs", "outputs", "code", "frozen", "settings")
    rows: list[dict[str, str]] = []
    for stage in sorted(set(before) | set(after)):
        if stage not in before or stage not in after:
            entry = after.get(stage) or before[stage]
            text = "; ".join(f"{name}: {value}" for name, value in zip(fields, entry, strict=False))
            added = stage in after
            rows.append(
                {
                    "item": stage,
                    "what": "new item" if added else "removed item",
                    "was": "" if added else text,
                    "now": text if added else "",
                }
            )
            continue
        for field, old, new in zip(fields, before[stage], after[stage], strict=False):
            if old != new:
                rows.append({"item": stage, "what": field, "was": str(old), "now": str(new)})
    return rows


def _shown_text(data: bytes) -> str | None:
    """A file as text where no two different files look alike, or None when it is not UTF-8.

    Anything that could be mistaken for a marker, and anything invisible, shows as its code
    point first. So every `⇥` on screen is a real tab and every `⟦` starts an escape.
    """
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        return None
    reserved = "\u240d\u21e5\u2423\u27e6\u27e7"
    escaped = "".join(
        f"\u27e6U+{ord(char):04X}\u27e7"
        if char in reserved or not (char.isprintable() or char in "\n\t\r")
        else char
        for char in text
    )
    return _visible(escaped)


def _diff_rows(diff: str) -> list[dict[str, Any]]:
    """A single-file unified diff as rows. Its first two lines are the file header."""
    rows: list[dict[str, Any]] = []
    number = 0
    for line in diff.split("\n")[2:]:
        if line.startswith("@@"):
            found = re.search(r"\+(\d+)", line)
            number = int(found.group(1)) - 1 if found else number
            rows.append({"kind": "gap", "line": None, "text": f"line {number + 1}"})
        elif line.startswith("\\"):
            rows.append({"kind": "note", "line": None, "text": line[2:]})
        elif line.startswith("-"):
            rows.append({"kind": "del", "line": None, "text": line[1:]})
        elif line.startswith("+"):
            number += 1
            rows.append({"kind": "add", "line": number, "text": line[1:]})
        elif line.startswith(" "):
            number += 1
            rows.append({"kind": "same", "line": number, "text": line[1:]})
    return rows


def _code_view(
    root: Path, relative: str, since: dict[str, Any], data: bytes | None
) -> dict[str, Any]:
    """One file to read: its changes in context when a diff is trustworthy, and always in full."""
    view: dict[str, Any] = {"path": relative, "state": "unchanged", "changes": None, "note": ""}
    text = _shown_text(data) if data is not None else None
    if data is None or text is None:
        return view | {"state": "unreadable", "full": [], "truncated": False}
    lines = text.split("\n")
    if lines and not lines[-1]:
        lines.pop()
    view["full"] = [
        {"kind": "same", "line": number, "text": line}
        for number, line in enumerate(lines[:REVIEW_DIFF_LINE_LIMIT], 1)
    ]
    view["truncated"] = len(lines) > REVIEW_DIFF_LINE_LIMIT
    if text and not text.endswith("\n") and not view["truncated"]:
        view["full"].append({"kind": "note", "line": None, "text": "No newline at end of file"})
    if since.get("mode") == "full":
        return view | {"state": "read in full", "note": str(since["why"])}
    if since.get("mode") != "diff":
        return view
    if relative in since["files_added"]:
        return view | {"state": "new"}
    if relative not in since["files_changed"]:
        return view
    try:
        stored = _stored_blobs(root, str(since["since"]), [relative])
    except OSError:
        stored = None
    if stored is None:
        return view | {"state": "read in full", "note": "Git could not read the reviewed file"}
    blob = stored.get(relative, ("", None))[1]
    near, why = _raw_diff(root, relative, blob, data, context=5)
    whole, _ = _raw_diff(root, relative, blob, data, context=1_000_000)
    if near is None or whole is None:
        return view | {"state": "read in full", "note": why}
    changes, full = _diff_rows(near), _diff_rows(whole)
    return view | {
        "state": "changed",
        "changes": changes[:REVIEW_DIFF_LINE_LIMIT],
        "full": full[:REVIEW_DIFF_LINE_LIMIT],
        "truncated": max(len(changes), len(full)) > REVIEW_DIFF_LINE_LIMIT,
    }


def review_code_html(rows: list[dict[str, Any]]) -> str:
    """Code rows as an HTML table. All file content is escaped, so it can only ever be text."""
    import html

    marks = {"add": "+", "del": "−"}
    cells = [
        f'<tr class="{row["kind"]}"><td>{row["line"] or ""}</td>'
        f"<td>{marks.get(row['kind'], '')}</td><td>{html.escape(row['text']) or ' '}</td></tr>"
        for row in rows
    ]
    style = (
        "<style>table.astack-code{border-collapse:collapse;width:100%;font-size:12px;"
        "font-family:ui-monospace,monospace}table.astack-code td{padding:0 8px;white-space:pre}"
        "table.astack-code td:nth-child(-n+2){opacity:.55;width:1%;text-align:right}"
        "table.astack-code tr.add{background:rgba(46,160,67,.18)}"
        "table.astack-code tr.del{background:rgba(248,81,73,.18)}"
        "table.astack-code tr.gap td,table.astack-code tr.note td{opacity:.55;font-style:italic}"
        "</style>"
    )
    return (
        f'{style}<div style="overflow:auto;max-height:520px"><table class="astack-code">'
        f"{''.join(cells)}</table></div>"
    )


def _param_usage(
    root: Path, row: dict[str, Any], since: dict[str, Any], rendered: dict[str, bytes]
) -> list[dict[str, Any]]:
    """For each changed parameter, the lines of this step's code that name it."""
    found: list[dict[str, Any]] = []
    for key in sorted({change["key"] for change in since.get("params_changed") or []}):
        name = key.rsplit(":", 1)[-1].rsplit(".", 1)[-1]
        pattern = re.compile(rf"\b{re.escape(name)}\b")
        lines: list[dict[str, Any]] = []
        for relative in [*row["files"], *row["shared"]]:
            try:
                data = rendered.get(relative)
                if relative in row["shared"]:
                    with _open_regular_file(root / relative) as handle:
                        data = handle.read()
            except OSError:
                continue
            text = _shown_text(data) if data is not None else None
            for number, line in enumerate((text or "").split("\n"), 1):
                if pattern.search(line):
                    lines.append({"path": relative, "line": number, "text": line})
        found.append({"key": key, "lines": lines})
    return found


def _review_notes(row: dict[str, Any], by_unit: dict[str, dict[str, Any]]) -> list[str]:
    """Non-blocking context: upstream steps or shared code this step relies on have moved."""
    seen: set[str] = set()
    stack = list(row["upstream"])
    while stack:
        name = stack.pop()
        if name not in seen and name in by_unit:
            seen.add(name)
            stack.extend(by_unit[name]["upstream"])
    notes = [
        f"Upstream step {name} is {review_display_status(by_unit[name])}."
        for name in sorted(seen)
        if by_unit[name]["status"] != "reviewed"
    ]
    for relative in row["shared"]:
        shared = by_unit.get(f"shared:{relative}")
        if shared and shared["status"] != "reviewed":
            notes.append(f"Shared {relative} is {review_display_status(shared)}.")
    return notes


def review_page(
    root: Path, unit: str, status: dict[str, Any], labels: dict[str, str]
) -> dict[str, Any]:
    """Everything one step's or shared file's page shows, ready to display."""
    by_unit = {str(row["unit"]): row for row in status["units"]}
    row = by_unit[unit]
    owners = {
        path: str(other["unit"])
        for other in status["units"]
        for item in other["items"]
        for path in item["outputs"]
    }
    since = row.get("since_review") or {}
    rendered: dict[str, bytes] = {}
    for relative in row["files"]:
        try:
            with _open_regular_file(root / relative) as handle:
                rendered[relative] = handle.read()
        except OSError:
            continue
    # Commands, parameters and settings come from the same row that produced the checksum.
    # Code is read when this page opens. Verify the exact bytes used for both views of each file.
    checksum = row["checksum"]
    stale = checksum is not None and (
        len(rendered) != len(row["files"])
        or checksum
        != _code_checksum(
            root, row["files"], row["commands"], row["params"], row["shared"], rendered=rendered
        )
    )
    items = [
        {
            "item": str(item["key"]),
            "command": str(item["command"]),
            "folder": str(item["wdir"]),
            "frozen": "yes" if item["frozen"] else "no",
            "code": ", ".join(item["code"]),
            "inputs": ", ".join(item["inputs"]),
            "outputs": ", ".join(
                f"{path} ({labels.get(path, 'unknown')})" for path in item["outputs"]
            ),
        }
        for item in row["items"]
        if item["key"] is not None
    ]
    return {
        "unit": unit,
        "kind": row["kind"],
        "title": review_label(row),
        "purpose": _purpose(root, row),
        "status": review_display_status(row),
        "checksum": None if stale else checksum,
        "blocked": stale or bool(row.get("uncommitted")) or checksum is None,
        "stale": stale,
        "why": "The code shown no longer matches the loaded review status."
        if stale
        else row.get("why"),
        "fix": "Refresh and review the page again" if stale else row["fix"],
        "review": row["review"],
        "revoked": row["revoked"],
        "since": since,
        "upstream": row["upstream"],
        "downstream": row["downstream"],
        "used_by": row["used_by"],
        "shared": [
            {
                "unit": f"shared:{path}",
                "path": path,
                "status": review_display_status(by_unit[f"shared:{path}"]),
            }
            for path in row["shared"]
            if f"shared:{path}" in by_unit
        ],
        "notes": _review_notes(row, by_unit),
        "inputs": _input_rows(row, owners),
        "params": _param_rows(row, since),
        "param_usage": _param_usage(root, row, since, rendered),
        "items": items,
        "differences": _item_differences(row["items"]),
        "difference_html": _difference_html(row["items"]),
        "commands": sorted(
            {
                ("[frozen, DVC will not rerun it] " if i["frozen"] else "")
                + ("" if i["wdir"] == "." else f"[in {i['wdir']}] ")
                + _key_template(str(i["command"]), i["key"])
                for i in row["items"]
            }
        ),
        "run_changes": _run_changes(since),
        "settings": [
            {
                "item": str(item["name"]),
                "setting": name,
                "value": json.dumps(value, sort_keys=True, default=str),
            }
            for item in row["items"]
            for name, value in sorted(item["settings"].items())
        ],
        "code_moves": [
            {"file": path, "change": label}
            for key, label in (
                ("files_removed", "no longer part of this step"),
                ("shared_added", "now shared code"),
                ("shared_removed", "no longer shared code"),
            )
            for path in since.get(key) or []
        ],
        "declared_code": [
            {"declared code": path}
            for path in dict.fromkeys(
                _key_template(path, item["key"]) for item in row["items"] for path in item["code"]
            )
        ],
        "code": [
            _code_view(root, relative, since, rendered.get(relative)) for relative in row["files"]
        ],
        "outputs": [
            {
                "item": str(item["key"]) if item["key"] is not None else None,
                "path": path,
                "label": labels.get(path, "unknown"),
            }
            for item in row["items"]
            for path in item["outputs"]
        ],
    }


def review_heading_html(inner: str, level: int) -> str:
    """A heading from text that is already escaped, sized so levels read apart in any theme."""
    return f'<h{level} style="{REVIEW_HEADING_STYLES[level]}">{inner}</h{level}>'


def review_file_title(path: str, state: str, level: int = 4) -> str:
    """A file's name and state, kept on one line that scrolls instead of wrapping."""
    import html

    pair = f"<code>{html.escape(path)}</code> · {html.escape(state)}"
    inner = f'<span style="display:block;overflow-x:auto;white-space:nowrap">{pair}</span>'
    return review_heading_html(inner, level)


def review_table_html(rows: list[dict[str, Any]]) -> str:
    """Facts as a compact static table. Every heading and value is escaped."""
    import html

    columns = list(dict.fromkeys(key for row in rows for key in row))
    head = "".join(f"<th>{html.escape(str(name))}</th>" for name in columns)

    def cell(value: Any) -> str:
        return f"<td>{'' if value is None else html.escape(str(value))}</td>"

    body = "".join(f"<tr>{''.join(cell(row.get(name)) for name in columns)}</tr>" for row in rows)
    style = (
        "<style>table.astack-facts{border-collapse:collapse;width:100%;font-size:13px}"
        "table.astack-facts th,table.astack-facts td{padding:2px 8px;text-align:left;"
        "vertical-align:top;white-space:pre-wrap;overflow-wrap:anywhere;"
        "border-bottom:1px solid var(--border,#d4d4d8)}"
        "table.astack-facts th{font-weight:600}</style>"
    )
    return (
        f'{style}<div style="overflow:auto;max-height:320px"><table class="astack-facts">'
        f"<thead><tr>{head}</tr></thead><tbody>{body}</tbody></table></div>"
    )


def review_facts_html(page: dict[str, Any]) -> str:
    """Inputs, parameters and command, side by side when there is room. All text is escaped."""
    import html

    cells = [
        review_heading_html(title, 4) + review_table_html(rows)
        for title, rows in (("Inputs", page["inputs"]), ("Parameters", page["params"]))
        if rows
    ]
    if page["commands"]:
        command = html.escape("\n".join(page["commands"]))
        cells.append(
            review_heading_html("Command", 4) + '<pre style="margin:0;font-size:13px;'
            f'white-space:pre-wrap;overflow-wrap:anywhere">{command}</pre>'
        )
    if not cells:
        return ""
    inner = "".join(f'<div style="min-width:0">{cell}</div>' for cell in cells)
    return (
        '<div style="display:grid;gap:.1rem 1.25rem;'
        f'grid-template-columns:repeat(auto-fit,minmax(min(100%,20rem),1fr))">{inner}</div>'
    )


def _heading(text: str, level: int = 3) -> dict[str, Any]:
    import html

    return {"type": "html", "html": review_heading_html(html.escape(text), level)}


def _declared_code_on_page(page: dict[str, Any]) -> bool:
    """Whether every declared code path already appears by its exact name on this page."""
    shown = {view["path"] for view in page["code"]} | {item["path"] for item in page["shared"]}
    return all(row["declared code"] in shown for row in page["declared_code"])


def _file_sections(view: dict[str, Any]) -> list[dict[str, Any]]:
    title = review_file_title(view["path"], view["state"])
    sections: list[dict[str, Any]] = [{"type": "html", "html": title}]
    if view["state"] == "unreadable":
        text = "Not UTF-8 text. Open it in your editor to read it."
        return [*sections, {"type": "callout", "kind": "warn", "text": text}]
    if view["note"]:
        text = f"Read in full: {view['note']}"
        sections.append({"type": "callout", "kind": "info", "text": text})
    if view["changes"] is not None:
        sections.append({"type": "html", "html": review_code_html(view["changes"])})
        sections.append(
            {"type": "fold", "title": "Full file", "html": review_code_html(view["full"])}
        )
    else:
        sections.append({"type": "html", "html": review_code_html(view["full"])})
    if view["truncated"]:
        text = "Cut short. Open the file and read the rest before signing off."
        sections.append({"type": "callout", "kind": "warn", "text": text})
    return sections


def review_sections(page: dict[str, Any]) -> list[dict[str, Any]]:
    """A page's content, top to bottom, as simple typed blocks the notebook only has to draw."""
    sections: list[dict[str, Any]] = []

    def note(kind: str, text: str) -> None:
        sections.append({"type": "callout", "kind": kind, "text": text})

    if page["why"]:
        note("danger", str(page["why"]))
    if page["fix"]:
        sections.append({"type": "text", "text": f"Next: {page['fix']}"})
    if page["kind"] == "shared":
        sections.append({"type": "links", "title": "Used by", "units": page["used_by"]})
    else:
        link_groups = [
            {"title": "Upstream", "units": page["upstream"]},
            {"title": "Downstream", "units": page["downstream"]},
        ]
        sections.append({"type": "link_row", "groups": link_groups})
    if page["notes"]:
        note("info", "Check its assumptions still hold:\n" + "\n".join(page["notes"]))
    for title, rows in (
        ("How it runs changed", page["run_changes"]),
        ("Code that moved", page["code_moves"]),
    ):
        if rows:
            sections.append(_heading(title))
            sections.append({"type": "table", "rows": rows})
    facts = review_facts_html(page)
    if facts:
        sections.append({"type": "html", "html": facts})
    if page["differences"]:
        lead = "Not every item is the same:"
        sections.append(
            {
                "type": "callout",
                "kind": "warn",
                "text": "\n".join([lead, *page["differences"]]),
                "html": "<br>".join([lead, *page["difference_html"]]),
            }
        )
    if page["items"]:
        sections.append(_heading(f"{len(page['items'])} items, one sign-off"))
        sections.append({"type": "table", "rows": page["items"]})
    if page["settings"]:
        sections.append(_heading("Run settings"))
        sections.append({"type": "table", "rows": page["settings"]})
    sections.append(_heading("Code"))
    if page["declared_code"] and not _declared_code_on_page(page):
        sections.append({"type": "table", "rows": page["declared_code"]})
    if page["shared"]:
        units = [item["unit"] for item in page["shared"]]
        sections.append({"type": "links", "title": "Uses shared code", "units": units})
    if not page["code"] and page["kind"] == "step":
        note("warn", "No code file is declared for this step.")
    for view in page["code"]:
        sections.extend(_file_sections(view))
    for usage in page["param_usage"]:
        sections.append(_heading(f"{usage['key']} changed. Lines that use it:", 4))
        rows = [
            {"kind": "same", "line": line["line"], "text": f"{line['path']}: {line['text']}"}
            for line in usage["lines"]
        ]
        if rows:
            sections.append({"type": "html", "html": review_code_html(rows)})
        else:
            sections.append({"type": "text", "text": "Not named in this step's code."})
    if page["outputs"]:
        sections.append(_heading("Outputs"))
        if page["items"]:
            groups: dict[str, list[dict[str, Any]]] = {}
            for output in page["outputs"]:
                groups.setdefault(str(output["item"]), []).append(output)
            listed = [{"title": title, "outputs": items} for title, items in groups.items()]
            sections.append({"type": "output_groups", "groups": listed})
        else:
            sections.append({"type": "outputs", "outputs": page["outputs"]})
    return sections


def review_title_html(page: dict[str, Any]) -> str:
    """A page's title and one-line purpose."""
    import html

    purpose = html.escape(page["purpose"] or "No docstring.")
    title = review_heading_html(html.escape(page["title"]), 2)
    return f"{title}<p style='margin:0 0 .35rem'><em>{purpose}</em></p>"


def review_legend_html(status: dict[str, Any]) -> str:
    """The colored count of each status in the notebook's header."""
    counts: dict[str, int] = {}
    for row in status["units"]:
        shown = review_display_status(row)
        counts[shown] = counts.get(shown, 0) + 1
    pills = "".join(
        f"<span style='background:{color};color:#fff;border-radius:999px;padding:1px 9px;"
        f"font-size:12px;white-space:nowrap'>{name} {counts[name]}</span>"
        for name, color in REVIEW_STATUS_COLORS.items()
        if name in counts
    )
    return f"<div style='display:flex;flex-flow:row wrap;gap:4px 6px'>{pills}</div>"


def _safe_record_path(root: Path, unit: str) -> Path:
    """The record's path, refusing any symlink on the way so a write never follows a link."""
    path = _review_record_path(root, unit)
    current = root
    for part in path.relative_to(root).parts:
        current = current / part
        if current.is_symlink():
            raise RuntimeError(f"Refusing to write a review record through symlink {current}")
    return path


def _review_write_record(root: Path, unit: str, record: dict[str, Any]) -> None:
    path = _safe_record_path(root, unit)
    path.parent.mkdir(parents=True, exist_ok=True)
    # Each writer gets its own exclusively created temp file, so concurrent ticks never publish
    # each other's half-written file. os.replace swaps the entry itself, never a link's target.
    handle, partial = tempfile.mkstemp(prefix=".record.", suffix=".tmp", dir=path.parent)
    try:
        with os.fdopen(handle, "w", encoding="utf-8") as stream:
            stream.write(json.dumps(record, indent=2, sort_keys=True) + "\n")
        os.replace(partial, path)
    finally:
        Path(partial).unlink(missing_ok=True)


def _now() -> str:
    return datetime.now(UTC).isoformat(timespec="seconds").replace("+00:00", "Z")


def _reviewer(root: Path) -> str:
    return _git(root, "config", "user.name") or os.environ.get("USER") or "unknown reviewer"


def record_review(root: Path, unit: str, expected_checksum: str | None = None) -> dict[str, Any]:
    """Record that a person signed off a step or shared file. Only the notebook calls this.

    With expected_checksum, the code must still be what the person saw, so a click on a page
    loaded before the code changed is refused instead of approving code nobody looked at.
    """
    config = _project_config(root)
    rows, problem = _code_review(root, config)
    row = next((item for item in rows if item["unit"] == unit), None)
    if row is None:
        raise RuntimeError(f"Unknown step: {unit}")
    if row["checksum"] is None:
        reason = row.get("why") or problem or "it has no code to review"
        raise RuntimeError(f"{unit} cannot be reviewed: {reason}")
    if expected_checksum is not None and row["checksum"] != expected_checksum:
        raise RuntimeError(f"The code of {unit} changed since this page loaded. Review it again.")
    commit = _git(root, "rev-parse", "HEAD")
    if commit is None:
        raise RuntimeError("A sign-off needs a committed revision")
    # A sign-off always points at a commit that stores exactly the code read, so the next one
    # can show what changed since. Uncommitted code cannot be signed off. That covers the files
    # declaring its command and parameters too.
    # Checked against the commit the record names, not a later HEAD, and the code is hashed
    # again after, so a commit or edit landing meanwhile can never be recorded as read.
    uncommitted = _uncommitted(root, [*row["files"], *row["declared_in"]], commit)
    if uncommitted:
        raise RuntimeError(
            f"Commit the code of {unit} before signing off. Not committed as it is: "
            + ", ".join(uncommitted[:5])
        )
    checksum = _code_checksum(root, row["files"], row["commands"], row["params"], row["shared"])
    if checksum != row["checksum"]:
        raise RuntimeError(f"The code of {unit} changed while signing off. Review it again.")
    record = {
        "schema_version": 2,
        "unit": unit,
        "reviewer": _reviewer(root),
        "commit": commit,
        "code_checksum": row["checksum"],
        "files": row["files"],
        "commands": row["commands"],
        "params": row["params"],
        "shared": row["shared"],
        "code_committed": True,
        "reviewed_at": _now(),
    }
    _review_write_record(root, unit, record)
    return record


def revoke_review(root: Path, unit: str, reason: str = "") -> dict[str, Any]:
    """Withdraw a sign-off. The old record is kept inside the new one, and RELEASE blocks."""
    record, valid = _load_review(root, unit)
    if not valid or record is None or record.get("revoked"):
        raise RuntimeError(f"{unit} has no sign-off to revoke")
    revocation = {
        "schema_version": 2,
        "unit": unit,
        "revoked": True,
        "reason": " ".join(reason.split())[:500],
        "by": _reviewer(root),
        "at": _now(),
        "previous": record,
    }
    _review_write_record(root, unit, revocation)
    return revocation


def pending_reviews(root: Path) -> list[str]:
    """Steps and shared files no person has signed off as they are now. Only RELEASE blocks."""
    rows, problem = _code_review(root, _project_config(root))
    if problem:
        return [f"code review could not be checked: {problem}"]
    return [f"{row['unit']}: {row['status']}" for row in rows if row["status"] != "reviewed"]


def _review_git_bytes(root: Path, *arguments: str) -> subprocess.CompletedProcess[bytes]:
    """Run read-only Git plumbing in binary mode so literal CR/LF bytes in paths stay intact."""
    try:
        return subprocess.run(
            ["git", "-c", "core.fsmonitor=false", "--no-replace-objects", *arguments],
            cwd=root,
            check=False,
            capture_output=True,
            timeout=30,
        )
    except subprocess.TimeoutExpired as error:
        raise OSError("Git timed out while reading review policy state") from error


def _decode_git_path(raw: bytes) -> str:
    try:
        return raw.decode("utf-8")
    except UnicodeDecodeError as error:
        raise OSError("Git returned a non-UTF-8 path while inspecting review policy") from error


def _verify_git_commit(root: Path, ref: str) -> tuple[str | None, str]:
    verified = _review_git_bytes(root, "rev-parse", "--verify", f"{ref}^{{commit}}")
    commit = verified.stdout.decode("ascii", "replace").strip()
    if verified.returncode == 0 and re.fullmatch(r"[0-9a-f]{40,64}", commit):
        return commit, ""
    detail = verified.stderr.decode("utf-8", "replace").strip() or "ref is not a commit"
    return None, detail


def _review_policy_base(root: Path, base: str | None) -> tuple[str, str]:
    """Resolve the Git comparison base ref and commit SHA without silent CI fallback."""
    if base is not None:
        candidate = base.strip()
        if (
            not candidate
            or "\x00" in candidate
            or candidate.startswith("-")
            or any(char.isspace() for char in candidate)
        ):
            raise ValueError(f"Invalid Git base ref: {base!r}")
        commit, detail = _verify_git_commit(root, candidate)
        if commit is None:
            raise ValueError(f"Could not resolve base ref {candidate!r}: {detail}")
        return candidate, commit

    github_base = os.environ.get("GITHUB_BASE_REF", "").strip()
    if github_base:
        if (
            "\x00" in github_base
            or github_base.startswith("-")
            or any(char.isspace() for char in github_base)
        ):
            raise RuntimeError(f"Invalid GITHUB_BASE_REF value: {github_base!r}")
        for ref in (f"refs/remotes/origin/{github_base}", f"refs/heads/{github_base}"):
            commit, _ = _verify_git_commit(root, ref)
            if commit is not None:
                return ref, commit
        raise RuntimeError(
            f"Could not resolve GITHUB_BASE_REF {github_base!r}; "
            "fetch the base branch or pass --base <ref>"
        )

    candidates: list[str] = []
    remote_head = _review_git_bytes(
        root, "symbolic-ref", "--quiet", "--short", "refs/remotes/origin/HEAD"
    )
    if remote_head.returncode == 0:
        head_ref = _decode_git_path(remote_head.stdout).strip()
        if head_ref:
            candidates.append(head_ref)
    candidates.extend(
        [
            "refs/remotes/origin/main",
            "refs/heads/main",
            "refs/remotes/origin/master",
            "refs/heads/master",
        ]
    )
    for candidate in dict.fromkeys(candidates):
        commit, _ = _verify_git_commit(root, candidate)
        if commit is not None:
            return candidate, commit
    raise RuntimeError(
        "Could not resolve a default Git base branch; pass --base <ref> or explicit paths"
    )


def _review_policy_git_paths(root: Path, *arguments: str) -> list[str]:
    result = _review_git_bytes(root, *arguments)
    if result.returncode != 0:
        detail = result.stderr.decode("utf-8", "replace").strip() or f"git {' '.join(arguments)}"
        raise RuntimeError(f"Could not inspect changed files: {detail}")
    return [_decode_git_path(item) for item in result.stdout.split(b"\0") if item]


def _git_blob_digest(data: bytes, oid_len: int) -> str:
    hasher = hashlib.sha256() if oid_len == 64 else hashlib.sha1()
    hasher.update(f"blob {len(data)}\0".encode("ascii"))
    hasher.update(data)
    return hasher.hexdigest()


def _git_file_blob_digest(path: Path, oid_len: int) -> str | None:
    """Hash raw file bytes as a Git blob without invoking Git clean filters."""
    hasher = hashlib.sha256() if oid_len == 64 else hashlib.sha1()
    with _open_regular_file(path) as handle:
        size = os.fstat(handle.fileno()).st_size
        hasher.update(f"blob {size}\0".encode("ascii"))
        total = 0
        while chunk := handle.read(65536):
            total += len(chunk)
            hasher.update(chunk)
    return hasher.hexdigest() if total == size else None


def _skip_worktree_paths(root: Path) -> set[str]:
    """Paths marked `skip-worktree` by Git sparse-checkout, read without running filters."""
    listing = _review_git_bytes(root, "ls-files", "-v", "-z")
    if listing.returncode != 0:
        detail = listing.stderr.decode("utf-8", "replace").strip() or "git ls-files -v failed"
        raise RuntimeError(f"Could not inspect Git sparse-checkout flags: {detail}")
    return {
        _decode_git_path(entry[2:])
        for entry in listing.stdout.split(b"\0")
        if len(entry) >= 2 and entry[:2] == b"S "
    }


def _submodule_is_dirty(sub_root: Path, *, depth: int) -> bool:
    """Check for staged, unstaged, or untracked edits inside an initialized submodule."""
    if depth > 4:
        return True
    try:
        staged = _review_policy_git_paths(
            sub_root,
            "diff-index",
            "--cached",
            "--no-renames",
            "--ignore-submodules=none",
            "--name-only",
            "-z",
            "HEAD",
        )
        if staged:
            return True
        untracked = _review_policy_git_paths(
            sub_root, "ls-files", "--others", "--exclude-standard", "-z"
        )
        if untracked:
            return True
        head_paths = set(
            _review_policy_git_paths(sub_root, "ls-tree", "-r", "--name-only", "-z", "HEAD")
        )
        return bool(_review_policy_worktree_changes(sub_root, head_paths, depth=depth))
    except (OSError, RuntimeError):
        return True


def _review_policy_worktree_changes(
    root: Path, merge_base_paths: set[str], *, depth: int = 0
) -> set[str]:
    """Detect unstaged worktree changes against the index using raw bytes (no clean filters)."""
    listing = _review_git_bytes(root, "ls-files", "--stage", "-z")
    if listing.returncode != 0:
        detail = listing.stderr.decode("utf-8", "replace").strip() or "git ls-files --stage failed"
        raise RuntimeError(f"Could not inspect Git index entries: {detail}")

    skip_worktree = _skip_worktree_paths(root)
    filemode_cfg = _review_git_bytes(root, "config", "--bool", "core.filemode")
    check_filemode = os.name != "nt" and filemode_cfg.stdout.strip() != b"false"

    changed: set[str] = set()
    for entry in listing.stdout.split(b"\0"):
        if not entry:
            continue
        meta_raw, sep, path_raw = entry.partition(b"\t")
        if not sep:
            raise RuntimeError("Git returned malformed index entry while inspecting review policy")
        path = _decode_git_path(path_raw)
        meta_parts = meta_raw.decode("ascii", "replace").split(" ")
        if len(meta_parts) != 3:
            raise RuntimeError("Git returned malformed index metadata for review policy")
        mode, oid, stage = meta_parts
        if stage != "0" or path not in merge_base_paths:
            changed.add(path)
            continue
        if len(oid) not in {40, 64}:
            raise RuntimeError(f"Unsupported Git object id length for {path!r}")
        full_path = root / path
        try:
            st = full_path.lstat()
        except FileNotFoundError:
            if path not in skip_worktree:
                changed.add(path)
            continue
        except OSError:
            changed.add(path)
            continue
        if mode == "160000":
            if not stat.S_ISDIR(st.st_mode):
                changed.add(path)
                continue
            if (full_path / ".git").exists():
                sub_head, _ = _verify_git_commit(full_path, "HEAD")
                if sub_head != oid or _submodule_is_dirty(full_path, depth=depth + 1):
                    changed.add(path)
            continue
        if mode == "120000":
            if not stat.S_ISLNK(st.st_mode):
                changed.add(path)
                continue
            try:
                target_bytes = os.fsencode(os.readlink(full_path))
            except OSError:
                changed.add(path)
                continue
            if _git_blob_digest(target_bytes, len(oid)) != oid:
                changed.add(path)
            continue
        if mode in {"100644", "100755"}:
            if not stat.S_ISREG(st.st_mode):
                changed.add(path)
                continue
            if check_filemode and bool(st.st_mode & 0o100) != (mode == "100755"):
                changed.add(path)
                continue
            try:
                digest = _git_file_blob_digest(full_path, len(oid))
            except OSError:
                changed.add(path)
                continue
            if digest != oid:
                changed.add(path)
            continue
        changed.add(path)
    return changed


def _parse_project_config_blob(root: Path, oid: str, *, label: str) -> dict[str, Any]:
    shown = _review_git_bytes(root, "cat-file", "blob", oid)
    if shown.returncode != 0:
        detail = shown.stderr.decode("utf-8", "replace").strip() or "git cat-file failed"
        raise RuntimeError(f"Could not read {label} .astack/project.toml: {detail}")
    try:
        return tomllib.loads(shown.stdout.decode("utf-8"))
    except (UnicodeDecodeError, tomllib.TOMLDecodeError) as error:
        raise ValueError(f"Invalid {label} .astack/project.toml: {error}") from error


def _tree_project_config(root: Path, tree_ref: str, *, label: str) -> dict[str, Any]:
    """Load `.astack/project.toml` blob from a Git commit/tree without following symlinks."""
    listing = _review_git_bytes(root, "ls-tree", "-z", tree_ref, "--", ".astack/project.toml")
    if listing.returncode != 0:
        detail = listing.stderr.decode("utf-8", "replace").strip() or "git ls-tree failed"
        raise RuntimeError(f"Could not inspect {label} .astack/project.toml: {detail}")
    entries = [item for item in listing.stdout.split(b"\0") if item]
    if not entries:
        return {}
    meta_raw, sep, _ = entries[0].partition(b"\t")
    if not sep:
        raise RuntimeError(f"Git returned malformed ls-tree entry for {label} .astack/project.toml")
    parts = meta_raw.decode("ascii", "replace").split(" ")
    if len(parts) != 3:
        raise RuntimeError(
            f"Git returned malformed ls-tree metadata for {label} .astack/project.toml"
        )
    mode, obj_type, oid = parts
    if mode not in {"100644", "100755"} or obj_type != "blob":
        raise OSError(f"{label.capitalize()} .astack/project.toml must be a regular file blob")
    return _parse_project_config_blob(root, oid, label=label)


def _index_project_configs(root: Path) -> list[dict[str, Any]]:
    """Load staged `.astack/project.toml` blob(s) from the Git index without symlinks."""
    listing = _review_git_bytes(root, "ls-files", "--stage", "-z", "--", ".astack/project.toml")
    if listing.returncode != 0:
        detail = listing.stderr.decode("utf-8", "replace").strip() or "git ls-files --stage failed"
        raise RuntimeError(f"Could not inspect index .astack/project.toml: {detail}")
    configs: list[dict[str, Any]] = []
    for entry in listing.stdout.split(b"\0"):
        if not entry:
            continue
        meta_raw, sep, _ = entry.partition(b"\t")
        if not sep:
            raise RuntimeError("Git returned malformed index entry for .astack/project.toml")
        parts = meta_raw.decode("ascii", "replace").split(" ")
        if len(parts) != 3:
            raise RuntimeError("Git returned malformed index metadata for .astack/project.toml")
        mode, oid, _ = parts
        if mode not in {"100644", "100755"}:
            raise OSError("Staged .astack/project.toml must be a regular file blob")
        configs.append(_parse_project_config_blob(root, oid, label="staged"))
    return configs


def _merge_review_policies(
    base_policy: dict[str, Any], candidate_policy: dict[str, Any]
) -> dict[str, Any]:
    """Preserve trusted base scrutiny while allowing candidate config to add requirements."""
    science_required = (
        "scientific_credibility" in base_policy["required_axes"]
        or "scientific_credibility" in candidate_policy["required_axes"]
    )
    return {
        **candidate_policy,
        "risk": max((base_policy["risk"], candidate_policy["risk"]), key=RISK_LEVELS.index),
        "risk_floor": max(
            (base_policy["risk_floor"], candidate_policy["risk_floor"]), key=RISK_LEVELS.index
        ),
        "risk_reasons": list(
            dict.fromkeys([*candidate_policy["risk_reasons"], *base_policy["risk_reasons"]])
        ),
        "protected_paths": sorted(
            set(candidate_policy["protected_paths"]) | set(base_policy["protected_paths"])
        ),
        "scientific_paths": sorted(
            set(candidate_policy["scientific_paths"]) | set(base_policy["scientific_paths"])
        ),
        "matched_scientific_paths": sorted(
            set(candidate_policy["matched_scientific_paths"])
            | set(base_policy["matched_scientific_paths"])
        ),
        "required_axes": ["acceptance", "engineering_reproducibility"]
        + (["scientific_credibility"] if science_required else []),
        "scientific_applicability": "required" if science_required else "interpretive",
    }


def _git_worktree_root(root: Path) -> Path | None:
    top = _review_git_bytes(root, "rev-parse", "--show-toplevel")
    if top.returncode != 0 or not top.stdout:
        return None
    raw = top.stdout.rstrip(b"\r\n")
    return Path(_decode_git_path(raw)).resolve()


def _review_policy_changed_paths(root: Path, base: str | None) -> tuple[str, str, str, list[str]]:
    """Collect committed, staged, unstaged, and untracked changes without running Git filters."""
    toplevel = _git_worktree_root(root)
    if toplevel is None:
        raise RuntimeError("Project is not in a Git worktree; pass explicit paths")
    if toplevel != root:
        raise RuntimeError(
            f"Run review-policy from the Git repository root ({toplevel}), "
            f"not a subdirectory ({root}), or pass explicit paths"
        )
    head_commit, _ = _verify_git_commit(root, "HEAD")
    if head_commit is None:
        raise RuntimeError("Git HEAD has no commits yet; pass explicit paths")
    base_ref, base_commit = _review_policy_base(root, base)
    merge_base_result = _review_git_bytes(root, "merge-base", "HEAD", base_commit)
    merge_base = merge_base_result.stdout.decode("ascii", "replace").strip()
    if merge_base_result.returncode != 0 or not re.fullmatch(r"[0-9a-f]{40,64}", merge_base):
        detail = (
            merge_base_result.stderr.decode("utf-8", "replace").strip()
            or f"no common ancestor with {base_ref}"
        )
        raise RuntimeError(
            f"Could not resolve merge-base between HEAD and {base_ref}: {detail}; "
            "pass --base <ref> or explicit paths"
        )
    changed: set[str] = set()
    # Plumbing `diff-tree` and `diff-index --cached` never touch the worktree or run clean filters.
    # `--no-renames` inspects both old and new paths; `--ignore-submodules=none` keeps gitlinks.
    changed.update(
        _review_policy_git_paths(
            root,
            "diff-tree",
            "-r",
            "--no-renames",
            "--ignore-submodules=none",
            "--name-only",
            "-z",
            merge_base,
            "HEAD",
        )
    )
    changed.update(
        _review_policy_git_paths(
            root,
            "diff-index",
            "--cached",
            "--no-renames",
            "--ignore-submodules=none",
            "--name-only",
            "-z",
            merge_base,
        )
    )
    merge_base_paths = set(
        _review_policy_git_paths(root, "ls-tree", "-r", "--name-only", "-z", merge_base)
    )
    changed.update(_review_policy_worktree_changes(root, merge_base_paths))
    changed.update(
        _review_policy_git_paths(root, "ls-files", "--others", "--exclude-standard", "-z")
    )
    return base_ref, base_commit, merge_base, sorted(changed)


def run_review_policy(
    root: Path,
    *,
    base: str | None = None,
    paths: list[str] | None = None,
    requested_risk: str = "auto",
    scientific_changes: bool = False,
) -> dict[str, Any]:
    """Classify changed or explicit paths with `project_policy.review_policy` and active lenses."""
    root = root.resolve()
    if base is not None and paths is not None:
        raise ValueError("--base cannot be combined with explicit paths")
    if (root / ".astack").is_symlink() or (root / ".astack/project.toml").is_symlink():
        raise OSError("Project configuration must not use a symlink")
    _check_review_config_file(root)
    if paths is not None:
        toplevel = _git_worktree_root(root)
        if toplevel is not None and toplevel != root:
            raise RuntimeError(
                f"Run review-policy from the Git repository root ({toplevel}), "
                f"not a subdirectory ({root})"
            )
        source = "explicit"
        base_ref: str | None = None
        base_commit: str | None = None
        merge_base: str | None = None
        candidate_paths = list(paths)
    else:
        source = "git"
        base_ref, base_commit, merge_base, candidate_paths = _review_policy_changed_paths(
            root, base
        )
    literal = source == "git"
    candidate_policy = review_policy(
        root,
        candidate_paths,
        requested_risk=requested_risk,
        scientific_changes=scientific_changes,
        literal_paths=literal,
    )
    if merge_base is not None:
        # Union merge_base, HEAD, staged index, and worktree configs so neither candidate edits
        # nor sparse-checkout omissions can hide declared scientific review requirements.
        snapshot_configs = [
            _tree_project_config(root, merge_base, label="base"),
            _tree_project_config(root, "HEAD", label="HEAD"),
            *_index_project_configs(root),
        ]
        policy = candidate_policy
        for snapshot_config in snapshot_configs:
            snapshot_policy = review_policy_for_config(
                snapshot_config,
                candidate_paths,
                requested_risk=requested_risk,
                scientific_changes=scientific_changes,
                literal_paths=literal,
            )
            policy = _merge_review_policies(snapshot_policy, policy)
    else:
        policy = candidate_policy
    if literal:
        reported_paths = sorted(set(candidate_paths))
    else:
        reported_paths = sorted(
            {
                "/".join(
                    part for part in item.replace("\\", "/").split("/") if part and part != "."
                )
                for item in candidate_paths
            }
        )
    lenses: list[str] = []
    if policy["protected_paths"]:
        lenses.append("security")
    if "scientific_credibility" in policy["required_axes"]:
        lenses.append("scientific-robustness")
    return {
        **policy,
        "source": source,
        "base": base_ref,
        "base_commit": base_commit,
        "merge_base": merge_base,
        "paths": reported_paths,
        "lenses": lenses,
    }


# --- review_outputs responsibility ---


def _inside_project(root: Path, relative: str) -> Path | None:
    """The real path of an output, or None when it leads outside the project."""
    try:
        real = (root / relative).resolve()
        real.relative_to(root.resolve())
    except (OSError, ValueError, RuntimeError):
        return None
    return real


def _file_facts(path: Path, note: str = "") -> dict[str, Any]:
    size = path.stat().st_size
    text = f"{path.suffix or 'No extension'} file, {size:,} bytes."
    return {"kind": "facts", "text": f"{text} {note}".strip()}


def _png(rows: list[bytes], width: int, height: int) -> bytes:
    """A grayscale PNG, written directly so a preview needs no imaging library."""

    def chunk(kind: bytes, data: bytes) -> bytes:
        crc = struct.pack(">I", zlib.crc32(kind + data) & 0xFFFFFFFF)
        return struct.pack(">I", len(data)) + kind + data + crc

    raw = b"".join(b"\x00" + row for row in rows)
    header = struct.pack(">IIBBBBB", width, height, 8, 0, 0, 0, 0)
    return (
        b"\x89PNG\r\n\x1a\n"
        + chunk(b"IHDR", header)
        + chunk(b"IDAT", zlib.compress(raw))
        + chunk(b"IEND", b"")
    )


def _thumbnail(values: Any) -> tuple[bytes | None, str]:
    """A 2-D array as a PNG scaled to its finite range, and that range in words."""
    import numpy as np

    array = np.ma.filled(np.ma.masked_invalid(np.ma.asarray(values, dtype="float64")), np.nan)
    finite = array[np.isfinite(array)]
    if finite.size == 0:
        return None, "no valid values"
    low, high = float(finite.min()), float(finite.max())
    scaled = np.nan_to_num((array - low) / ((high - low) or 1.0), nan=0.0)
    pixels = (scaled * 255).astype("uint8")
    rows = [row.tobytes() for row in pixels]
    return _png(rows, pixels.shape[1], pixels.shape[0]), f"{low:.4g} to {high:.4g}"


def _raster_preview(path: Path) -> dict[str, Any]:
    try:
        import rasterio
    except ImportError:
        return _file_facts(path, "Install rasterio to preview it.")
    with rasterio.open(path) as source:
        scale = max(1, max(source.width, source.height) // 240)
        shape = (max(1, source.height // scale), max(1, source.width // scale))
        band = source.read(1, out_shape=shape, masked=True)
        facts = [
            (
                f"size: {source.width} × {source.height} px, "
                f"{source.count} band(s), {source.dtypes[0]}"
            ),
            f"CRS: {source.crs}",
            "bounds: " + ", ".join(f"{value:.6g}" for value in source.bounds),
            f"nodata: {source.nodata}",
        ]
    image, value_range = _thumbnail(band)
    facts += [f"band 1 range: {value_range}", f"thumbnail: 1/{scale} scale, grayscale"]
    return {"kind": "raster", "png": image, "facts": facts}


def _netcdf_preview(path: Path) -> dict[str, Any]:
    try:
        import xarray
    except ImportError:
        return _file_facts(path, "Install xarray to preview it.")
    with xarray.open_dataset(path, decode_times=False) as dataset:
        facts = ["dimensions: " + ", ".join(f"{k}={v}" for k, v in dataset.sizes.items())]
        facts += [
            f"{name}: {tuple(item.dims)}, {item.dtype}" for name, item in dataset.data_vars.items()
        ]
        field = next(
            (item for item in dataset.data_vars.values() if item.ndim >= 2 and item.size), None
        )
        image = None
        if field is not None:
            first = field.isel({dim: 0 for dim in field.dims[:-2]})
            step = max(1, max(first.shape) // 240)
            sampled = first.isel({dim: slice(None, None, step) for dim in first.dims})
            image, value_range = _thumbnail(sampled.values)
            facts.append(f"thumbnail: {field.name}, first slice, 1/{step} scale, {value_range}")
    return {"kind": "raster", "png": image, "facts": facts}


def _limited_note(shown: int, total: int | None, limit: int) -> str:
    if total is not None and total > shown:
        return f"First {shown:,} of {total:,} rows"
    if total is None and shown >= limit:
        return f"First {shown:,} rows. The file may have more"
    return f"{shown:,} rows"


def _parquet_preview(path: Path, limit: int) -> dict[str, Any]:
    try:
        import pyarrow as pa
        import pyarrow.parquet as pq
    except ImportError:
        return _file_facts(path, "Install pyarrow to preview it.")
    with pq.ParquetFile(path) as parquet:
        total = parquet.metadata.num_rows
        batches, count = [], 0
        for batch in parquet.iter_batches(batch_size=min(limit, 10_000)):
            batches.append(batch.slice(0, limit - count))
            count += batches[-1].num_rows
            if count >= limit:
                break
        table = pa.Table.from_batches(batches, schema=parquet.schema_arrow)
    return {"kind": "data", "table": table, "note": _limited_note(table.num_rows, total, limit)}


def _delimited_text_preview(path: Path, delimiter: str, limit: int) -> dict[str, Any]:
    import csv
    from itertools import islice

    with path.open(encoding="utf-8", errors="replace", newline="") as handle:
        rows = list(islice(csv.DictReader(handle, delimiter=delimiter), limit + 1))
    more = len(rows) > limit
    rows = rows[:limit]
    note = _limited_note(len(rows), None if more else len(rows), limit)
    return {"kind": "data", "table": rows, "note": f"{note}, read as text"}


def _delimited_preview(path: Path, limit: int) -> dict[str, Any]:
    delimiter = "\t" if path.suffix.lower() == ".tsv" else ","
    try:
        import pyarrow as pa
        import pyarrow.csv as pc
    except ImportError:
        return _delimited_text_preview(path, delimiter, limit)
    options = pc.ParseOptions(delimiter=delimiter)
    batches, count, more = [], 0, False
    try:
        with pc.open_csv(path, parse_options=options) as reader:
            schema = reader.schema
            for batch in reader:
                room = limit - count
                batches.append(batch.slice(0, room))
                count += batches[-1].num_rows
                if batch.num_rows > room:
                    more = True
                    break
    except pa.ArrowInvalid as error:
        if str(error).startswith("In CSV column #"):
            return _delimited_text_preview(path, delimiter, limit)
        raise
    table = pa.Table.from_batches(batches, schema=schema)
    note = _limited_note(table.num_rows, None if more else table.num_rows, limit)
    return {"kind": "data", "table": table, "note": note}


def _text_preview(path: Path) -> dict[str, Any]:
    with _open_regular_file(path) as handle:
        data = handle.read(REVIEW_PREVIEW_TEXT_BYTES + 1)
    cut = len(data) > REVIEW_PREVIEW_TEXT_BYTES
    text = data[:REVIEW_PREVIEW_TEXT_BYTES].decode("utf-8", errors="replace")
    if path.suffix.lower() == ".json" and not cut:
        try:
            parsed = json.loads(text)
        except ValueError:
            parsed = None
        if isinstance(parsed, (dict, list)):
            return {"kind": "json", "data": parsed}
    return {"kind": "text", "text": text + ("\n[Cut short]" if cut else "")}


def review_preview(root: Path, relative: str) -> dict[str, Any]:
    """One output, ready to show. Failing to read it says why and never looks like empty data."""
    path = _inside_project(root, relative)
    if path is None:
        return {"kind": "problem", "text": f"{relative} points outside the project."}
    suffix = path.suffix.lower()
    try:
        mode = path.stat().st_mode
        if stat.S_ISDIR(mode):
            names = sorted(item.relative_to(path).as_posix() for item in path.rglob("*"))
            return {"kind": "text", "text": "\n".join(names[:200]) or "Empty folder."}
        if not stat.S_ISREG(mode):
            return {"kind": "problem", "text": "Cannot preview a special file."}
        if suffix in {".png", ".jpg", ".jpeg", ".gif", ".webp", ".svg"}:
            return {"kind": "image", "path": str(path)}
        if suffix in {".csv", ".tsv"}:
            return _delimited_preview(path, REVIEW_PREVIEW_ROWS)
        if suffix in {".parquet", ".pq"}:
            return _parquet_preview(path, REVIEW_PREVIEW_ROWS)
        if suffix in {".tif", ".tiff"}:
            return _raster_preview(path)
        if suffix in {".nc", ".nc4", ".netcdf"}:
            return _netcdf_preview(path)
        if suffix in {".json", ".md", ".txt", ".yaml", ".yml", ".toml", ".log"}:
            return _text_preview(path)
        return _file_facts(path)
    except FileNotFoundError:
        return {"kind": "problem", "text": "Not produced yet."}
    except Exception as error:  # noqa: BLE001 - a preview must never break the review page.
        return {"kind": "problem", "text": f"Could not read it: {type(error).__name__}: {error}"}


def _chartable_table(table: Any) -> Any | None:
    if isinstance(table, list):
        return None
    try:
        import pyarrow as pa
    except ImportError:
        return None
    if not isinstance(table, pa.Table):
        return None
    columns = [field.name for field in table.schema if not pa.types.is_nested(field.type)]
    return table.select(columns) if columns else None


def _keep(keep: list[Any] | None, element: Any) -> Any:
    """Hold a strong reference to a marimo UI element so its weakref registry entry stays alive."""
    if keep is not None:
        keep.append(element)
    return element


def _draw_preview(mo: Any, root: Path, relative: str, keep: list[Any] | None = None) -> Any:
    shown = review_preview(root, relative)
    kind = shown["kind"]
    if kind == "image":
        return mo.image(src=shown["path"], width=520)
    if kind == "json":
        return mo.json(shown["data"])
    if kind == "data":
        table_ui = _keep(keep, mo.ui.table(shown["table"], selection=None, label=shown["note"]))
        parts = [table_ui]
        chartable = _chartable_table(shown["table"])
        if chartable is not None:
            explore = _keep(keep, mo.lazy(lambda t=chartable: _keep(keep, mo.ui.data_explorer(t))))
            parts.append(mo.accordion({"Explore with charts": explore}))
        return mo.vstack(parts)
    if kind == "raster":
        facts = mo.plain_text("\n".join(shown["facts"]))
        if shown["png"] is None:
            return facts
        return mo.hstack([mo.image(src=shown["png"], width=320), facts], justify="start", gap=2)
    if kind == "problem":
        return mo.callout(mo.plain_text(shown["text"]), kind="warn")
    return mo.plain_text(shown["text"])


def _draw_output(mo: Any, root: Path, output: dict[str, Any], keep: list[Any] | None = None) -> Any:
    """An output and its label. One that is not current says so before it can be judged."""
    label = str(output["label"])
    title = mo.Html(review_file_title(str(output["path"]), label))
    preview = _keep(
        keep,
        mo.lazy(
            lambda path=output["path"]: _draw_preview(mo, root, path, keep),
            show_loading_indicator=True,
        ),
    )
    if label == "current":
        return mo.vstack([title, preview])
    warning = mo.callout(
        mo.plain_text(
            f"This output is {label}, so don't judge it yet. Ask your agent to run just reproduce."
        ),
        kind="warn",
    )
    return mo.vstack([title, warning, mo.accordion({"Show this version anyway": preview})])


def _draw_links(mo: Any, group: dict[str, Any], links: Any) -> Any:
    """A title and its page buttons."""
    buttons = [links[unit] for unit in group["units"]] or [mo.md("_none_")]
    return mo.hstack([mo.md(f"**{group['title']}**"), *buttons], justify="start", wrap=True)


def review_draw(
    mo: Any,
    block: dict[str, Any],
    links: Any,
    root: Path,
    keep: list[Any] | None = None,
) -> Any:
    """Draw one typed block from `review_sections` or `review_report_sections`."""
    kind = block["type"]
    if kind == "html":
        return mo.Html(block["html"])
    if kind == "text":
        return mo.plain_text(block["text"])
    if kind == "callout":
        shown = mo.Html(block["html"]) if block.get("html") else mo.plain_text(block["text"])
        return mo.callout(shown, kind=block["kind"])
    if kind == "fold":
        return mo.accordion({block["title"]: mo.Html(block["html"])})
    if kind == "table":
        return mo.Html(review_table_html(block["rows"]))
    if kind == "outputs":
        drawn = [_draw_output(mo, root, output, keep) for output in block["outputs"]]
        return mo.vstack(drawn)
    if kind == "output_groups":
        return mo.accordion(
            {
                group["title"]: _keep(
                    keep,
                    mo.lazy(
                        lambda items=group["outputs"]: mo.vstack(
                            [_draw_output(mo, root, output, keep) for output in items]
                        )
                    ),
                )
                for group in block["groups"]
            }
        )
    if kind == "claim":
        buttons = [links[unit] for unit in block["units"]]
        return mo.hstack([mo.Html(block["html"]), *buttons], justify="space-between", widths=[5, 1])
    if kind == "link_row":
        row = [_draw_links(mo, group, links) for group in block["groups"]]
        return mo.hstack(row, justify="start", wrap=True, gap=1.5)
    return _draw_links(mo, block, links)


class ReviewActionGate:
    """Accepts one click per render of the action bar.

    marimo gives a re-created control the same id, so a click sent from the old page would run the
    new page's callback. Each render gets a fresh token, and only that token is honored, once.
    """

    def __init__(self) -> None:
        self._token: str | None = None
        self._allowed: frozenset[str] = frozenset()

    def issue(self, allowed: Any) -> str:
        """Start a render. Any token from an earlier render stops working."""
        self._token = secrets.token_urlsafe(16)
        self._allowed = frozenset(allowed)
        return self._token

    def void(self) -> None:
        """The page is about to change, so nothing from the current render may act."""
        self._token = None
        self._allowed = frozenset()

    def voiding(self, setter: Any) -> Any:
        """A state setter that voids the render first, even if a click is already queued."""

        def guarded(update: Any) -> None:
            self.void()
            setter(update)

        return guarded

    def accept(self, event: Any) -> tuple[str, str] | None:
        """The action and reason of a valid click. Stale, replayed or malformed events are None."""
        if not isinstance(event, dict) or self._token is None:
            return None
        token, action, reason = event.get("token"), event.get("action"), event.get("reason")
        if not isinstance(token, str) or not secrets.compare_digest(
            token.encode(), self._token.encode()
        ):
            return None
        if not isinstance(reason, str):
            return None
        if not isinstance(action, str) or action not in self._allowed:
            return None
        self.void()
        return action, reason if action == "confirm" else ""


def review_action_view(
    page: dict[str, Any],
    status: dict[str, Any],
    next_step: str | None,
    revoking: str | None,
    refused: dict[str, str] | None,
) -> dict[str, Any]:
    """What the action bar shows and which actions this render may send."""
    signed = page["status"] == "signed off"
    confirming = signed and revoking == page["unit"]
    why = refused["text"] if refused and refused["unit"] == page["unit"] else ""
    left = max(status["to_sign_off"] - (not signed), 0)
    label = "Commit the code first" if page["blocked"] else "Sign off"
    if page.get("stale"):
        label = "Refresh before signing off"
    allowed = [
        *(["sign"] if not signed and not page["blocked"] else []),
        *(["next"] if next_step is not None else []),
        *(["revoke"] if signed else []),
        *(["confirm", "cancel"] if confirming else []),
        *(["refresh"] if why else []),
    ]
    return {
        "status": page["status"],
        "sign": {"label": "✓ Signed off" if signed else label, "primary": not signed},
        "next": {"label": f"Next → ({left} left)", "primary": signed},
        "can_revoke": signed,
        "confirming": confirming,
        "refused": why,
        "allowed": allowed,
    }


def review_apply_action(
    accepted: tuple[str, str] | None,
    page: dict[str, Any],
    next_step: str | None,
    sign_off: Any,
    revoke: Any,
    set_page: Any,
    set_revoking: Any,
    refresh: Any,
) -> None:
    """Run one accepted click against the page it was rendered for."""
    if accepted is None:
        return
    action, reason = accepted
    if action == "sign":
        if page["checksum"] is not None:
            sign_off(page["unit"], page["checksum"])
    elif action == "next" and next_step is not None:
        set_page(f"unit:{next_step}")
    elif action == "revoke":
        set_revoking(page["unit"])
    elif action == "confirm":
        revoke(page["unit"], reason)
        set_revoking(None)
    elif action == "cancel":
        set_revoking(None)
    elif action == "refresh":
        refresh()


def _action_bar(mo: Any, page: dict[str, Any], action_bar: Any) -> Any:
    """The step's one action bar, and why a sign-off was withdrawn."""
    bar = [action_bar]
    if page["revoked"]:
        gone = page["revoked"]
        text = f"Revoked by {gone['by']} at {gone['at']}. {gone['reason']}"
        bar.append(mo.callout(mo.plain_text(text), kind="danger"))
    return mo.vstack(bar).style(REVIEW_BAR_STYLE)


def review_page_view(
    mo: Any, root: Path, page: dict[str, Any], action_bar: Any, links: Any, keep: list[Any]
) -> Any:
    """A step page. The bar and body share one parent, because a stack would box in sticky."""
    body = [review_draw(mo, block, links, root, keep=keep) for block in review_sections(page)]
    bar = _action_bar(mo, page, action_bar)
    return mo.Html(review_title_html(page) + bar.text + mo.vstack(body).text)


def _owner(path: str, owners: dict[str, str]) -> str | None:
    """The step that produces a path, directly or through an output folder."""
    if path in owners:
        return owners[path]
    return next((unit for out, unit in owners.items() if path.startswith(out + "/")), None)


def _report_sentences(body: str) -> dict[int, str]:
    """Each source line's whole paragraph, so a line break can never cut a claim's meaning."""
    parser = _report_parser()
    sentences: dict[int, str] = {}
    for token in parser.parse(body):
        if token.type != "inline" or not token.children:
            continue
        parts: list[str] = []
        for child in token.children:
            if child.type in {"text", "code_inline"}:
                parts.append(child.content)
            elif child.type in {"softbreak", "hardbreak"}:
                parts.append(" ")
            elif child.type == "image":
                parts.append(parser.renderer.renderInlineAsText(child.children, parser.options, {}))
            elif child.type == "html_inline" and not child.content.startswith("<!--"):
                parts.append(child.content)
        text = "".join(parts).strip()
        if not text:
            continue
        first, last = token.map if token.map else (0, 1)
        for line in range(first + 1, last + 1):
            shown = [sentences.get(line, ""), text]
            sentences[line] = " ".join(part for part in shown if part)
    return sentences


def _report_claims(
    root: Path,
    report: Path,
    source: str,
    state: dict[str, Any],
    labels: dict[str, str],
    owners: dict[str, str],
) -> list[dict[str, Any]]:
    """Each figure and cited number, its evidence, the evidence's label and its step."""
    lines = source.split("\n")
    skip, _ = _report_front_matter(lines)
    body = "\n".join([""] * skip + lines[skip:])
    sentences = _report_sentences(body)
    claims: list[dict[str, Any]] = []
    for item, (kind, line, destination, text) in enumerate(_report_items(body)):
        if kind not in {"figure", "link"} or (kind == "link" and not _is_cited_value(text)):
            continue
        target = str(destination or "")
        location = unquote(target.partition("#")[0].split("?", 1)[0])
        relative = None
        if location and not REPORT_URL_SCHEME.match(target) and not target.startswith("//"):
            joined = posixpath.normpath(posixpath.join(report.parent.as_posix(), location))
            try:
                relative = Path(joined).resolve().relative_to(root.resolve()).as_posix()
            except (OSError, ValueError):
                relative = None
        covered = evidence_label(state, relative) if relative else None
        if covered is not None:
            label = str(covered.get("label", "unknown"))
            matched = str(covered.get("path", relative))
            unit = _owner(matched, owners) or (_owner(relative, owners) if relative else None)
        else:
            label = labels.get(relative or "", "unknown")
            unit = _owner(relative, owners) if relative else None
        claims.append(
            {
                "item": item,
                "line": line,
                "kind": "figure" if kind == "figure" else "number",
                "text": text,
                "context": sentences.get(line, ""),
                "evidence": relative or target,
                "label": label,
                "unit": unit,
            }
        )
    return claims


def _attach_findings(
    claims: list[dict[str, Any]], problems: list[dict[str, Any]], notes: list[dict[str, Any]]
) -> dict[str, list[dict[str, Any]]]:
    """Put each finding on the one claim it came from and sort failures, notes, then passing.

    Findings carry the parsed item that produced them, so several claims on one line stay apart.
    Anything without a claim is returned, so the page can show it at report level.
    """
    by_item = {claim["item"]: claim for claim in claims}
    loose: dict[str, list[dict[str, Any]]] = {"problems": [], "notes": []}
    for claim in claims:
        claim["problems"], claim["notes"] = [], []
    for key, findings in (("problems", problems), ("notes", notes)):
        for finding in findings:
            owner = by_item.get(finding.get("item"))
            (owner[key] if owner else loose[key]).append(finding)
    claims.sort(
        key=lambda c: (0 if c["problems"] else 1 if c["notes"] else 2, c["line"], c["item"])
    )
    return loose


def _claim_verdict(claim: dict[str, Any]) -> str:
    """A claim with a finding names it, so a wrong number can never read as `current`."""
    kinds = [str(item["kind"]).replace("-", " ") for item in [*claim["problems"], *claim["notes"]]]
    return ", ".join(dict.fromkeys(kinds)) or str(claim["label"])


def review_reports(root: Path, status: dict[str, Any], labels: dict[str, str]) -> dict[str, Any]:
    """Every report's claims with their live labels. Report files are only ever read."""
    from io import TextIOWrapper

    if markdown_it is None or yaml is None:
        return {"problem": "Reading reports needs markdown-it-py and PyYAML.", "reports": []}
    owners = {
        path: str(row["unit"])
        for row in status["units"]
        for item in row["items"]
        for path in item["outputs"]
    }
    previous = _READ_ONLY["on"]
    _READ_ONLY["on"] = True
    try:
        state = _review_output_status(root)
        reports = []
        for path in _report_paths(root, []):
            try:
                # One read, so a finding's item always indexes the claims parsed from it.
                resolved = path.resolve()
                with TextIOWrapper(_open_regular_file(resolved), encoding="utf-8") as handle:
                    source = handle.read()
                checked = _check_report_text(root, resolved, source, state)
                claims = _report_claims(root, resolved, source, state, labels, owners)
            except (OSError, UnicodeDecodeError) as error:
                try:
                    display = path.relative_to(root).as_posix()
                except ValueError:
                    display = path.as_posix()
                checked = {
                    "path": display,
                    "final": False,
                    "problems": [{"line": 0, "kind": "unreadable", "message": str(error)}],
                    "evidence_notes": [],
                }
                claims = []
            notes = checked.get("evidence_notes", [])
            loose = _attach_findings(claims, checked["problems"], notes)
            reports.append(
                {
                    "path": checked["path"],
                    "final": checked["final"],
                    "problems": checked["problems"],
                    "notes": notes,
                    "claims": claims,
                    "loose_problems": loose["problems"],
                    "loose_notes": loose["notes"],
                    "attention": sum(bool(c["problems"] or c["notes"]) for c in claims),
                }
            )
    finally:
        _READ_ONLY["on"] = previous
    return {"problem": None, "reports": reports}


def review_report_picker(mo: Any, found: dict[str, Any]) -> Any:
    options = {report["path"]: i for i, report in enumerate(found["reports"])}
    if len(options) > 1:
        return mo.ui.dropdown(options, value=next(iter(options)), label="Report file")
    return None


def review_claim_page_picker(mo: Any, found: dict[str, Any], report_index: int) -> Any:
    reports = found["reports"]
    count = len(reports[report_index]["claims"]) if reports else 0
    size = REVIEW_CLAIMS_PER_PAGE
    if count <= size:
        return None
    options = {
        f"{start + 1}–{min(start + size, count)} of {count}": page
        for page, start in enumerate(range(0, count, size))
    }
    return mo.ui.dropdown(options, value=next(iter(options)), label="Claims")


def review_report_sections(
    root: Path, status: dict[str, Any], labels: dict[str, str]
) -> list[dict[str, Any]]:
    """The unpaged entry point used by review notebooks copied into existing projects."""
    found = review_reports(root, status, labels)
    intro = "Each cited figure and number, its evidence's label now, and the step that made it."
    blocks: list[dict[str, Any]] = [
        {
            "type": "html",
            "html": (
                f"{review_heading_html('Report', 2)}"
                f"<p style='margin:0 0 .35rem'><em>{intro} Reports are never changed.</em></p>"
            ),
        }
    ]
    if found["problem"] or not found["reports"]:
        return [*blocks, *review_report_page(found)]
    for index, report in enumerate(found["reports"]):
        blocks.extend(_review_report_blocks(report, report["claims"], index))
    return blocks


def review_report_page(
    found: dict[str, Any], report_index: int = 0, claim_page: int = 0
) -> list[dict[str, Any]]:
    """Render one page of the selected report, with zero-based report and page indices."""
    if found["problem"]:
        return [{"type": "callout", "kind": "warn", "text": found["problem"]}]
    if not found["reports"]:
        return [{"type": "text", "text": "No reports under reports/."}]
    report = found["reports"][report_index]
    start = claim_page * REVIEW_CLAIMS_PER_PAGE
    claims = report["claims"][start : start + REVIEW_CLAIMS_PER_PAGE]
    return _review_report_blocks(report, claims, report_index)


def _review_report_blocks(
    report: dict[str, Any], claims: list[dict[str, Any]], report_index: int
) -> list[dict[str, Any]]:
    import html

    state = "final" if report["final"] else "draft"
    blocks: list[dict[str, Any]] = [
        {"type": "html", "html": review_file_title(report["path"], state, 3)}
    ]
    loose = len(report["loose_problems"]) + len(report["loose_notes"])
    if report["claims"]:
        count = f"{report['attention']} of {len(report['claims'])} need attention"
        more = f" · {loose} more not tied to one claim" if loose else ""
        blocks.append({"type": "html", "html": f"<p><strong>{count}</strong>{more}</p>"})
    for key, kind in (("loose_problems", "danger"), ("loose_notes", "info")):
        if report[key]:
            text = "\n".join(f"Line {p['line']}: {p['message']}" for p in report[key])
            blocks.append({"type": "callout", "kind": kind, "text": text})
    if not report["claims"]:
        blocks.append({"type": "text", "text": "No cited figures or numbers."})

    contexts: dict[str, int] = {}
    for claim in claims:
        findings = "".join(
            f"<br><strong>{name}:</strong> {html.escape(str(item['message']))}"
            for name, key in (("Problem", "problems"), ("Note", "notes"))
            for item in claim[key]
        )
        cited = claim["text"] or claim["kind"]
        context = claim["context"]
        sentence = ""
        if context and context != cited:
            if len(context) > REVIEW_INLINE_CONTEXT_CHARS:
                number = contexts.setdefault(context, len(contexts) + 1)
                sentence = (
                    f'<button type="button" popovertarget="review-context-{report_index}-{number}" '
                    f'style="text-decoration:underline">Full context {number}</button><br>'
                )
            else:
                sentence = f"{html.escape(context)}<br>"
        body = (
            f"<p style='margin:0'><strong>{html.escape(cited)}</strong>"
            f" · line {claim['line']}<br>{sentence}"
            f"<code>{html.escape(claim['evidence'])}</code> · "
            f"<strong>{html.escape(_claim_verdict(claim))}</strong>{findings}</p>"
        )
        units = [claim["unit"]] if claim["unit"] else []
        blocks.append({"type": "claim", "html": body, "units": units})
    for context, number in contexts.items():
        label = f"Full context {number}"
        body = (
            f'<div id="review-context-{report_index}-{number}" popover="auto" tabindex="0" '
            f'role="region" aria-label="{label}" '
            f'style="max-width:min(72ch, 90vw); max-height:45vh; overflow:auto; '
            f"overflow-wrap:anywhere; padding:1rem; background:Canvas; color:CanvasText; "
            f'border:1px solid GrayText">{html.escape(context)}</div>'
        )
        blocks.append({"type": "html", "html": body})
    return blocks


def review_block_units(blocks: list[dict[str, Any]]) -> list[str]:
    """Every unit these blocks link to, once, so the notebook can make one button for each."""
    return list(dict.fromkeys(unit for block in blocks for unit in block.get("units", [])))


def review_route(target: str) -> str:
    """Normalize an initial page name into a non-colliding `page:` or `unit:` route."""
    if target.startswith(("page:", "unit:")):
        return target
    return f"page:{target}" if target in {"overview", "report"} else f"unit:{target}"


# --- cli responsibility ---


def _parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="workflow.py", description="Project workflow checks and helpers, run from the root."
    )
    # A metavar keeps the hidden compatibility alias out of the command list.
    subparsers = parser.add_subparsers(dest="command", required=True, metavar="COMMAND")
    upgrade_parser = subparsers.add_parser(
        "upgrade",
        help="Plan or apply an upgrade to a published astack release (defaults to latest stable)",
    )
    upgrade_parser.add_argument(
        "release",
        nargs="?",
        default=None,
        help="Exact published release tag such as v1.2.1 (defaults to latest stable release)",
    )
    upgrade_parser.add_argument("--apply", action="store_true")
    upgrade_parser.add_argument(
        "--approve-plan", help="Exact dry-run plan_digest to apply (implies --apply)"
    )
    audit_parser = subparsers.add_parser(
        "audit", help="Check workflow conformance, provenance and evidence (just ship-ready)"
    )
    output_contract_parser = subparsers.add_parser(
        "output-contract", help="Read the declared scientific output contract summary"
    )
    output_contract_parser.add_argument(
        "--analysis", help="One analysis from the registry's analyses (default: whole project)"
    )
    # `--work-unit` was this option's old name.
    output_contract_parser.add_argument("--work-unit", dest="analysis", help=argparse.SUPPRESS)
    audit_parser.add_argument("--format", choices=["json", "text"], default="text")
    audit_parser.add_argument(
        "--run-tools", action="store_true", help="Also run the project's configured checks"
    )
    audit_parser.add_argument(
        "--strict", action="store_true", help="Exit non-zero unless the project is ship-ready"
    )
    audit_parser.add_argument(
        "--analysis",
        help="Check this registry analysis: it must exist and its confirmation must be current",
    )
    # `--output-scope` was this option's old name.
    audit_parser.add_argument("--output-scope", dest="analysis", help=argparse.SUPPRESS)
    audit_parser.add_argument(
        "--ci",
        action="store_true",
        help="Explicit limited engineering/metadata CI, not scientific release proof",
    )
    validation_parser = subparsers.add_parser(
        "validate", help="Run one declared validation tier from .astack/project.toml"
    )
    validation_parser.add_argument("tier", choices=("check", *VALIDATION_TIERS))

    file_audit_help = "File an audit report as a GitHub issue, or keep it local"
    file_audit_parser = subparsers.add_parser("file-audit", help=file_audit_help)
    # `publish` was this command's old name. It never published the project; see publish-public.
    legacy_parser = subparsers.add_parser("publish", description=file_audit_help)
    for audit_report_parser in (file_audit_parser, legacy_parser):
        audit_report_parser.add_argument("--report", type=Path, required=True)
        audit_report_parser.add_argument("--commit", required=True)
        audit_report_parser.add_argument("--scope", choices=sorted(ALLOWED_SCOPES), required=True)
        audit_report_parser.add_argument(
            "--to",
            dest="publish",
            choices=["auto", "github", "local", "none"],
            default="auto",
            help="Where the report goes. auto files an issue when GitHub is available",
        )
        # `--publish` was the destination option's old name.
        audit_report_parser.add_argument(
            "--publish",
            dest="publish",
            choices=["auto", "github", "local", "none"],
            help=argparse.SUPPRESS,
        )
        audit_report_parser.add_argument("--actionable-count", type=int, required=True)
        audit_report_parser.add_argument("--remove-on-success", action="store_true")

    share_raw_parser = subparsers.add_parser(
        "share-raw",
        help="Link immutable raw inputs from the canonical checkout into this linked worktree",
    )
    share_raw_parser.add_argument("--apply", action="store_true")
    reproduce_parser = subparsers.add_parser(
        "reproduce", help="Run the declared reproduction and record the run (just reproduce)"
    )
    reproduce_parser.add_argument(
        "--promote",
        action="store_true",
        help="Also write a durable run record under evidence/ or reports/qa/.",
    )
    reproduce_parser.add_argument(
        "--verify",
        action="store_true",
        help="Fail unless the rerun matches a promoted reference record.",
    )
    subparsers.add_parser(
        "acquire", help="Run the declared [acquisition] command to obtain inputs (just acquire)"
    )
    export_parser = subparsers.add_parser(
        "export-public",
        help="Write an allowlisted, history-free public copy of the committed project",
    )
    export_parser.add_argument("--out", type=Path, required=True)
    verify_source_parser = subparsers.add_parser(
        "verify-source",
        help="Hash bytes retrieved for an external source and write its verification record",
    )
    verify_source_parser.add_argument("source_id")
    verify_source_parser.add_argument("retrieved", type=Path)
    checksum_parser = subparsers.add_parser(
        "checksum",
        help="Print the raw_checksum value for a file (sha256) or directory (sha256-tree-v2)",
    )
    checksum_parser.add_argument("path", type=Path)
    report_check_parser = subparsers.add_parser(
        "report-check",
        help="Check that report figures and cited numbers point at evidence (just report-check)",
    )
    report_check_parser.add_argument(
        "reports", nargs="*", type=Path, help="Reports to check (default: every report in reports/)"
    )
    subparsers.add_parser(
        "outputs", help="Label each pipeline output current, outdated, missing or unknown"
    )
    review_parser = subparsers.add_parser(
        "review-status",
        help="Show what the review notebook shows: each pipeline step and its sign-off",
    )
    review_parser.add_argument(
        "--require-reviewed",
        action="store_true",
        help="Fail unless a person signed off every step and shared file as it is now (RELEASE)",
    )
    review_policy_parser = subparsers.add_parser(
        "review-policy",
        help="Classify changed or explicit paths for review risk, paths, and required axes",
    )
    review_policy_parser.add_argument(
        "--root",
        type=Path,
        help="Target project checkout root to inspect as data (default: current directory)",
    )
    review_policy_parser.add_argument(
        "--base",
        help="Git base ref or commit to compare against (default: resolved default/CI base branch)",
    )
    review_policy_parser.add_argument(
        "--risk",
        choices=("auto", "low", "medium", "high", "critical"),
        default="auto",
        help="Optional requested risk floor (cannot lower the computed floor)",
    )
    review_policy_parser.add_argument(
        "--scientific-changes",
        action="store_true",
        help="Explicitly mark the changes as touching scientific claims or analysis",
    )
    review_policy_parser.add_argument(
        "paths",
        nargs="*",
        help="Explicit relative paths to classify instead of inspecting Git changes",
    )
    subparsers.add_parser("dvc-status", help="Show DVC pipeline status (DVC projects only)")
    dvc_cache_parser = subparsers.add_parser(
        "dvc-cache", help="Inspect or clean this project's DVC cache (DVC projects only)"
    )
    dvc_cache_commands = dvc_cache_parser.add_subparsers(dest="dvc_cache_command", required=True)
    dvc_cache_commands.add_parser("status")
    dvc_cache_gc = dvc_cache_commands.add_parser("gc")
    dvc_cache_gc.add_argument("--apply", action="store_true")
    return parser


def _strict_ready(result: dict[str, Any]) -> bool:
    """Exploratory work cannot claim reproduction, so it is gated on its software checks."""
    verdicts = result["verdicts"]
    reproducibility = str(verdicts["computational_reproducibility"])
    if result.get("analysis_stage", "material") == "material":
        reproducibility_ready = reproducibility == "pass"
    else:
        reproducibility_ready = (
            reproducibility != "fail" and str(verdicts.get("software_checks")) == "pass"
        )
    return (
        str(verdicts["workflow_conformance"]) == "pass"
        and reproducibility_ready
        and str(verdicts["release_readiness"]) != "fail"
    )


def _context_command(args: argparse.Namespace) -> str:
    parts = [args.command]
    value = getattr(args, "dvc_cache_command", None)
    if value:
        parts.append(str(value))
    return " ".join(parts)


def _emit_result(result: object, cwd: Path, *, command: str) -> None:
    del cwd, command
    payload = dict(result) if isinstance(result, dict) else {"result": result}
    print(json.dumps(payload, indent=2, sort_keys=True))


def _with_errors(function: Any) -> Any:
    def wrapped() -> None:
        try:
            function()
        except SystemExit:
            raise
        except Exception as exc:
            print(
                json.dumps(
                    {"error": {"type": type(exc).__name__, "message": str(exc)}},
                    indent=2,
                    sort_keys=True,
                ),
                file=sys.stderr,
            )
            raise SystemExit(1) from exc

    return wrapped


@_with_errors
def main() -> None:
    args = _parser().parse_args()
    if args.command == "upgrade":
        try:
            from release_upgrade import upgrade_release  # type: ignore[import-not-found]
        except ImportError:
            from astack.release_upgrade import upgrade_release

        # Check `is not None` so `--approve-plan ""` still attempts apply and fails closed.
        result = upgrade_release(
            Path.cwd(),
            args.release,
            apply=bool(args.apply or args.approve_plan is not None),
            approve_plan=args.approve_plan,
        )
        _emit_result(result, Path.cwd(), command="upgrade")
        return
    if args.command == "output-contract":
        print(
            json.dumps(output_contract_summary(Path.cwd(), args.analysis), indent=2, sort_keys=True)
        )
        return
    if args.command == "audit":
        cwd = Path.cwd().resolve()
        if args.ci and not (args.strict and args.run_tools):
            raise SystemExit("--ci requires --strict --run-tools")
        options: dict[str, Any] = {"ci": True} if args.ci else {}
        if args.analysis:
            options["output_scope"] = args.analysis
        result = audit(cwd, run_tools=args.run_tools, strict=args.strict, **options)
        if args.format == "json":
            _emit_result(result, cwd, command=_context_command(args))
        else:
            print("Workflow audit")
            for key, value in result["verdicts"].items():
                print(f"- {key}: {value}")
            for finding in result["findings"]:
                print(
                    f"- {finding['priority']} [{finding['area']}] "
                    f"{finding['message']} ({finding['evidence']})"
                )
        if args.ci:
            if args.format == "text":
                print(
                    "Limited CI: source identity/reproduction NOT VERIFIED. "
                    "Strict local ship-ready required."
                )
            if result.get("ci_validation", {}).get("status") != "pass":
                raise SystemExit(1)
        elif args.strict and not _strict_ready(result):
            raise SystemExit(1)
        return
    if args.command == "validate":
        cwd = Path.cwd().resolve()
        _emit_result(run_validation(cwd, args.tier), cwd, command=_context_command(args))
        return
    if args.command == "share-raw":
        cwd = Path.cwd().resolve()
        _emit_result(share_raw_inputs(cwd, apply=args.apply), cwd, command=_context_command(args))
        return
    if args.command == "reproduce":
        cwd = Path.cwd().resolve()
        _ensure_cache_ignored(cwd)
        result = run_reproduction(cwd, promote=args.promote, verify=args.verify)
        _emit_result(result, cwd, command=_context_command(args))
        if result["status"] == "mismatch" or (args.verify and result["status"] != "verified"):
            raise SystemExit(1)
        return
    if args.command == "acquire":
        cwd = Path.cwd().resolve()
        _emit_result(run_acquisition(cwd), cwd, command=_context_command(args))
        return
    if args.command == "export-public":
        cwd = Path.cwd().resolve()
        _emit_result(export_public(cwd, args.out), cwd, command=_context_command(args))
        return
    if args.command == "verify-source":
        cwd = Path.cwd().resolve()
        result = verify_source(cwd, args.source_id, args.retrieved.resolve())
        _emit_result(result, cwd, command=_context_command(args))
        return
    if args.command == "checksum":
        cwd = Path.cwd().resolve()
        _emit_result(source_checksum(args.path), cwd, command=_context_command(args))
        return
    if args.command == "report-check":
        cwd = Path.cwd().resolve()
        result = report_check(cwd, args.reports)
        _emit_result(result, cwd, command=_context_command(args))
        if result["status"] in {"failed", "unavailable"}:
            raise SystemExit(1)
        return
    if args.command == "review-status":
        cwd = Path.cwd().resolve()
        if args.require_reviewed:
            pending = pending_reviews(cwd)
            _emit_result(
                {"status": "failed" if pending else "passed", "pending": pending},
                cwd,
                command=_context_command(args),
            )
            if pending:
                raise SystemExit(1)
            return
        _emit_result(review_status(cwd), cwd, command=_context_command(args))
        return
    if args.command == "review-policy":
        target_root = (args.root or Path.cwd()).resolve()
        result = run_review_policy(
            target_root,
            base=args.base,
            paths=args.paths or None,
            requested_risk=args.risk,
            scientific_changes=args.scientific_changes,
        )
        _emit_result(result, target_root, command=_context_command(args))
        return
    if args.command == "outputs":
        cwd = Path.cwd().resolve()
        _emit_result(output_status(cwd), cwd, command=_context_command(args))
        return
    if args.command == "dvc-status":
        cwd = Path.cwd().resolve()
        _emit_result(run_dvc_status(cwd), cwd, command=_context_command(args))
        return
    if args.command == "dvc-cache":
        root = Path.cwd().resolve()
        result = (
            run_dvc_cache_status(root)
            if args.dvc_cache_command == "status"
            else run_dvc_cache_gc(root, apply=args.apply)
        )
        _emit_result(result, root, command=_context_command(args))
        return
    if args.command not in {"file-audit", "publish"}:
        raise SystemExit(f"Unknown command: {args.command}")
    cwd = Path.cwd().resolve()
    result = publish_audit(
        cwd,
        args.report,
        commit=args.commit,
        scope=args.scope,
        publish=args.publish,
        actionable_count=args.actionable_count,
        remove_on_success=args.remove_on_success,
    )
    _emit_result(result, cwd, command=_context_command(args))
    if args.publish == "github" and result["status"] != "github":
        raise SystemExit(1)


if __name__ == "__main__":
    main()
